  (md5('cts-v0.2.1-standard-9')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-track-3')::uuid, 9, 'تقييم الشراكات'),
  (md5('cts-v0.2.1-standard-10')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-track-4')::uuid, 10, 'تخطيط البرامج'),
  (md5('cts-v0.2.1-standard-11')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-track-4')::uuid, 11, 'تقديم الخدمات'),
