  (md5('cts-v0.2.1-standard-14')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-track-5')::uuid, 14, 'نتائج العمليات'),
  (md5('cts-v0.2.1-standard-15')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-track-5')::uuid, 15, 'نتائج المستفيدين')
insert into public.indicators (id, tool_version_id, standard_id, number, text) values
  (md5('cts-v0.2.1-indicator-1')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-1')::uuid, 1, 'تجمع المنظمة بانتظام معلومات عن احتياجات المستفيدين وتوقعاتهم من البرامج والخدمات، وتقوم بتحليلها والاستفادة من نتائجها.'),
  (md5('cts-v0.2.1-indicator-2')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-1')::uuid, 2, 'تملك المنظمة سجلاً موثقاً بالقوانين والأنظمة المتعلقة بالمستفيدين والخدمات، وتستطيع شرح تأثيرها على برامجها وخدماتها.'),
  (md5('cts-v0.2.1-indicator-3')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-1')::uuid, 3, 'تُحلل المنظمة المتطلبات الفنية اللازمة للبرامج والخدمات، لتحديد معايير تقديمها والموارد الضرورية لتلبية احتياجات المستفيدين.'),
  (md5('cts-v0.2.1-indicator-4')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-1')::uuid, 4, 'تُحدد المنظمة جميع الجهات المعنية بخدماتها وبرامجها، وتُحلل مدى تأثيرهم، وتدرس توقعاتهم واحتياجاتهم، وتضعها في الاعتبار عند التخطيط وتقديم الخدمات.'),
  (md5('cts-v0.2.1-indicator-5')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-1')::uuid, 5, 'تُجري المنظمة تقييماً سنوياً لقدرتها على تلبية متطلبات تقديم برامج وخدمات تُناسب احتياجات المستفيدين وتوقعات الجهات المعنية.'),
  (md5('cts-v0.2.1-indicator-6')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-1')::uuid, 6, 'تُحلل المنظمة تقارير إنجاز البرامج والخدمات، وتستخدم الدروس المستفادة وآراء الجهات المعنية في تطويرها وتحسينها.'),
  (md5('cts-v0.2.1-indicator-7')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-2')::uuid, 7, 'تملك المنظمة وصفاً واضحاً ودقيقاً وموثقاً  للفئات المستفيدة من برامجها وخدماتها وتحدد الخدمات المقدمة لكل فئة.'),
  (md5('cts-v0.2.1-indicator-8')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-2')::uuid, 8, 'تحدد المنظمة هيكلية برامجها وخدماتها بدقة، موضحة العلاقة بينها، لضمان التكامل والانسجام في تحقيق الأهداف المشتركة.'),
  (md5('cts-v0.2.1-indicator-9')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-2')::uuid, 9, 'تطوّر المنظمة وصفاً شاملاً لكل برنامج/خدمة يتضمن معلومات عن أهدافه، والمخرجات والنتائج المتوقعة، والفئة المستهدفة.'),
  (md5('cts-v0.2.1-indicator-10')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-2')::uuid, 10, 'تتضمن وثائق وصف البرامج/الخدمات مؤشرات واقعية لقياس مدى تحقيق النتائج على المستفيدين وتحدد المسؤوليات وطريقة جمع البيانات لكل مؤشر.'),
  (md5('cts-v0.2.1-indicator-11')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-3')::uuid, 11, 'تُحدد المنظمة المخاطر التي قد تُؤثر على تقديم البرامج والخدمات وتحقيق النتائج، وتُقيّم مدى تأثير كل خطر.'),
  (md5('cts-v0.2.1-indicator-12')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-3')::uuid, 12, 'تضع المنظمة خطة لإدارة المخاطر، وتُحدد إجراءاتٍ مناسبة لمنعها أو تقليل تأثيرها، وتُحدد المسؤول عن تنفيذ كل إجراء.'),
  (md5('cts-v0.2.1-indicator-13')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-3')::uuid, 13, 'تُراجع المنظمة إجراءات التعامل مع المخاطر باستمرار وتُحدّثها بناءً على نتائج المراجعة والتغيرات في بيئة العمل.'),
  (md5('cts-v0.2.1-indicator-14')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-4')::uuid, 14, 'تصمم المنظمة هيكلاً تنظيماً يعزز قدرتها على تحقيق أهدافها الاستراتيجية، وتُجري تحليلاً دقيقاً وشاملاً لجميع عملياتها الرئيسية لضمان تحقيق الفاعلية والتوافق بين الهيكل التنظيمي وتلك العمليات.'),
  (md5('cts-v0.2.1-indicator-15')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-4')::uuid, 15, 'تُراجع المنظمة هيكلها التنظيمي وتُحدّثه بشكل دوري، لمواكبة التغيرات في الأهداف والاستراتيجيات والمتطلبات.'),
  (md5('cts-v0.2.1-indicator-16')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-4')::uuid, 16, 'تُحدد المنظمة بوضوح الجدارات الفنية اللازمة لإنجاز مهام تنفيذ البرامج وتقديم الخدمات للمستفيدين.'),
  (md5('cts-v0.2.1-indicator-17')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-4')::uuid, 17, 'تضع المنظمة توصيفات وظيفية لجميع الوظائف الفنية في هيكلها التنظيمي، وتضمن أن مهام ومسؤوليات كل وظيفة، ومتطلبات شغلها، تتوافق مع الأنظمة والمعايير المُعتمدة في مجال عملها.'),
  (md5('cts-v0.2.1-indicator-18')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-4')::uuid, 18, 'تُخطط المنظمة لاحتياجاتها من الموظفين (عددًا وكفاءةً)، بما يتوافق مع حجم العمل والمعايير المُعتمدة في مجال عملها.'),
  (md5('cts-v0.2.1-indicator-19')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-5')::uuid, 19, 'لدى المنظمة عدد كافٍ من الموظفين والمتطوعين المؤهلين لتنفيذ البرامج والخدمات وتحقيق النتائج المرجوة.'),
  (md5('cts-v0.2.1-indicator-20')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-5')::uuid, 20, 'تُصمم المنظمة وتُنفذ برامج تهيئة وتوعية فعّالة للموظفين والمتطوعين، وتتأكد من فهمهم لمتطلبات تقديم الخدمات للمستفيدين والتواصل معهم والحفاظ على سلامتهم.'),
  (md5('cts-v0.2.1-indicator-21')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-5')::uuid, 21, 'تُجري المنظمة تحليلاً دورياً لاحتياجات التعلّم والتطوير للموظفين والمتطوعين، وتخطط برامج التعلم والتطوير استناداً إلى نتائج التحليل.'),
  (md5('cts-v0.2.1-indicator-22')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-5')::uuid, 22, 'تنفذ  المنظمة برامج التعلّم والتطوير  المخططة بما يضمن فرصاً متساوية لجميع العاملين والمتطوعين، وتحتفظ بمعلومات وسجلات مُحدّثة.'),
  (md5('cts-v0.2.1-indicator-23')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-5')::uuid, 23, 'تطبق المنظمة سياسات وإجراءات فعّالة لضمان سلامة الموظفين والمتطوعين أثناء العمل، ويتمتع الموظفون بالمعرفة والمهارات اللازمة للتعامل مع المخاطر المُتعلقة بالسلامة.'),
  (md5('cts-v0.2.1-indicator-24')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-6')::uuid, 24, 'تُحدد المنظمة مستويات الأداء والمهام المطلوبة من كل موظف ومتطوع، ويتمتع الجميع بفهم واضح لهذه المهام.'),
  (md5('cts-v0.2.1-indicator-25')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-6')::uuid, 25, 'تُقيّم المنظمة أداء موظفيها ومتطوعيها بانتظام باستخدام منهجية مُحددة وملائمة، وتُناقش نتائج التقييم معهم.'),
  (md5('cts-v0.2.1-indicator-26')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-6')::uuid, 26, 'تستخدم المنظمة نتائج تقييم الأداء لتقديم التوجيه والدعم اللازمين للموظفين والمتطوعين، وتوفير الموارد التي تُمكّنهم من إنجاز مهامهم وتحقيق النتائج المرجوة.'),
  (md5('cts-v0.2.1-indicator-27')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-6')::uuid, 27, 'تُعدّ المنظمة تقارير تحليلية عن أداء الموظفين والمتطوعين، وتُشاركها مع أصحاب المصلحة، وتستخدم الدروس المُستفادة لتحسين الأداء.'),
  (md5('cts-v0.2.1-indicator-28')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-7')::uuid, 28, 'تحدد المنظمة احتياجاتها من الشراكات الفنية التي تُعزز جودة خدماتها من خلال تحليل دوري لبرامجها وخدماتها.'),
  (md5('cts-v0.2.1-indicator-29')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-7')::uuid, 29, 'تجمع المنظمة معلومات عن الشركاء المُحتملين، وتُحلل مدى توافق توجهاتهم وقدراتهم مع أهداف برامجها وخدماتها.'),
  (md5('cts-v0.2.1-indicator-30')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-7')::uuid, 30, 'تضع المنظمة خططاً واضحة للتواصل مع الشركاء المحتملين وتحدد الأهداف والوسائل ومتطلبات بناء شراكات فعالة.'),
  (md5('cts-v0.2.1-indicator-31')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-7')::uuid, 31, 'تعتمد المنظمة إطارًا واضحًا لإنهاء الشراكات، يشمل تحديد قواعد وآليات فك الارتباط منذ بداية الشراكة، وتنفذ هذا الإطار بما يضمن عملية إنهاء للشراكة تحافظ على العلاقات وتتيح فرصًا لإعادة التعاون مستقبلاً.'),
  (md5('cts-v0.2.1-indicator-32')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-8')::uuid, 32, 'تتأكد المنظمة من استيفاء جميع المتطلبات النظامية، وذلك قبل توقيع أي اتفاقية شراكة، بما في ذلك مراجعة بنود الاتفاقية والتأكد من التزام الشركاء بالأنظمة والمعايير ذات الصلة.'),
  (md5('cts-v0.2.1-indicator-33')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-8')::uuid, 33, 'تتأكد المنظمة من تحديد اتفاقيات الشراكة لأدوار ومسؤوليات كل طرف بوضوح في دعم تنفيذ البرامج وتقديم الخدمات.'),
  (md5('cts-v0.2.1-indicator-34')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-8')::uuid, 34, 'تضع المنظمة إجراءات واضحة للتواصل مع الشركاء، وتتأكد من فهمهم لهذه الإجراءات، كما تجمع آراء الشركاء لمعالجة أي مشاكل أو قضايا قد تطرأ أثناء العمل.'),
  (md5('cts-v0.2.1-indicator-35')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-8')::uuid, 35, 'تُحيل المنظمة المستفيدين إلى الشركاء الذين يُقدمون خدمات مُكملة من خلال إجراءات واضحة وموثقة، وتُوثّق هذه الإحالات بسجلات واضحة.'),
  (md5('cts-v0.2.1-indicator-36')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-9')::uuid, 36, 'تقيّم المنظمة  الشراكات الفنية، وتحلل فوائدها  ومخاطرها، وتُقرر استمرارها أو إيقافها بناءً على نتائج التقييم والتحليل.'),
  (md5('cts-v0.2.1-indicator-37')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-9')::uuid, 37, 'تُحافظ المنظمة على سجلات محدثة لبيانات الشركاء، بما في ذلك معلومات الاتصال والمشاريع المُنفذة ونتائج تقييم الشراكة.'),
  (md5('cts-v0.2.1-indicator-38')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-10')::uuid, 38, 'تضع المنظمة سياسات موثقة ومحدثة تُحدد مبادئ وقواعد تقديم الخدمات للمستفيدين.'),
  (md5('cts-v0.2.1-indicator-39')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-10')::uuid, 39, 'تُحدد المنظمة بوضوح متطلبات ومعايير تقديم وإيقاف الخدمات،  بما يضمن وصول الفئات المستهدفة إليها بشكل عادل دون تمييز.'),
  (md5('cts-v0.2.1-indicator-40')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-10')::uuid, 40, 'توثق المنظمة إجراءات تقديم الخدمات وتجربة المستفيد وتطور أدلة إرشادية مفصّلة، توضح المراحل والخطوات وتحدد المسؤوليات والصلاحيات بوضوح.'),
  (md5('cts-v0.2.1-indicator-41')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-10')::uuid, 41, 'تضع المنظمة خطط عمل فعّالة تُحدد المهام والمسؤوليات والجداول الزمنية والموارد المطلوبة لتنفيذ البرامج وتقديم الخدمات.'),
  (md5('cts-v0.2.1-indicator-42')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-10')::uuid, 42, 'تُطور المنظمة خطط مُتابعة تُحدد مواعيد إعداد التقارير، والبيانات المطلوبة، والجهات المسؤولة عن جمعها وتحليلها، وأصحاب المصلحة المعنيين بها.'),
  (md5('cts-v0.2.1-indicator-43')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-11')::uuid, 43, 'توفر المنظمة  الموارد اللازمة لتنفيذ برامجها وخدماتها، بما في ذلك المرافق  والأجهزة والمعدات الضرورية.'),
  (md5('cts-v0.2.1-indicator-44')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-11')::uuid, 44, 'تضمن المنظمة سهولة الوصول إلى أماكن تقديم البرامج والخدمات، مع توفير إرشادات واضحة للحركة داخلها.'),
  (md5('cts-v0.2.1-indicator-45')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-11')::uuid, 45, 'تزود المنظمة المستفيدين بمعلومات وافية عن خدماتها وكيفية الاستفادة منها، باستخدام وسائل تواصل متنوعة تناسب قدراتهم واحتياجاتهم.'),
  (md5('cts-v0.2.1-indicator-46')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-11')::uuid, 46, 'تُوفر المنظمة أدلة إرشادية لإدارة علاقتها مع المستفيدين أثناء وبعد تقديم الخدمات، وتضمن الإفصاح عن أي تضارب محتمل في المصالح.'),
  (md5('cts-v0.2.1-indicator-47')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-11')::uuid, 47, 'تطبق المنظمة إجراءات ومعايير فعّالة لضمان سلامة المستفيدين أثناء تقديم الخدمات، وتتأكد من وعي المستفيدين والعاملين بإجراءات وتعليمات السلامة.'),
  (md5('cts-v0.2.1-indicator-48')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-12')::uuid, 48, 'تحتفظ المنظمة بسجلات مُحدثة للمستفيدين والخدمات المُقدمة لهم، مع ضمان السرية والخصوصية وسهولة الوصول إلى هذه البيانات .'),
  (md5('cts-v0.2.1-indicator-49')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-12')::uuid, 49, 'تطبق المنظمة إجراءات فعّالة لمعالجة استفسارات واقتراحات وشكاوى المستفيدين، وتُعلمهم بهذه الإجراءات ومدة الاستجابة للتواصل معهم.'),
  (md5('cts-v0.2.1-indicator-50')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-12')::uuid, 50, 'تُطبق المنظمة نظاماً لتحديد وحماية وتأمين وثائق وممتلكات المستفيدين، ولديها إجراءات للتعامل مع حالات فقدانها أو تلفها.'),
  (md5('cts-v0.2.1-indicator-51')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-12')::uuid, 51, 'تُطور المنظمة خطة فعّالة للتعامل مع حالات عدم المطابقة في المنتجات والخدمات، وتُحدد إجراءات لمنع تكرارها، وتُتابع فعالية هذه الإجراءات.'),
  (md5('cts-v0.2.1-indicator-52')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-13')::uuid, 52, 'تراقب المنظمة معدلات الأخطاء أو الشكاوى المرتبطة بأداء العاملين والمتطوعين، وتحلل المعلومات وتحدد المجالات التي تحتاج إلى تحسينات لضمان جودة الخدمة المقدمة.'),
  (md5('cts-v0.2.1-indicator-53')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-13')::uuid, 53, 'تجري المنظمة تقييماً لكفاءة أداء العاملين والمتطوعين من منظور المستفيدين، وتقيس مستوى ثقة المستفيدين ورضاهم عن الأداء.'),
  (md5('cts-v0.2.1-indicator-54')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-13')::uuid, 54, 'توثق المنظمة الدروس المستفادة من تقييم نتائج الفريق وتحللها وتوظفها في تحسين أداء العاملين وكفاءة العمليات وجودة الخدمات.'),
  (md5('cts-v0.2.1-indicator-55')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-14')::uuid, 55, 'تُحدد المنظمة مؤشرات أداء رئيسية لقياس أداء عملياتها، وتضع خططاً واضحة لقياسها، وتضمن وعي العاملين والمتطوعين بأهداف القياس وكيفية جمع البيانات.'),
  (md5('cts-v0.2.1-indicator-56')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-14')::uuid, 56, 'تجمع المنظمة بيانات أداء العمليات، وتُحللها، وتتخذ الإجراءات التصحيحية اللازمة عند وجود أي انحراف عن الأهداف.'),
  (md5('cts-v0.2.1-indicator-57')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-14')::uuid, 57, 'تُعد المنظمة تقارير دورية عن أداء عملياتها وتُشاركها مع أصحاب المصلحة، وتُستخدم هذه التقارير لمقارنة الأداء بين الفترات المختلفة وتراقب اتجاهات التحسن في الأداء.'),
  (md5('cts-v0.2.1-indicator-58')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-15')::uuid, 58, 'تُحدد المنظمة مؤشرات للمخرجات والنتائج المتعلقة بالمستفيدين، وتضع خطة تقييم واضحة تُحدد فيها المسؤوليات والصلاحيات ودورية جمع البيانات.'),
  (md5('cts-v0.2.1-indicator-59')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-15')::uuid, 59, 'العاملون والمتطوعون على دراية بنتائج البرامج والخدمات التي تسعى المنظمة لتحقيقها على المستفيدين، وكيفية جمع البيانات وتحليلها.'),
  (md5('cts-v0.2.1-indicator-60')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-15')::uuid, 60, 'تجمع المنظمة بيانات المخرجات والنتائج، وتوثق الإخفاقات وقصص النجاح، وتُعدّ تقارير عن النتائج وتُشاركها مع أصحاب المصلحة.'),
  (md5('cts-v0.2.1-indicator-61')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-standard-15')::uuid, 61, 'توثق المنظمة الدروس المستفادة من تحليل النتائج وتستخدمها في تطوير وتحسين البرامج والخدمات.')
insert into public.items (id, tool_version_id, indicator_id, number, text, improvement_action, strength_text, opportunity_text) values
  (md5('cts-v0.2.1-item-1')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-1')::uuid, 1, 'لدى الجمعية نظام لجمع البيانات بانتظام مثل استبيانات أو لقاءات مخططة مع المستفيدين.', 'إنشاء نظام متكامل لجمع البيانات بانتظام يشمل أدوات مثل الاستبيانات واللقاءات المخططة مع المستفيدين مع تدريب الفريق على استخدامه بشكل فعال.', 'تمتلك الجمعية نظاماً منظماً لجمع البيانات بانتظام باستخدام أدوات مثل الاستبيانات واللقاءات المخططة مع المستفيدين مما يضمن توفر معلومات دقيقة وحديثة لدعم اتخاذ القرار.', 'لا تمتلك الجمعية نظاماً واضحاً ومنتظماً لجمع البيانات بانتظام من المستفيدين مما قد يؤدي إلى نقص المعلومات اللازمة لتحسين البرامج والخدمات.'),
  (md5('cts-v0.2.1-item-2')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-1')::uuid, 2, 'قامت الجمعية بجمع معلومات عن احتياجات المستفيدين وتوقعاتهم.', 'تنفيذ خطة شاملة لجمع معلومات دقيقة عن احتياجات وتوقعات المستفيدين من خلال استبيانات مخصصة ولقاءات منتظمة.', 'نجحت الجمعية في جمع معلومات شاملة عن احتياجات وتوقعات المستفيدين مما يعكس التزامها بفهم أولوياتهم والعمل بناءً عليها.', 'لم تقم الجمعية بجمع معلومات كافية أو موثوقة عن احتياجات وتوقعات المستفيدين مما يؤثر على جودة البرامج والخدمات المقدمة.'),
  (md5('cts-v0.2.1-item-3')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-1')::uuid, 3, 'حللت الجمعية البيانات لتحديد توقعات المستفيدين ومدى رضاهم.', 'إنشاء عملية تحليل دورية للبيانات المجمعة لتحديد توقعات المستفيدين وقياس مدى رضاهم مع توثيق النتائج واستخدامها لتطوير البرامج.', 'قامت الجمعية بتحليل البيانات التي جمعتها لتحديد توقعات المستفيدين وقياس مدى رضاهم مما ساهم في تحسين جودة الخدمات.', 'لم تقم الجمعية بتحليل البيانات بشكل كافٍ لتحديد توقعات المستفيدين أو قياس رضاهم مما قد يؤدي إلى ضعف في توجيه البرامج والخدمات.'),
  (md5('cts-v0.2.1-item-4')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-1')::uuid, 4, 'لدى الجمعية تقريرأو سجل موثق عن توقعات واحتياجات المستفيدين.', 'إعداد تقرير موثق ومنتظم عن توقعات واحتياجات المستفيدين وتحديثه بشكل دوري ليتماشى مع تغيرات احتياجاتهم.', 'توفر الجمعية تقريراً موثقاً عن توقعات واحتياجات المستفيدين مما يساهم في تعزيز الشفافية ودعم تطوير البرامج.', 'لا يتوفر لدى الجمعية تقرير موثق يعكس توقعات واحتياجات المستفيدين مما يضعف قدرتها على تلبية متطلباتهم.'),
  (md5('cts-v0.2.1-item-5')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-1')::uuid, 5, 'التقريرأو السجل حديث ومتاح.', 'تحديث تقرير أو سجل توقعات واحتياجات المستفيدين  وإتاحته لجميع الأطراف المعنية لاستخدامه في عمليات التخطيط واتخاذ القرار.', 'تقرير توقعات واحتياجات المستفيدين حديث ومتوافر مما يتيح استخدامه في اتخاذ قرارات مستنيرة وفي الوقت المناسب.', 'التقرير المتعلق بتوقعات واحتياجات المستفيدين غير محدّث أو غير متاح مما يعيق الاستفادة منه في تحسين البرامج والخدمات.'),
  (md5('cts-v0.2.1-item-6')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-1')::uuid, 6, 'تمت مناقشة التقرير ويوجد توثيق للمناقشة مثل محضر اجتماع أو تقرير ورشة عمل داخلية.', 'تنظيم اجتماعات دورية لمناقشة تقرير توقعات المستفيدين وتوثيق هذه الاجتماعات من خلال محاضر رسمية أو تقارير ورش عمل.', 'تمت مناقشة تقرير توقعات المستفيدين خلال اجتماعات موثقة مما يبرز التزام الجمعية بمشاركة المعلومات واتخاذ قرارات جماعية.', 'لم يتم مناقشة تقرير توقعات المستفيدين بشكل رسمي أو لم يتم توثيق النقاشات المتعلقة به.'),
  (md5('cts-v0.2.1-item-7')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-1')::uuid, 7, 'استخدمت الجمعية المعلومات في تحسين وتطوير البرامج والخدمات ويوجد دليل موثق يظهر ذلك.', 'إنشاء آلية موثقة لاستخدام المعلومات المجمعة في تحسين البرامج والخدمات مع متابعة تنفيذ التحسينات وتوثيقها بشكل دوري.', 'تستفيد الجمعية من المعلومات التي تجمعها في تحسين البرامج والخدمات مع وجود أدلة موثقة تثبت تطبيق هذه التحسينات.', 'لا تستخدم الجمعية المعلومات المجمعة لتحسين البرامج والخدمات أو تفتقر إلى دليل موثق يثبت ذلك.'),
  (md5('cts-v0.2.1-item-8')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-2')::uuid, 8, 'تستخدم الجمعية سجلاً موثقاً بالقوانين والأنظمة المتعلقة بالمستفيدين والخدمات.', 'إعداد سجل موثق يضم جميع القوانين والأنظمة ذات الصلة بالمستفيدين والخدمات واعتماده كمرجع أساسي لجميع العاملين.', 'تعتمد الجمعية  على سجل موثق بالقوانين والأنظمة المتعلقة بالمستفيدين والخدمات مما يضمن الامتثال والشفافية في عملها.', 'لا تستخدم الجمعية سجلاً موثقاً بالقوانين والأنظمة المتعلقة بالمستفيدين والخدمات مما يعرضها لاحتمال عدم الامتثال للمتطلبات النظامية ذات الصلة.'),
  (md5('cts-v0.2.1-item-9')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-2')::uuid, 9, 'السجل شامل لكل الأنظمة والقوانين ذات الصلة.', 'مراجعة السجل الحالي للأنظمة والقوانين للتأكد من شمولية جميع الأنظمة والقوانين ذات الصلة وتحديثه بما يتماشى مع أحدث المتطلبات.', 'السجل الموثق للجمعية شامل لكل الأنظمة والقوانين ذات الصلة مما يضمن تغطية شاملة للممارسات القانونية والتنظيمية.', 'السجل الموثق للجمعية يفتقر إلى الشمولية ولا يغطي جميع الأنظمة والقوانين ذات الصلة مما قد يسبب ثغرات تنظيمية.'),
  (md5('cts-v0.2.1-item-10')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-2')::uuid, 10, 'حللت الجمعية تأثير الأنظمة والقوانين على خدماتها وهذا التحليل موثق في السجل.', 'إجراء تحليل دوري لتأثير الأنظمة والقوانين على خدمات الجمعية مع توثيق النتائج في السجل المخصص.', 'الجمعية قامت بتحليل تأثير الأنظمة والقوانين على خدماتها وحرصت على توثيق هذا التحليل في السجل مما يعزز التخطيط المبني على المعرفة.', 'لا تحلل الجمعية  تأثير الأنظمة والقوانين على خدماتها أو أن التحليل غير موثق مما قد يؤدي إلى قرارات غير مستندة إلى تقييم قانوني.'),
  (md5('cts-v0.2.1-item-11')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-2')::uuid, 11, 'جميع العاملين أو المتطوعين ذوي العلاقة لديهم وعي بالقوانين والأنظمة ذات الصلة.', 'تنظيم ورش عمل وبرامج تدريبية منتظمة لرفع وعي العاملين والمتطوعين بالقوانين والأنظمة ذات الصلة بعمل الجمعية.', 'العاملون والمتطوعون في الجمعية لديهم وعي كامل بالقوانين والأنظمة ذات الصلة مما يضمن الالتزام وتجنب المخالفات.', 'لا يمتلك جميع العاملين والمتطوعين وعياً كافياً بالقوانين والأنظمة ذات الصلة مما يزيد من خطر عدم الامتثال القانوني.'),
  (md5('cts-v0.2.1-item-12')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-2')::uuid, 12, 'سجل القوانين والأنظمة محدث ومتاح.', 'تحديث سجل الأنظمة والقوانين لضمان ملاءمته مع القوانين الحالية وإتاحته للعاملين بشكل يسهل الوصول إليه.', 'سجل القوانين والأنظمة محدث ومتوافر لجميع الأطراف ذات العلاقة مما يضمن مرجعية فعالة وسهولة الوصول إلى المعلومات.', 'سجل القوانين والأنظمة غير محدث أو غير متاح للعاملين مما يضعف من كفاءة الالتزام بالممارسات النظامية.'),
  (md5('cts-v0.2.1-item-13')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-2')::uuid, 13, 'السجل مراجع من جهة أو شخص مختص مثل محامي أو أخصائي الحوكمة والامتثال.', 'التعاقد مع محامٍ أو أخصائي حوكمة لمراجعة السجل الموثق بشكل دوري وضمان دقته وامتثاله للأنظمة والتشريعات.', 'السجل الموثق للجمعية تمت مراجعته من قبل جهة أو شخص مختص مثل محامٍ أو أخصائي حوكمة مما يضمن دقة الالتزام القانوني.', 'لم تتم مراجعة السجل الموثق من قبل جهة أو شخص مختص مما يزيد من احتمال وجود أخطاء أو نقص في المحتوى القانوني.'),
  (md5('cts-v0.2.1-item-14')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-3')::uuid, 14, 'لدى الجمعية آلية أوعملية لتحليل المتطلبات الفنية للبرامج والخدمات.', 'تطوير آلية شاملة لتحليل المتطلبات الفنية للبرامج والخدمات مع تحديد خطوات واضحة للتنفيذ وتدريب الفريق على تطبيقها.', 'تمتلك الجمعية آلية فعالة ومنظمة لتحليل المتطلبات الفنية للبرامج والخدمات مما يضمن التخطيط السليم والتطبيق الفعّال.', 'لا توجد لدى الجمعية آلية واضحة لتحليل المتطلبات الفنية للبرامج والخدمات مما قد يؤدي إلى ضعف التخطيط وصعوبة التنفيذ.'),
  (md5('cts-v0.2.1-item-15')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-3')::uuid, 15, 'يتضمن التحليل تحديد المتطلبات والموارد الضرورية لتقديم الخدمات.', 'إدراج بند واضح في عملية تحليل المتطلبات الفنية لتحديد جميع المتطلبات والموارد الضرورية بدقة مع إعداد قوائم مرجعية تشمل التفاصيل.', 'تتضمن عملية التحليل التي تقوم بها الجمعية تحديداً دقيقاً للمتطلبات والموارد الضرورية لتقديم الخدمات بشكل فعّال.', 'لا يتم تحديد المتطلبات والموارد الضرورية بشكل كافٍ في عملية التحليل مما قد يؤدي إلى نقص في تجهيز الخدمات أو تعطيلها.'),
  (md5('cts-v0.2.1-item-16')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-3')::uuid, 16, 'يتضمن التحليل تحديد معايير تقديم الخدمات.', 'إضافة خطوة في تحليل المتطلبات الفنية مخصصة لتحديد معايير تقديم الخدمات مع مراجعتها وتطويرها بشكل مستمر لضمان الجودة.', 'تشمل عملية التحليل في الجمعية تحديد معايير واضحة لتقديم الخدمات مما يضمن جودة موحدة ورضا المستفيدين.', 'لا يتم تحديد معايير تقديم الخدمات ضمن عملية التحليل مما قد يؤدي إلى تفاوت في جودة الخدمة وصعوبة قياس الأداء.'),
  (md5('cts-v0.2.1-item-17')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-3')::uuid, 17, 'يتضمن التحليل الموارد البشرية والمؤهلات والخبرات المطلوبة.', 'إدراج عنصر في عملية تحليل المتطلبات الفنية لتحديد الاحتياجات البشرية من حيث العدد المؤهلات والخبرات مع وضع خطة لتلبية هذه الاحتياجات.', 'تحرص الجمعية على تضمين تحليل الموارد البشرية المطلوبة من حيث المؤهلات والخبرات اللازمة مما يضمن توافر الكفاءات المناسبة لتنفيذ البرامج.', 'لا يتضمن التحليل تحديد الموارد البشرية والمؤهلات والخبرات المطلوبة مما قد يؤدي إلى عدم كفاءة في تنفيذ الخدمات.'),
  (md5('cts-v0.2.1-item-18')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-3')::uuid, 18, 'التحليل موثق ومتاح.', 'إنشاء نظام لتوثيق جميع نتائج تحليل المتطلبات الفنية وتوفيرها بشكل يسهل الوصول إليه من قبل العاملين وأصحاب المصلحة.', 'تحرص الجمعية على توثيق جميع نتائج التحليل وإتاحتها بسهولة مما يعزز الشفافية ويسهل مراجعة المعلومات واستخدامها.', 'نتائج التحليل غير موثقة أو غير متاحة للعاملين وأصحاب العلاقة مما يعيق الاستفادة منها في تحسين الأداء.'),
  (md5('cts-v0.2.1-item-19')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-3')::uuid, 19, 'التحليل محدث ويغطي كل البرامج والخدمات.', 'تصميم جدول زمني لتحديث تحليل المتطلبات بشكل دوري مع التأكد من شموله لجميع البرامج والخدمات الحالية والمستقبلية.', 'تعمل الجمعية على تحديث تحليل المتطلبات الفنية بانتظام مع ضمان شمولها لجميع البرامج والخدمات مما يضمن التكيف مع الاحتياجات المتغيرة.', 'التحليل قديم أو لا يغطي جميع البرامج والخدمات مما قد يؤدي إلى فجوات في تلبية الاحتياجات الحالية والمستقبلية.'),
  (md5('cts-v0.2.1-item-20')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-4')::uuid, 20, 'تستخدم الجمعية منهجية لتحليل الجهات المعنية.', 'تصميم وتطبيق منهجية شاملة لتحليل الجهات المعنية تشمل تحديد الأدوار التأثيرات وسبل التعاون مع تدريب الفريق على تطبيقها.', 'تعتمد الجمعية  على منهجية واضحة لتحليل الجهات المعنية مما يعزز من قدرتها على تحديد الأدوار والتأثيرات وبناء شراكات فعالة.', 'لا تستخدم الجمعية منهجية محددة لتحليل الجهات المعنية مما قد يؤدي إلى ضعف في فهم الأدوار والتأثيرات وتحديد الأولويات.'),
  (md5('cts-v0.2.1-item-21')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-4')::uuid, 21, 'حصرت الجمعية كافة الجهات المعنية بخدماتها وبرامجها.', 'إجراء عملية حصر شاملة ومحدثة لكافة الجهات المعنية بخدمات الجمعية وبرامجها مع إنشاء قاعدة بيانات موحدة لهذه الجهات.', 'قامت الجمعية بحصر جميع الجهات المعنية بخدماتها وبرامجها مما يضمن شمولية التحليل وإشراك كافة الأطراف ذات الصلة.', 'لم تقم الجمعية بحصر شامل لجميع الجهات المعنية مما قد يؤدي إلى استبعاد أطراف مؤثرة قد يكون لها دور في دعم البرامج والخدمات.'),
  (md5('cts-v0.2.1-item-22')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-4')::uuid, 22, 'حللت الجمعية مدي تأثير كل جهة من الجهات ذات العلاقة.', 'إضافة تحليل دوري لمدى تأثير الجهات ذات العلاقة مع توثيق النتائج واستخدامها في تطوير استراتيجيات التعاون والشراكات.', 'الجمعية قامت بتحليل مدى تأثير الجهات ذات العلاقة بشكل دقيق مما ساعدها على توجيه الجهود والاستفادة من هذه العلاقات بفعالية.', 'لم تقم الجمعية بتحليل كافٍ لتحديد مدى تأثير الجهات ذات العلاقة مما قد يؤدي إلى ضعف في الاستفادة من الشراكات والدعم المحتمل.'),
  (md5('cts-v0.2.1-item-23')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-4')::uuid, 23, 'درست الجمعية توقعات واحتياجات الجهات ذات العلاقة.', 'تنفيذ دراسة دورية لتوقعات واحتياجات الجهات ذات العلاقة مع تضمينها في خطط الجمعية لتحسين مستوى التعاون وتلبية الاحتياجات.', 'حرصت الجمعية على دراسة توقعات واحتياجات الجهات ذات العلاقة مما يعزز التعاون والتفاهم المتبادل لتحقيق الأهداف المشتركة.', 'لم تدرس الجمعية توقعات واحتياجات الجهات ذات العلاقة بشكل كافٍ مما قد يؤدي إلى ضعف في بناء شراكات فعالة.'),
  (md5('cts-v0.2.1-item-24')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-4')::uuid, 24, 'تحليل التأثير ودراسة التوقعات والاحتياجات موثق في سجل أو تقرير متاح.', 'إعداد سجل أو تقرير موثق لتحليل التأثير ودراسة توقعات واحتياجات الجهات ذات العلاقة مع تحديثه بشكل دوري وجعله متاحاً للأطراف ذات الصلة.', 'قامت الجمعية بتوثيق تحليل التأثير ودراسة التوقعات والاحتياجات في سجل أو تقرير متاح مما يسهل الرجوع إليه ومشاركته مع الأطراف المعنية.', 'لم توثق الجمعية تحليل التأثير ودراسة التوقعات والاحتياجات مما قد يؤدي إلى صعوبة في الرجوع إلى المعلومات أو استخدامها في التخطيط.'),
  (md5('cts-v0.2.1-item-25')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-4')::uuid, 25, 'سجلأو تقرير تحليل الجهات المعنية محدث.', 'وضع جدول زمني لتحديث سجل أو تقرير تحليل الجهات المعنية بانتظام مع مراجعة المعلومات للتأكد من دقتها وملاءمتها.', 'تحرص الجمعية على تحديث سجل أو تقرير تحليل الجهات المعنية بشكل دوري مما يضمن توافق المعلومات مع الواقع الحالي.', 'سجل أو تقرير تحليل الجهات المعنية غير محدث مما قد يؤدي إلى معلومات قديمة تؤثر على جودة التخطيط والتعاون.'),
  (md5('cts-v0.2.1-item-26')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-4')::uuid, 26, 'استفادت الجمعية من تحليل الجهات المعنية عند التخطيط وتقديم الخدمات ويوجد دليل موثق يظهر ذلك مثل محضر اجتماع أو تقرير أو بريد إلكتروني.', 'تفعيل استخدام نتائج تحليل الجهات المعنية في تخطيط وتقديم الخدمات مع توثيق الأدلة على هذه العمليات لضمان الشفافية والمتابعة.', 'استفادت الجمعية من نتائج تحليل الجهات المعنية في تخطيط وتقديم الخدمات مع وجود أدلة موثقة تدعم ذلك مثل محاضر الاجتماعات أو التقارير.', 'لم تستفد الجمعية بشكل كافٍ من تحليل الجهات المعنية عند التخطيط وتقديم الخدمات أو لا توجد أدلة موثقة تثبت ذلك.'),
  (md5('cts-v0.2.1-item-27')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-5')::uuid, 27, 'اختارت الجمعية أو طورت أدوات لتقييم القدرات المؤسسية.', 'تحديد أدوات تقييم مناسبة أو تطوير أدوات مخصصة لتقييم القدرات المؤسسية مع مراعاة متطلبات الجمعية وأهدافها.', 'حرصت الجمعية على اختيار أو تطوير أدوات متخصصة لتقييم القدرات المؤسسية مما يضمن دقة القياس وفعالية النتائج.', 'لم تختَر الجمعية أو تطور أدوات مناسبة لتقييم القدرات المؤسسية مما قد يؤدي إلى ضعف في قياس الأداء وتحليل القدرات بشكل صحيح.'),
  (md5('cts-v0.2.1-item-28')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-5')::uuid, 28, 'لدى الجمعية خطة سنوية لتقييم القدرات تحدد مواعيد التقييم الذاتي أو الخارجي وقد يكون مضمناً في الخطة التشغيلية.', 'وضع خطة سنوية لتقييم القدرات المؤسسية مع تحديد مواعيد واضحة للتقييم الذاتي أو الخارجي ودمجها في الخطة التشغيلية.', 'لدى الجمعية خطة سنوية واضحة لتقييم القدرات المؤسسية تتضمن مواعيد التقييم الذاتي والخارجي لضمان استمرارية التطوير.', 'لا توجد لدى الجمعية خطة سنوية لتقييم القدرات المؤسسية مما قد يؤدي إلى غياب تنظيم عملية التقييم وتأخير تحسين الأداء.'),
  (md5('cts-v0.2.1-item-29')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-5')::uuid, 29, 'نفذت الجمعية أو شاركت في تقييم للقدرات المؤسسية مرة واحدة على الأقل خلال العام.', 'إدراج التقييم المؤسسي كجزء أساسي من الأنشطة السنوية للجمعية مع الحرص على إجراء تقييم واحد على الأقل كل عام.', 'قامت الجمعية بتنفيذ أو المشاركة في تقييم للقدرات المؤسسية مرة واحدة على الأقل خلال العام مما يعكس التزامها بتطوير الأداء.', 'لم تنفذ الجمعية أو تشارك في تقييم للقدرات المؤسسية خلال العام مما قد يؤدي إلى غياب بيانات حقيقية لتحديد نقاط القوة والضعف.'),
  (md5('cts-v0.2.1-item-30')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-5')::uuid, 30, 'يوجد تقرير موثق لنتائج تقييم القدرات المؤسسية.', 'إعداد تقرير موثق وشامل لنتائج كل عملية تقييم للقدرات المؤسسية مع توضيح نقاط القوة والضعف والفرص للتحسين.', 'أعدت الجمعية تقريراً موثقاً لنتائج تقييم القدرات المؤسسية مما يسهل تحليل النتائج ووضع خطط التطوير.', 'لا يوجد تقرير موثق لنتائج تقييم القدرات المؤسسية مما قد يؤدي إلى صعوبة في توثيق التقدم وتحليل النتائج بشكل منهجي.'),
  (md5('cts-v0.2.1-item-31')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-5')::uuid, 31, 'يوجد خطة للتحسين والتطوير استناداً نتائج التقييم.', 'تصميم خطة تحسين وتطوير بناءً على نتائج التقييم المؤسسي مع تحديد أولويات التنفيذ ومواعيد زمنية واضحة.', 'تمتلك الجمعية خطة للتحسين والتطوير بناءً على نتائج التقييم المؤسسي مما يضمن تحويل التوصيات إلى إجراءات عملية.', 'لا توجد خطة للتحسين والتطوير استناداً إلى نتائج التقييم مما قد يؤدي إلى عدم الاستفادة من نتائج التقييم بشكل فعال.'),
  (md5('cts-v0.2.1-item-32')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-5')::uuid, 32, 'يتوفر دليل على متابعة تنفيذ أنشطة خطة التحسين والتطوير.', 'إنشاء نظام متابعة وتوثيق لأنشطة خطة التحسين والتطوير مع إعداد تقارير دورية توضح التقدم المحرز والعوائق المحتملة.', 'تتوفر لدى الجمعية أدلة موثقة على متابعة تنفيذ أنشطة خطة التحسين والتطوير مما يعزز الشفافية والالتزام بالتحسين المستمر.', 'لا توجد أدلة واضحة على متابعة تنفيذ أنشطة خطة التحسين والتطوير مما يضعف مصداقية الجمعية في تنفيذ التوصيات.'),
  (md5('cts-v0.2.1-item-33')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-6')::uuid, 33, 'تقوم الجمعية بتحلل تقارير إنجاز البرامج والخدمات.', 'إدراج عملية تحليل دورية لتقارير إنجاز البرامج والخدمات ضمن آليات العمل مع تحديد المسؤوليات والجداول الزمنية لذلك.', 'تحرص الجمعية على تحليل تقارير إنجاز البرامج والخدمات بانتظام مما يساعد على تقييم الأداء وتحسين جودة التنفيذ.', 'لا تقوم الجمعية بتحليل تقارير إنجاز البرامج والخدمات مما قد يؤدي إلى غياب فهم شامل للأداء وصعوبة تحديد نقاط القوة والضعف.'),
  (md5('cts-v0.2.1-item-34')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-6')::uuid, 34, 'توثق الجمعية الدروس المستفادة وتحللها.', 'إنشاء آلية لتوثيق الدروس المستفادة وتحليلها بعد تنفيذ كل برنامج أو خدمة مع وضعها في سجل متاح للرجوع إليه.', 'تواظب الجمعية على توثيق وتحليل الدروس المستفادة من تنفيذ البرامج والخدمات مما يساهم في تحسين الأداء وتجنب الأخطاء المستقبلية.', 'لا تقوم الجمعية بتوثيق وتحليل الدروس المستفادة مما قد يؤدي إلى تكرار الأخطاء وفقدان فرص تحسين العمليات.'),
  (md5('cts-v0.2.1-item-35')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-6')::uuid, 35, 'توثق الجمعية آراء الجهات المعنية وتحللها.', 'تطبيق نظام لجمع وتوثيق آراء الجهات المعنية بشكل منتظم مع تحليلها واستخدام النتائج في تحسين البرامج والخدمات.', 'تحرص الجمعية على توثيق آراء الجهات المعنية وتحليلها مما يعزز من استجابتها لاحتياجات الأطراف ذات العلاقة وتحسين برامجها.', 'لا تقوم الجمعية بتوثيق وتحليل آراء الجهات المعنية مما قد يؤدي إلى ضعف في فهم احتياجاتهم وصعوبة تحسين مستوى الخدمات.'),
  (md5('cts-v0.2.1-item-36')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-6')::uuid, 36, 'يتوفر تقريرأو سجل لتحليل التقارير والدروس المستفادة والجهات المعنية.', 'إعداد تقرير دوري يشمل تحليلاً لتقارير الإنجاز والدروس المستفادة وآراء الجهات المعنية مع تحديثه بانتظام وإتاحته للمعنيين.', 'يتوفر لدى الجمعية تقرير شامل ومحدث لتحليل التقارير والدروس المستفادة وآراء الجهات المعنية مما يسهل عملية المتابعة والتطوير.', 'لا يوجد لدى الجمعية تقرير موثق لتحليل التقارير والدروس المستفادة وآراء الجهات المعنية مما قد يؤدي إلى صعوبة في تتبع الأداء وتحسينه.'),
  (md5('cts-v0.2.1-item-37')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-6')::uuid, 37, 'التقرير محدّث ومتاح.', 'إعداد جدول زمني لتحديث التقرير بشكل منتظم والتأكد من إتاحته لجميع الأطراف المعنية بسهولة.', 'تحرص الجمعية على تحديث التقرير بشكل منتظم وإتاحته للأطراف ذات العلاقة مما يعزز الشفافية وسهولة استخدام المعلومات.', 'التقرير غير محدث أو غير متاح مما قد يؤدي إلى تقديم معلومات غير دقيقة وصعوبة في اتخاذ قرارات مستنيرة.'),
  (md5('cts-v0.2.1-item-38')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-6')::uuid, 38, 'يوجد دليل موثق على الاستفادة من التحليل في تطوير وتحسين البرامج والخدمات.', 'وضع آلية لتوثيق كيفية الاستفادة من نتائج التحليل في تطوير البرامج والخدمات مع إعداد تقارير دورية تبرز التحسينات التي تم تنفيذها بناءً على التحليل.', 'تظهر الجمعية أدلة واضحة وموثقة على استخدامها لتحليل التقارير والدروس المستفادة وآراء الجهات المعنية في تطوير وتحسين برامجها وخدماتها.', 'لا توجد أدلة موثقة على استفادة الجمعية من تحليل التقارير والدروس المستفادة في تحسين البرامج والخدمات مما يعكس ضعفاً في استخدام نتائج التحليل.'),
  (md5('cts-v0.2.1-item-39')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-7')::uuid, 39, 'الفئات المستفيدة من خدمات الجمعية معرّفة مع تحديد الخصائص الأساسية لكل فئة.', 'إعداد قائمة شاملة للفئات المستفيدة تتضمن تحديداً واضحاً للخصائص الأساسية لكل فئة مع مراجعتها بشكل دوري لتحديثها عند الحاجة.', 'تحدد الجمعية بشكل دقيق الفئات المستفيدة من خدماتها مع وصف واضح للخصائص الأساسية لكل فئة مما يسهم في تصميم خدمات ملائمة تلبي احتياجاتهم.', 'لم تقم الجمعية بتحديد الفئات المستفيدة بشكل واضح أو لم تصف خصائصها الأساسية مما قد يؤدي إلى صعوبة في تقديم خدمات متخصصة تلبي احتياجات المستفيدين.'),
  (md5('cts-v0.2.1-item-40')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-7')::uuid, 40, 'الخدمات المقدمة من الجمعية لكل فئة من فئات المستفيدين محددة.', 'إعداد وتصنيف قائمة بالخدمات المقدمة لكل فئة من الفئات المستفيدة مع توضيح أهداف كل خدمة ومدى ملاءمتها لاحتياجات الفئة المستهدفة.', 'تمتلك الجمعية قائمة واضحة بالخدمات المقدمة لكل فئة من الفئات المستفيدة مما يضمن توفير الخدمات بطريقة فعالة وموجهة تلبي احتياجات كل فئة.', 'لا توجد لدى الجمعية قائمة واضحة بالخدمات المقدمة لكل فئة من الفئات المستفيدة مما قد يؤدي إلى تداخل الخدمات أو عدم تلبيتها لاحتياجات المستفيدين.'),
  (md5('cts-v0.2.1-item-41')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-7')::uuid, 41, 'لدى الجمعية وثيقة محدثة تتضمن توصيف الفئات المستفيدة والخدمات المقدمة لكل فئة.', 'إعداد وثيقة شاملة تحتوي على توصيف للفئات المستفيدة والخدمات المقدمة لكل فئة مع مراجعتها وتحديثها بشكل دوري.', 'تحرص الجمعية على توثيق توصيف الفئات المستفيدة والخدمات المقدمة لهم في وثيقة محدثة مما يسهم في تحسين التخطيط والتنفيذ للخدمات.', 'لا توجد وثيقة محدثة لدى الجمعية تتضمن توصيفاً للفئات المستفيدة والخدمات المقدمة مما قد يؤدي إلى غياب مرجع واضح لدعم التخطيط الاستراتيجي.'),
  (md5('cts-v0.2.1-item-42')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-7')::uuid, 42, 'الوثيقة معتمدة وتاريخ الاعتماد مذكور في الوثيقة.', 'التأكد من اعتماد الوثيقة بشكل رسمي وإضافة تاريخ الاعتماد لضمان موثوقيتها واعتمادها كمرجع تنظيمي.', 'وثيقة توصيف الفئات المستفيدة والخدمات المقدمة معتمدة رسمياً وتحتوي على تاريخ الاعتماد مما يعزز من موثوقيتها واستخدامها كمرجع رسمي.', 'الوثيقة غير معتمدة أو لا تحتوي على تاريخ الاعتماد مما يقلل من مصداقيتها ويعيق استخدامها كمرجع تنظيمي.'),
  (md5('cts-v0.2.1-item-43')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-7')::uuid, 43, 'الوثيقة محدثة ومتاحة.', 'وضع جدول زمني لتحديث الوثيقة بانتظام مع ضمان إتاحتها للأطراف ذات العلاقة بسهولة لضمان استخدامها في العمليات اليومية.', 'تحرص الجمعية على تحديث الوثيقة بشكل دوري وإتاحتها للأطراف ذات العلاقة مما يضمن توافقها مع التغيرات ومرونتها في التطبيق.', 'الوثيقة غير محدثة أو غير متاحة للأطراف ذات العلاقة مما قد يؤدي إلى صعوبة في الاستفادة منها وضعف التوجيه في تقديم الخدمات.'),
  (md5('cts-v0.2.1-item-44')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-8')::uuid, 44, 'جميع البرامج والخدمات التي تقدمها الجمعية معرّفة بدقة.', 'إعداد توصيف شامل ودقيق لجميع البرامج والخدمات التي تقدمها الجمعية مع توضيح أهدافها والفئات المستفيدة منها.', 'تمتلك الجمعية تعريفاً دقيقاً وشاملاً لجميع البرامج والخدمات التي تقدمها مما يساهم في وضوح الأهداف وسهولة تنفيذها بما يتماشى مع احتياجات المستفيدين.', 'لا تمتلك الجمعية تحديداً دقيقاً للبرامج والخدمات التي تقدمها مما قد يؤدي إلى غموض في الأهداف وصعوبة في تحقيق الفائدة المرجوة للمستفيدين.'),
  (md5('cts-v0.2.1-item-45')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-8')::uuid, 45, 'العلاقة بين البرامج والخدمات وتأثيرها على بعضها محدد بوضوح.', 'إجراء دراسة لتحديد العلاقة بين البرامج والخدمات وتأثيرها المتبادل مع إعداد خطة لتكاملها بما يعزز الأثر الإيجابي.', 'تحرص الجمعية على تحديد العلاقة بين البرامج والخدمات وتأثيرها المتبادل مما يضمن التكامل بينها وتحقيق نتائج مستدامة.', 'لا توجد لدى الجمعية رؤية واضحة عن العلاقة بين البرامج والخدمات وتأثيرها على بعضها مما قد يؤدي إلى تداخل أو تعارض في التنفيذ.'),
  (md5('cts-v0.2.1-item-46')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-8')::uuid, 46, 'يتوفر دليل موثق لهيكلة البرامج والخدمات.', 'إعداد دليل موثق يحتوي على هيكلة البرامج والخدمات مع توضيح تفاصيل كل برنامج وخدمة وطريقة تنفيذها.', 'لدى الجمعية دليل موثق وشامل يوضح هيكلة البرامج والخدمات مما يسهل الرجوع إليه كمرجع رسمي لدعم عمليات التخطيط والتنفيذ.', 'لا يتوفر دليل موثق لهيكلة البرامج والخدمات مما قد يؤدي إلى غياب مرجع تنظيمي يصعب معه توجيه العمل وضمان الاتساق.'),
  (md5('cts-v0.2.1-item-47')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-8')::uuid, 47, 'وثيقة الدليل معتمدة وتاريخ الاعتماد مذكور في الوثيقة.', 'ضمان اعتماد دليل هيكلة البرامج والخدمات من الجهة المخولة مع إضافة تاريخ الاعتماد لضمان موثوقيته وفعاليته.', 'تم اعتماد دليل هيكلة البرامج والخدمات رسمياً وتاريخ الاعتماد موثق فيه مما يعزز من موثوقيته واستخدامه كمرجع رسمي معتمد.', 'لم يتم اعتماد دليل هيكلة البرامج والخدمات أو لا يحتوي على تاريخ الاعتماد مما يقلل من مصداقيته كوثيقة مرجعية.'),
  (md5('cts-v0.2.1-item-48')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-8')::uuid, 48, 'الوثيقة محدثة ومتاحة والوصول إليها سهل.', 'وضع جدول زمني لتحديث الدليل بانتظام مع ضمان توفره إلكترونياً وورقياً لسهولة الوصول والاستخدام.', 'تحرص الجمعية على تحديث دليل هيكلة البرامج والخدمات بانتظام وإتاحته بسهولة للأطراف ذات العلاقة مما يسهل الوصول إلى المعلومات وتطبيقها.', 'الدليل غير محدث أو غير متاح بسهولة مما قد يؤدي إلى صعوبة في الرجوع إليه أو الاعتماد عليه في توجيه العمل.'),
  (md5('cts-v0.2.1-item-49')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-9')::uuid, 49, 'يتوفر لدى الجمعية وثيقة وصف لكل برنامجأو خدمة تقدمها.', 'إعداد وثائق وصف تفصيلية لكل برنامج أو خدمة تقدمها الجمعية مع تضمين المعلومات الأساسية التي تدعم التنفيذ والتطوير.', 'تمتلك الجمعية وثائق وصف شاملة لجميع برامجها وخدماتها مما يسهم في تعزيز وضوح البرامج ودعم التخطيط والتنفيذ بشكل منظم.', 'لا توجد لدى الجمعية وثائق وصف شاملة لبرامجها وخدماتها مما قد يؤدي إلى ضعف في التنظيم وصعوبة تحقيق الأهداف المرجوة.'),
  (md5('cts-v0.2.1-item-50')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-9')::uuid, 50, 'تتضمن الوثيقة أهداف كل برنامج أو خدمة.', 'إضافة قسم مخصص لتوضيح أهداف كل برنامج أو خدمة في وثائق الوصف مع تحديد الأهداف بطريقة قابلة للقياس.', 'تتضمن وثائق الجمعية أهدافاً واضحة لكل برنامج أو خدمة مما يضمن توجيه الجهود نحو تحقيق غايات محددة وملموسة.', 'لا تتضمن الوثائق أهدافاً محددة لكل برنامج أو خدمة مما قد يؤدي إلى غياب التوجيه الفعّال وصعوبة قياس النجاح.'),
  (md5('cts-v0.2.1-item-51')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-9')::uuid, 51, 'تتضمن الوثيقة تحديد النتائج المستهدفة والتي تذكر بوضوح التغيرات الإيجابية المتوقعة على المستفيدين.', 'إضافة قسم لتحديد النتائج المستهدفة والتغيرات الإيجابية المتوقعة على المستفيدين ضمن وثائق وصف البرامج والخدمات.', 'توضح الجمعية في وثائقها النتائج المستهدفة لكل برنامج مع ذكر التغيرات الإيجابية المتوقعة على المستفيدين مما يدعم قياس الأثر.', 'لا تحتوي وثائق الجمعية على نتائج مستهدفة أو توضيح للتغيرات الإيجابية المتوقعة مما قد يؤدي إلى صعوبة قياس تأثير البرامج.'),
  (md5('cts-v0.2.1-item-52')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-9')::uuid, 52, 'تتضمن الوثيقة تحديد للأنشطة والمنتجات المباشرة لكل برنامج أو خدمة.', 'إضافة قسم مفصل في الوثائق لتحديد الأنشطة والمنتجات المباشرة لكل برنامج أو خدمة مع توضيح خطوات التنفيذ.', 'تتضمن وثائق الجمعية تحديداً دقيقاً للأنشطة والمنتجات المباشرة لكل برنامج أو خدمة مما يساهم في تسهيل التنفيذ وتقييم النتائج.', 'لا تحتوي وثائق الجمعية على تحديد واضح للأنشطة والمنتجات المباشرة مما قد يؤدي إلى غموض في التخطيط والتنفيذ.'),
  (md5('cts-v0.2.1-item-53')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-9')::uuid, 53, 'تتضمن الوثيقة تحديد الفئةأو الفئات المستفيدة من البرنامج أو الخدمة.', 'إضافة قسم في الوثائق لتحديد الفئات المستفيدة بدقة مع وصف خصائصهم واحتياجاتهم لضمان فعالية البرامج والخدمات.', 'تحرص الجمعية على تحديد الفئات المستفيدة في وثائق البرامج والخدمات مما يساعد في استهداف المستفيدين بدقة.', 'لا تتضمن وثائق الجمعية تحديداً واضحاً للفئات المستفيدة مما قد يؤدي إلى ضعف في استهداف المستفيدين وملاءمة الخدمات لاحتياجاتهم.'),
  (md5('cts-v0.2.1-item-54')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-9')::uuid, 54, 'تتضمن الوثيقة تحديداً للمخاطر ذات الصلة بالبرنامج أو الخدمة.', 'إضافة قسم لتحديد المخاطر المحتملة لكل برنامج أو خدمة مع وضع خطط لإدارتها وتقليل تأثيرها.', 'تتضمن وثائق الجمعية تحديداً واضحاً للمخاطر المرتبطة بالبرامج والخدمات مما يساهم في اتخاذ تدابير استباقية لإدارتها.', 'لا تحتوي وثائق الجمعية على تحديد للمخاطر المرتبطة بالبرامج والخدمات مما يزيد من احتمال التعرض لمشكلات غير متوقعة أثناء التنفيذ.'),
  (md5('cts-v0.2.1-item-55')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-9')::uuid, 55, 'تتضمن الوثيقة تحديداً لمؤشرات النجاح ذات الصلة بالبرنامج أو الخدمة.', 'إدراج مؤشرات نجاح محددة وقابلة للقياس ضمن وثائق وصف البرامج والخدمات لتقييم فعاليتها بشكل دوري.', 'توفر وثائق الجمعية مؤشرات نجاح واضحة لكل برنامج أو خدمة مما يساعد في قياس الأداء وتقييم الأثر.', 'لا تحتوي وثائق الجمعية على مؤشرات نجاح مما قد يؤدي إلى صعوبة تقييم الأداء وتحقيق الأهداف.'),
  (md5('cts-v0.2.1-item-56')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-9')::uuid, 56, 'تتضمن الوثيقة تحديداً للشركاء ذوي العلاقة وأدوارهم المرتبطة بالبرنامج أو الخدمة.', 'إضافة قسم لتحديد الشركاء ذوي العلاقة وأدوارهم المرتبطة بكل برنامج أو خدمة مع تحديث هذا القسم بانتظام.', 'توضح وثائق الجمعية الشركاء ذوي العلاقة وأدوارهم بوضوح مما يسهم في تعزيز التعاون وتحقيق أهداف البرامج.', 'لا تتضمن وثائق الجمعية تحديداً للشركاء أو أدوارهم مما قد يؤدي إلى ضعف التنسيق والتعاون في تنفيذ البرامج.'),
  (md5('cts-v0.2.1-item-57')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-9')::uuid, 57, 'الوثيقة معتمدة ومحدثة ويظهر فيها تاريخ الاعتماد وآخر تحديث.', 'ضمان اعتماد وثائق البرامج والخدمات من الجهات المختصة مع إضافة تواريخ الاعتماد والتحديث لضمان توثيق المعلومات بشكل رسمي.', 'تحرص الجمعية على اعتماد وثائق البرامج والخدمات وتحديثها بانتظام مع توضيح تاريخ الاعتماد وآخر تحديث مما يعزز مصداقيتها.', 'لم يتم اعتماد الوثائق أو لا تحتوي على تواريخ الاعتماد والتحديث مما يقلل من موثوقيتها وصلاحيتها كمرجع رسمي.'),
  (md5('cts-v0.2.1-item-58')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-10')::uuid, 58, 'تتضمن وثيقة وصف البرنامج أو الخدمة تحديداً لمؤشرات تقيس تحقق النتائج على المستفيدين.', 'إضافة مؤشرات واضحة وقابلة للقياس في وثائق وصف البرامج والخدمات مع التركيز على قياس أثر النتائج على المستفيدين بشكل دوري.', 'تحتوي وثيقة وصف البرامج والخدمات على مؤشرات دقيقة لقياس تحقق النتائج على المستفيدين مما يضمن التقييم المستمر لأثر الخدمات المقدمة.', 'لا تتضمن وثيقة وصف البرامج والخدمات مؤشرات لقياس تحقق النتائج على المستفيدين مما قد يؤدي إلى غياب أدوات فعّالة لتقييم الأثر.'),
  (md5('cts-v0.2.1-item-59')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-10')::uuid, 59, 'يتوفر لكل مؤشراً تحديداً واضح للمسؤوليات ذات الصلة مثل المسؤولية عن جمع البيانات.', 'تحديد المسؤوليات المرتبطة بكل مؤشر في وثائق وصف البرامج والخدمات مع تعيين أفراد أو فرق مختصة لجمع البيانات ومتابعة التقييم.', 'تحدد الجمعية بوضوح المسؤوليات ذات الصلة بكل مؤشر مثل المسؤولية عن جمع البيانات مما يعزز الشفافية والتنظيم.', 'لا يتم تحديد المسؤوليات المتعلقة بكل مؤشر في الوثائق مما قد يؤدي إلى تداخل الأدوار وصعوبة تنفيذ عمليات التقييم.'),
  (md5('cts-v0.2.1-item-60')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-10')::uuid, 60, 'طريقة جمع البيانات محددة لكل مؤشر.', 'إضافة تفاصيل حول طرق جمع البيانات لكل مؤشر ضمن وثائق وصف البرامج والخدمات مع التأكد من توافقها مع أفضل الممارسات.', 'توضح وثائق الجمعية طريقة جمع البيانات لكل مؤشر مما يضمن جمع معلومات دقيقة وموحدة تدعم عمليات التقييم.', 'لا تحتوي وثائق الجمعية على تحديد واضح لطريقة جمع البيانات لكل مؤشر مما قد يؤدي إلى ضعف في جودة البيانات وصعوبة تحليلها.'),
  (md5('cts-v0.2.1-item-61')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-10')::uuid, 61, 'دورية وتكرارية جمع البيانات محددة لكل مؤشر.', 'وضع جدول زمني لجمع البيانات بشكل دوري لكل مؤشر وتضمينه في وثائق وصف البرامج والخدمات لضمان الالتزام به.', 'تحرص الجمعية على تحديد دورية وتكرارية جمع البيانات لكل مؤشر مما يضمن توفير معلومات محدثة وموثوقة لدعم اتخاذ القرار.', 'لا يتم تحديد دورية أو تكرارية جمع البيانات لكل مؤشر مما قد يؤدي إلى نقص في تحديث المعلومات وصعوبة متابعة الأداء.'),
  (md5('cts-v0.2.1-item-62')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-10')::uuid, 62, 'المؤشرات معتمدة ويوجد توثيق يظهر تاريخ الاعتماد.', 'ضمان اعتماد المؤشرات المستخدمة في التقييم من الجهات المختصة مع توثيق تاريخ الاعتماد وإضافته إلى وثائق البرامج والخدمات.', 'المؤشرات المستخدمة في تقييم البرامج والخدمات معتمدة رسمياً ويوجد توثيق يوضح تاريخ الاعتماد مما يعزز مصداقيتها واستخدامها كمرجع.', 'لا يتم اعتماد المؤشرات أو لا يوجد توثيق يوضح تاريخ اعتمادها مما يقلل من موثوقيتها وصلاحيتها للاستخدام.'),
  (md5('cts-v0.2.1-item-63')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-10')::uuid, 63, 'المؤشرات محدثة ومتسقة مع البرامج والخدمات التي تقدمها الجمعية.', 'تحديث المؤشرات بانتظام لتتوافق مع التغيرات في البرامج والخدمات مع مراجعتها دورياً لضمان فعاليتها ودقتها.', 'تحرص الجمعية على تحديث المؤشرات بانتظام بما يتماشى مع التطورات والبرامج والخدمات الجديدة مما يضمن ملاءمتها وفعاليتها.', 'المؤشرات غير محدثة أو غير متسقة مع البرامج والخدمات الحالية مما قد يؤدي إلى صعوبة قياس الأثر بشكل دقيق.'),
  (md5('cts-v0.2.1-item-64')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-11')::uuid, 64, 'المخاطر التي قد تؤثر على تحقيق نتائج كل برنامج أو خدمة محددة بوضوح.', 'إعداد قائمة تفصيلية بالمخاطر التي قد تؤثر على تحقيق نتائج كل برنامج أو خدمة مع تضمينها في وثائق التخطيط والتقييم.', 'حرصت الجمعية على تحديد المخاطر المحتملة التي قد تؤثر على تحقيق نتائج كل برنامج أو خدمة بوضوح مما يعزز قدرتها على الاستعداد والتخفيف من تأثيرها.', 'لم تحدد الجمعية بوضوح  المخاطر التي قد تؤثر على تحقيق نتائج البرامج أو الخدمات مما يزيد من احتمالية تعرضها لمشكلات غير متوقعة تؤثر على النتائج.'),
  (md5('cts-v0.2.1-item-65')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-11')::uuid, 65, 'تحديد المخاطر شامل ويغطي كل الجوانب المتعلقة بالبرنامج أو الخدمة على سبيل المثال تشغيلية وتقنية وموارد بشرية وغيرها.', 'إجراء تحليل شامل للمخاطر يشمل جميع الجوانب المتعلقة بالبرنامج أو الخدمة مثل التشغيلية والتقنية والموارد البشرية.', 'تتميز الجمعية بتحديد شامل للمخاطر التي تغطي الجوانب التشغيلية التقنية والموارد البشرية وغيرها مما يضمن استعداداً كاملاً لمواجهة التحديات.', 'لا يغطي تحديد المخاطر جميع الجوانب المرتبطة بالبرنامج أو الخدمة مما قد يؤدي إلى فجوات في الاستعداد لإدارة المخاطر.'),
  (md5('cts-v0.2.1-item-66')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-11')::uuid, 66, 'يوجد تقييم لمستوى تأثير كل خطر.', 'إضافة عملية لتقييم مستوى تأثير كل خطر محتمل على البرنامج أو الخدمة مع تصنيف المخاطر حسب الأولوية ووضع خطط للتعامل معها.', 'تقوم الجمعية بتقييم مستوى تأثير كل خطر محتمل مما يمكنها من تصنيف المخاطر وفقاً لأولويتها واتخاذ الإجراءات المناسبة للتخفيف منها.', 'لا يوجد لدى الجمعية تقييم واضح لمستوى تأثير المخاطر مما قد يؤدي إلى صعوبة في تحديد الأولويات وإدارة المخاطر بفعالية.'),
  (md5('cts-v0.2.1-item-67')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-11')::uuid, 67, 'يوجد توثيق لمشاركة أصحاب المصلحة في تحديد المخاطر.', 'وضع آلية لتوثيق مشاركة أصحاب المصلحة في تحديد المخاطر مع الاحتفاظ بسجلات الاجتماعات أو ورش العمل لضمان الشفافية.', 'تحرص الجمعية على توثيق مشاركة أصحاب المصلحة في عملية تحديد المخاطر مما يضمن تنوع وجهات النظر وتعزيز الشفافية في التخطيط.', 'لا يوجد توثيق يثبت مشاركة أصحاب المصلحة في تحديد المخاطر مما قد يؤدي إلى نقص في الشمولية وضعف في استباق المشكلات.'),
  (md5('cts-v0.2.1-item-68')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-12')::uuid, 68, 'إجراءات التعامل مع كل خطر موثقة وواضحة.', 'إعداد وتوثيق إجراءات واضحة ومحددة للتعامل مع كل خطر محتمل مع ضمان تحديثها بانتظام وفقاً للمتغيرات.', 'حرصت الجمعية على توثيق إجراءات واضحة ومحددة للتعامل مع كل خطر محتمل مما يسهم في تعزيز الاستجابة السريعة والفعالة للمخاطر.', 'لا توجد إجراءات موثقة للتعامل مع المخاطر مما قد يؤدي إلى ضعف في الاستجابة الفعالة عند وقوعها.'),
  (md5('cts-v0.2.1-item-69')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-12')::uuid, 69, 'الخطة تتضمن إجراءات لمنع حدوث الخطر أو تقليل تأثيره.', 'إضافة إجراءات استباقية ضمن خطة إدارة المخاطر تهدف إلى منع حدوث الأخطار أو تقليل تأثيرها في حال وقوعها.', 'تشمل خطة إدارة المخاطر إجراءات استباقية لمنع حدوث الخطر أو تقليل تأثيره مما يضمن تقليل التحديات وتعزيز استمرارية العمليات.', 'لا تحتوي خطة إدارة المخاطر على إجراءات لمنع حدوث الأخطار أو تقليل تأثيرها مما يزيد من احتمالية تأثر الجمعية بشكل سلبي عند وقوعها.'),
  (md5('cts-v0.2.1-item-70')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-12')::uuid, 70, 'يوجد تحديد واضح للمسؤول عن تنفيذ إجراءات التعامل مع الخطر.', 'تحديد المسؤوليات بشكل دقيق لكل إجراء متعلق بإدارة المخاطر مع توثيق ذلك في الخطة وإبلاغ الأطراف المعنية.', 'تتضمن خطة إدارة المخاطر تحديداً واضحاً للمسؤوليات المتعلقة بتنفيذ إجراءات التعامل مع كل خطر مما يعزز التنظيم والمساءلة.', 'لا يوجد تحديد واضح للمسؤوليات المتعلقة بتنفيذ إجراءات التعامل مع المخاطر مما قد يؤدي إلى تداخل الأدوار وتأخير الاستجابة.'),
  (md5('cts-v0.2.1-item-71')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-12')::uuid, 71, 'خطة إدارة المخاطر معتمدة ويظهر تاريخ الاعتماد وجهته.', 'اعتماد خطة إدارة المخاطر من الجهة المختصة مع تضمين تاريخ الاعتماد وجهته في الوثيقة الرسمية.', 'تم اعتماد خطة إدارة المخاطر رسمياً من الجهة المختصة ويظهر فيها تاريخ الاعتماد مما يعزز موثوقيتها ويضمن الالتزام بتطبيقها.', 'لم يتم اعتماد خطة إدارة المخاطر أو لا يظهر تاريخ الاعتماد وجهته مما يقلل من مصداقيتها واستخدامها كمرجع رسمي.'),
  (md5('cts-v0.2.1-item-72')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-12')::uuid, 72, 'خطة إدارة المخاطر محدثة ويظهر تاريخ آخر تحديث.', 'وضع جدول زمني لتحديث خطة إدارة المخاطر بانتظام وتحديثها مع توثيق تاريخ آخر تحديث في الوثيقة لضمان استمرارية ملاءمتها.', 'تحرص الجمعية على تحديث خطة إدارة المخاطر بانتظام مع الإشارة إلى تاريخ آخر تحديث مما يضمن توافقها مع المتغيرات والظروف الحالية.', 'خطة إدارة المخاطر غير محدثة أو لا يظهر فيها تاريخ آخر تحديث مما يجعلها غير متوافقة مع التغيرات وقد تؤدي إلى عدم فعاليتها.'),
  (md5('cts-v0.2.1-item-73')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-13')::uuid, 73, 'يوجد توثيق يظهر تخطيط الجمعية لمراجعة إجراءات التعامل مع المخاطر.', 'إعداد خطة موثقة لمراجعة إجراءات التعامل مع المخاطر بشكل دوري مع تحديد المواعيد والمسؤوليات لضمان تحديثها المستمر.', 'توفر الجمعية توثيقاً واضحاً يثبت تخطيطها المنتظم لمراجعة إجراءات التعامل مع المخاطر مما يضمن تحسينها باستمرار وملاءمتها للمتغيرات.', 'لا يوجد توثيق يثبت أن الجمعية تخطط لمراجعة إجراءات التعامل مع المخاطر مما قد يؤدي إلى احتمال عدم توافق هذه الإجراءات مع التحديات المستجدة.'),
  (md5('cts-v0.2.1-item-74')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-13')::uuid, 74, 'يوجد توثيق يظهر تنفيذ الجمعية لمراجعة إجراءات التعامل مع المخاطر.', 'إنشاء سجل موثق لجميع عمليات مراجعة إجراءات التعامل مع المخاطر مع تضمين النتائج والتوصيات لضمان الاستفادة منها.', 'تقوم الجمعية بتوثيق تنفيذها لمراجعات دورية على إجراءات التعامل مع المخاطر مما يعزز مصداقية النظام وإمكانية تطويره باستمرار.', 'لا يوجد توثيق يثبت أن الجمعية قامت بتنفيذ مراجعات لإجراءات التعامل مع المخاطر مما قد يؤدي إلى صعوبة التحقق من فعالية هذه الإجراءات.'),
  (md5('cts-v0.2.1-item-75')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-13')::uuid, 75, 'العاملين في الجمعية لديهم وعي بآخر تحديث على إجراءات التعامل مع المخاطر.', 'وضع آلية لإبلاغ العاملين بأي تحديث يتم على إجراءات التعامل مع المخاطر مع تنظيم جلسات توعية أو تدريب لضمان فهمهم وتطبيقهم للإجراءات الجديدة.', 'تحرص الجمعية على إبلاغ العاملين بآخر تحديث على إجراءات التعامل مع المخاطر مما يضمن جاهزيتهم وتوافقهم مع الإجراءات الجديدة.', 'العاملون في الجمعية غير مطلعين على آخر تحديث لإجراءات التعامل مع المخاطر مما قد يؤدي إلى تطبيق ممارسات قديمة وغير فعّالة.'),
  (md5('cts-v0.2.1-item-76')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-14')::uuid, 76, 'حددت الجمعية العمليات الرئيسية بشكل دقيق.', 'إجراء تحليل شامل لتحديد العمليات الرئيسية بدقة مع توثيقها لضمان وضوحها لجميع العاملين والأطراف ذات العلاقة.', 'قامت الجمعية بتحديد العمليات الرئيسية بدقة مما يضمن وضوح المهام وتركيز الجهود على تحقيق الأهداف الأساسية.', 'لم تقم الجمعية بتحديد العمليات الرئيسية بشكل دقيق مما قد يؤدي إلى تداخل في المهام وصعوبة في تحقيق الكفاءة التشغيلية.'),
  (md5('cts-v0.2.1-item-77')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-14')::uuid, 77, 'طورت الجمعية هيكلاً تنظيمياً يحدد الأدوار والمسؤوليات بوضوح.', 'تصميم هيكل تنظيمي يوضح الأدوار والمسؤوليات بشكل دقيق مع تحديثه بانتظام ليتماشى مع تطورات العمل.', 'طورت الجمعية هيكلاً تنظيمياً واضحاً يحدد الأدوار والمسؤوليات بدقة مما يعزز من التنظيم والمساءلة.', 'الهيكل التنظيمي غير واضح أو لا يحدد الأدوار والمسؤوليات بشكل دقيق مما قد يؤدي إلى غموض في المهام وتداخل الأدوار.'),
  (md5('cts-v0.2.1-item-78')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-14')::uuid, 78, 'الهيكل التنظيمي متسق ومتوافق مع العمليات الرئيسية.', 'مراجعة الهيكل التنظيمي لضمان توافقه مع العمليات الرئيسية مع إجراء التعديلات اللازمة لتحقيق الانسجام.', 'يتسم الهيكل التنظيمي للجمعية بالتناسق والتوافق مع العمليات الرئيسية مما يضمن سهولة تنفيذ المهام وتحقيق الكفاءة.', 'الهيكل التنظيمي غير متسق مع العمليات الرئيسية مما قد يؤدي إلى ضعف في تنفيذ العمليات وعدم تحقيق الانسجام بين الأدوار.'),
  (md5('cts-v0.2.1-item-79')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-14')::uuid, 79, 'يوجد توثيق للهيكل التنظيمي وجميع العمليات الرئيسية بشكل واضح.', 'إعداد وثائق تفصيلية توضح الهيكل التنظيمي والعمليات الرئيسية مع ضمان سهولة الوصول إليها لجميع الأطراف ذات العلاقة.', 'تحرص الجمعية على توثيق الهيكل التنظيمي وجميع العمليات الرئيسية بشكل واضح مما يسهل الرجوع إليها كمرجع رسمي.', 'لا يوجد توثيق واضح للهيكل التنظيمي والعمليات الرئيسية مما قد يؤدي إلى صعوبة في التوجيه والتنسيق بين الفرق.'),
  (md5('cts-v0.2.1-item-80')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-14')::uuid, 80, 'وثائق الهيكل التنظيمي وجميع العمليات الرئيسية متاحة وسهلة الوصول لجميع الأطراف المعنية.', 'وضع آلية لجعل الوثائق متاحة وسهلة الوصول لجميع الأطراف المعنية مع استخدام وسائل إلكترونية لتسهيل الاطلاع عليها.', 'توفر الجمعية الوثائق المتعلقة بالهيكل التنظيمي والعمليات الرئيسية بشكل متاح وسهل الوصول لجميع الأطراف المعنية مما يعزز الشفافية.', 'الوثائق المتعلقة بالهيكل التنظيمي والعمليات الرئيسية غير متاحة أو صعبة الوصول مما يعيق التنسيق والتواصل الفعّال.'),
  (md5('cts-v0.2.1-item-81')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-14')::uuid, 81, 'الهيكل التنظيمي معتمد ويظهر تاريخ الاعتماد وجهته.', 'ضمان اعتماد الهيكل التنظيمي من الجهة المختصة مع تضمين تاريخ الاعتماد وجهته لضمان الالتزام والمصداقية.', 'الهيكل التنظيمي معتمد رسمياً من الجهة المختصة ويظهر فيه تاريخ الاعتماد وجهته مما يعزز الموثوقية والالتزام بتطبيقه.', 'الهيكل التنظيمي غير معتمد أو لا يظهر فيه تاريخ الاعتماد وجهته مما يقلل من موثوقيته كوثيقة مرجعية.'),
  (md5('cts-v0.2.1-item-82')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-15')::uuid, 82, 'تنفذ الجمعية مراجعات دورية لتقييم كفاءة الهيكل التنظيمي وفعاليته.', 'تصميم جدول زمني للمراجعات الدورية لتقييم كفاءة وفعالية الهيكل التنظيمي مع إعداد تقارير توضح نتائج التقييم والتوصيات.', 'تحرص الجمعية على تنفيذ مراجعات دورية لتقييم كفاءة وفعالية الهيكل التنظيمي مما يساهم في تحسين الأداء وضمان توافقه مع الأهداف.', 'لا تقوم الجمعية بإجراء مراجعات دورية لتقييم كفاءة وفعالية الهيكل التنظيمي مما قد يؤدي إلى استمرارية العملبهيكل قد لا يكون مناسباً.'),
  (md5('cts-v0.2.1-item-83')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-15')::uuid, 83, 'جميع التعديلات التي تُجرى على الهيكل التنظيمي موثقة بوضوح وتُتاح لجميع الأطراف ذات الصلة.', 'إنشاء آلية لتوثيق جميع التعديلات التي تُجرى على الهيكل التنظيمي مع ضمان إتاحتها لجميع الأطراف ذات العلاقة بسهولة.', 'توثق الجمعية جميع التعديلات التي تُجرى على الهيكل التنظيمي بشكل واضح وتحرص على إتاحتها للأطراف ذات الصلة مما يعزز الشفافية والتنظيم.', 'لا يتم توثيق التعديلات التي تُجرى على الهيكل التنظيمي أو لا تُتاح للأطراف ذات الصلة مما قد يؤدي إلى غموض وصعوبة في متابعة التغييرات.'),
  (md5('cts-v0.2.1-item-84')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-15')::uuid, 84, 'يوجد دليل على مشاركة ذوي العلاقة في تحديث وتطوير الهيكل.', 'وضع آلية تضمن مشاركة ذوي العلاقة في عمليات تحديث وتطوير الهيكل التنظيمي مع توثيق مساهماتهم ونتائج مشاركتهم.', 'تضمن الجمعية مشاركة ذوي العلاقة في عملية تحديث وتطوير الهيكل التنظيمي مما يعزز التوافق مع احتياجات الأطراف ذات الصلة.', 'لا توجد أدلة على مشاركة ذوي العلاقة في تحديث وتطوير الهيكل التنظيمي مما قد يؤدي إلى ضعف التوافق مع احتياجات الجهات المعنية.'),
  (md5('cts-v0.2.1-item-85')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-15')::uuid, 85, 'الهيكل التنظيمي الحالي محدّث ويعكس واقع الجمعية.', 'إجراء مراجعة شاملة لتحديث الهيكل التنظيمي الحالي مع ضمان توافقه مع التغيرات والمتطلبات الواقعية للجمعية.', 'يتسم الهيكل التنظيمي الحالي للجمعية بالتحديث الدوري ويعكس بدقة الواقع التنظيمي للجمعية مما يدعم العمليات التشغيلية بكفاءة.', 'الهيكل التنظيمي الحالي غير محدث أو لا يعكس واقع الجمعية مما قد يؤدي إلى قصور في توجيه المهام والمسؤوليات.'),
  (md5('cts-v0.2.1-item-86')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-15')::uuid, 86, 'يظهر في وثيقة الهيكل التنظيمي تاريخ آخر تحديث ورقم الإصدار.', 'إضافة تاريخ آخر تحديث ورقم الإصدار إلى وثيقة الهيكل التنظيمي مع تحديثهما عند إجراء أي تغييرات على الهيكل.', 'تحتوي وثيقة الهيكل التنظيمي على تاريخ آخر تحديث ورقم الإصدار مما يضمن وضوح النسخة المستخدمة وتفادي الالتباس.', 'لا تحتوي وثيقة الهيكل التنظيمي على تاريخ آخر تحديث أو رقم الإصدار مما قد يؤدي إلى عدم وضوح النسخة المعتمدة وصعوبة تتبع التغييرات.'),
  (md5('cts-v0.2.1-item-87')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-16')::uuid, 87, 'حددت الجمعية الجدارات الوظيفية المطلوبة لإنجاز مهام تنفيذ البرامج وتقديم الخدمات بدقة.', 'إجراء تحليل شامل لتحديد الجدارات الوظيفية المطلوبة لكل مهمة في تنفيذ البرامج وتقديم الخدمات مع توثيقها لضمان الوضوح.', 'قامت الجمعية بتحديد الجدارات الوظيفية المطلوبة بدقة لإنجاز مهام تنفيذ البرامج وتقديم الخدمات مما يضمن اختيار الكفاءات المناسبة لتحقيق الأهداف.', 'لم تقم الجمعية بتحديد الجدارات الوظيفية المطلوبة بدقة مما قد يؤدي إلى قصور في الأداء وصعوبة في تحديد الكفاءات اللازمة.'),
  (md5('cts-v0.2.1-item-88')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-16')::uuid, 88, 'تحديد الجدارات الوظيفية شامل ويغطي جميع الوظائف الفنية في الهيكل التنظيمي للجمعية.', 'مراجعة الجدارات الوظيفية للتأكد من شمولها لجميع الوظائف الفنية في الهيكل التنظيمي مع تحديثها لضمان التوافق مع احتياجات الجمعية.', 'يشمل تحديد الجدارات الوظيفية جميع الوظائف الفنية في الهيكل التنظيمي للجمعية مما يضمن تغطية شاملة لجميع المهام والمسؤوليات.', 'لا يغطي تحديد الجدارات الوظيفية جميع الوظائف الفنية في الهيكل التنظيمي مما قد يؤدي إلى فجوات في المهارات المطلوبة لبعض الوظائف.'),
  (md5('cts-v0.2.1-item-89')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-16')::uuid, 89, 'هناك توثيق للجدارات الوظيفية بوضوح في دليل للجدارات أو وثائق التوصيف الوظيفي أو أي وثيقة أخرى مناسبة.', 'إعداد دليل شامل للجدارات الوظيفية أو تضمينها في وثائق التوصيف الوظيفي مع التأكد من وضوح التفاصيل وسهولة الرجوع إليها.', 'تم توثيق الجدارات الوظيفية بوضوح في دليل للجدارات أو وثائق التوصيف الوظيفي مما يسهل الرجوع إليها وتطبيقها عملياً.', 'لا يوجد توثيق واضح للجدارات الوظيفية في دليل أو وثائق مناسبة مما قد يؤدي إلى غموض في تحديد المهارات والكفاءات المطلوبة.'),
  (md5('cts-v0.2.1-item-90')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-16')::uuid, 90, 'تراجع الجمعية الجدارات الوظيفية بشكل دوري لتتوافق مع التغيرات في البرامج والخدمات.', 'إدراج مراجعة دورية للجدارات الوظيفية في خطة العمل السنوية مع ضمان تعديلها لتواكب التغيرات في البرامج والخدمات.', 'تقوم الجمعية بمراجعة دورية للجدارات الوظيفية لتتوافق مع التغيرات في البرامج والخدمات مما يضمن مواكبة الكفاءات لمتطلبات العمل.', 'لا تجري الجمعية مراجعات دورية للجدارات الوظيفية مما قد يؤدي إلى عدم توافق الكفاءات مع التغيرات في البرامج والخدمات.'),
  (md5('cts-v0.2.1-item-91')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-16')::uuid, 91, 'وثيقة الجدارات محدثة ويظهر تاريخ آخر تحديث فيها.', 'تحديث وثيقة الجدارات الوظيفية بشكل دوري مع تضمين تاريخ آخر تحديث لضمان دقتها ومواءمتها مع احتياجات الجمعية.', 'تحرص الجمعية على تحديث وثيقة الجدارات الوظيفية بانتظام مع توضيح تاريخ آخر تحديث لضمان استخدامها كمرجع موثوق.', 'وثيقة الجدارات الوظيفية غير محدثة أو لا يظهر فيها تاريخ آخر تحديث مما يقلل من موثوقيتها وفعاليتها كمرجع.'),
  (md5('cts-v0.2.1-item-92')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-16')::uuid, 92, 'وثيقة الجدارات الوظيفية متاحة لجميع الموظفين ذوي العلاقة.', 'توفير وثيقة الجدارات الوظيفية لجميع الموظفين ذوي العلاقة سواء إلكترونياً أو ورقياً مع ضمان سهولة الوصول إليها.', 'تُتاح وثيقة الجدارات الوظيفية لجميع الموظفين ذوي العلاقة مما يضمن وضوح المهام والكفاءات المطلوبة لكل وظيفة.', 'وثيقة الجدارات الوظيفية غير متاحة للموظفين ذوي العلاقة مما قد يؤدي إلى ضعف في وضوح المهام وصعوبة في تحسين الأداء.'),
  (md5('cts-v0.2.1-item-93')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-17')::uuid, 93, 'التوصيفات الوظيفية مكتوبة لجميع الوظائف الفنية في الهيكل التنظيمي.', 'إعداد توصيفات وظيفية مكتوبة لجميع الوظائف الفنية في الهيكل التنظيمي مع التأكد من شموليتها ودقتها.', 'تمتلك الجمعية  توصيفات وظيفية مكتوبة تغطي جميع الوظائف الفنية في الهيكل التنظيمي مما يضمن وضوح الأدوار والمسؤوليات.', 'لا توجد توصيفات وظيفية مكتوبة لبعض الوظائف الفنية مما قد يؤدي إلى غموض في المهام والمسؤوليات وصعوبة في تقييم الأداء.'),
  (md5('cts-v0.2.1-item-94')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-17')::uuid, 94, 'حُددت المهام والمسؤوليات لكل وظيفة بوضوح ودقة.', 'تحديث التوصيفات الوظيفية لضمان تحديد دقيق وواضح للمهام والمسؤوليات لكل وظيفة مع إشراك الموظفين في عملية التحديث.', 'التوصيفات الوظيفية تحتوي على تحديد واضح ودقيق للمهام والمسؤوليات لكل وظيفة مما يعزز الكفاءة والفعالية في العمل.', 'لم يتم تحديد المهام والمسؤوليات بشكل واضح لبعض الوظائف مما قد يؤدي إلى تداخل الأدوار وصعوبة تحقيق الأهداف.'),
  (md5('cts-v0.2.1-item-95')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-17')::uuid, 95, 'حددت المؤهلات والخبرات اللازمة لشغل كل وظيفة فنية.', 'إضافة المؤهلات والخبرات اللازمة لشغل كل وظيفة فنية في التوصيفات الوظيفية مع مراجعتها بشكل دوري لضمان توافقها مع متطلبات العمل.', 'تتضمن التوصيفات الوظيفية تحديداً واضحاً للمؤهلات والخبرات اللازمة لشغل كل وظيفة فنية مما يضمن اختيار الكفاءات المناسبة.', 'لا تحتوي التوصيفات الوظيفية على تحديد دقيق للمؤهلات والخبرات المطلوبة مما قد يؤدي إلى ضعف في اختيار الموارد البشرية الملائمة.'),
  (md5('cts-v0.2.1-item-96')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-17')::uuid, 96, 'التوصيفات الوظيفية متوافقة مع الأنظمة والمعايير المُعتمدة ذات العلاقة.', 'مراجعة التوصيفات الوظيفية لضمان توافقها مع الأنظمة والمعايير المعتمدة مع تحديثها بما يتماشى مع المتطلبات الجديدة.', 'تراعي الجمعية توافق التوصيفات الوظيفية مع الأنظمة والمعايير المعتمدة مما يعزز الامتثال ويضمن الالتزام التنظيمي.', 'لا تتوافق التوصيفات الوظيفية مع الأنظمة أو المعايير المعتمدة مما قد يؤدي إلى احتمالية وجود تجاوزات تنظيمية أو قانونية.'),
  (md5('cts-v0.2.1-item-97')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-17')::uuid, 97, 'التوصيفات الوظيفية متاحة للموظفين والمسؤولين للاطلاع عليها عند الحاجة.', 'توفير التوصيفات الوظيفية إلكترونياً وورقياً لتكون متاحة لجميع الموظفين والمسؤولين مع ضمان سهولة الوصول إليها عند الحاجة.', 'تُتاح التوصيفات الوظيفية بسهولة للموظفين والمسؤولين مما يسهل الرجوع إليها لفهم الأدوار والمسؤوليات.', 'التوصيفات الوظيفية غير متاحة للموظفين أو المسؤولين مما يسبب غموضاً في المهام وصعوبة في تحقيق التوافق الوظيفي.'),
  (md5('cts-v0.2.1-item-98')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-17')::uuid, 98, 'تُراجع التوصيفات الوظيفية بانتظام لضمان استمرار توافقها مع التغيرات في الهيكل التنظيمي أو الأنظمة.', 'إدراج مراجعة دورية للتوصيفات الوظيفية في خطة العمل السنوية مع إجراء التعديلات اللازمة وفقاً للتغيرات.', 'تجري الجمعية مراجعات دورية للتوصيفات الوظيفية مما يضمن توافقها مع التغيرات التنظيمية والقانونية.', 'لا يتم إجراء مراجعات دورية للتوصيفات الوظيفية مما قد يؤدي إلى عدم توافقها مع التغيرات في الهيكل التنظيمي أو الأنظمة.'),
  (md5('cts-v0.2.1-item-99')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-17')::uuid, 99, 'التوصيفات الوظيفية معتمدة ويمكن إظهار تاريخ الاعتماد.', 'ضمان اعتماد التوصيفات الوظيفية رسمياً من الجهة المختصة مع تضمين تواريخ الاعتماد لتوثيقها بشكل رسمي.', 'التوصيفات الوظيفية معتمدة من الجهة المختصة وتظهر فيها تواريخ الاعتماد بوضوح مما يعزز مصداقيتها كوثائق رسمية.', 'لم يتم اعتماد التوصيفات الوظيفية أو لا تحتوي على تواريخ اعتماد مما يقلل من موثوقيتها وفعاليتها كمرجع تنظيمي.'),
  (md5('cts-v0.2.1-item-100')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-17')::uuid, 100, 'التوصيفات الوظيفية محدّثة ويظهر فيها تاريخ آخر تحديث.', 'تحديث التوصيفات الوظيفية بانتظام مع تضمين تاريخ آخر تحديث لضمان وضوح النسخة المعتمدة ودقتها.', 'تحرص الجمعية على تحديث التوصيفات الوظيفية بانتظام مع توضيح تاريخ آخر تحديث لضمان دقتها وملاءمتها للاحتياجات الحالية.', 'التوصيفات الوظيفية غير محدثة أو لا تحتوي على تاريخ آخر تحديث مما يجعلها غير متوافقة مع الواقع التنظيمي الحالي.'),
  (md5('cts-v0.2.1-item-101')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-18')::uuid, 101, 'حللت الجمعية حجم العمل الحالي والمتوقع لتحديد الاحتياجات الفعلية من الموظفين.', 'إجراء تحليل شامل لحجم العمل الحالي والمتوقع مع تحديد الاحتياجات الفعلية من الموظفين بناءً على البيانات التشغيلية والبرامج المستقبلية.', 'قامت الجمعية بتحليل حجم العمل الحالي والمتوقع بدقة لتحديد الاحتياجات الفعلية من الموظفين مما يضمن توافر الموارد البشرية اللازمة لتحقيق الأهداف بكفاءة.', 'لم تقم الجمعية بتحليل حجم العمل الحالي أو المتوقع بشكل كافٍ مما قد يؤدي إلى نقص أو فائض في الموظفين وصعوبة تحقيق التوازن الوظيفي.'),
  (md5('cts-v0.2.1-item-102')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-18')::uuid, 102, 'حددت الجمعية الفجوات في احتياجاتها من الموظفين عددا ونوعا.', 'وضع آلية شاملة لتحديد الفجوات في احتياجات الموظفين من حيث العدد والنوع مع مراجعة دورية لهذه الاحتياجات بناءً على متطلبات البرامج والخدمات.', 'تقوم الجمعية بتحديد الفجوات في احتياجاتها من الموظفين من حيث العدد والنوع بشكل دقيق مما يُسهم في تحسين كفاءة التوظيف وتلبية احتياجات البرامج والخدمات.', 'لا تُحدد الجمعية الفجوات في احتياجاتها من الموظفين من حيث العدد والنوع مما قد يؤدي إلى نقص الكفاءات اللازمة وصعوبة تنفيذ البرامج والخدمات بكفاءة.'),
  (md5('cts-v0.2.1-item-103')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-18')::uuid, 103, 'لدى الجمعية خطة واضحة للتوظيف تشمل جدول زمني وأولويات وتحديد للتكاليف المتوقعة.', 'إعداد خطة توظيف شاملة تتضمن جدولاً زمنياً وأولويات واضحة وتقديراً للتكاليف المتوقعة مع مراجعتها لتتوافق مع الاحتياجات الفعلية.', 'تمتلك الجمعية خطة توظيف واضحة ومفصلة تشمل جدولاً زمنياً وأولويات وتحديداً دقيقاً للتكاليف المتوقعة مما يسهل تنفيذ خطط التوظيف بكفاءة وفعالية.', 'لا توجد لدى الجمعية خطة توظيف واضحة أو لا تشمل الجدول الزمني والأولويات والتكاليف المتوقعة مما قد يؤدي إلى عشوائية في عمليات التوظيف وصعوبة في تخصيص الموارد.'),
  (md5('cts-v0.2.1-item-104')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-18')::uuid, 104, 'خطة التوظيف محدّثة بشكل منتظم لمواكبة المستجدات.', 'وضع جدول زمني لمراجعة وتحديث خطة التوظيف بانتظام مع ضمان توافقها مع التغيرات في البرامج والأهداف.', 'تحرص الجمعية على تحديث خطة التوظيف بانتظام لتواكب المستجدات في حجم العمل والاحتياجات الوظيفية مما يعزز مرونتها وفعاليتها.', 'خطة التوظيف غير محدثة أو لا يتم مراجعتها بانتظام مما قد يؤدي إلى صعوبة مواكبة التغيرات في حجم العمل أو الأولويات.'),
  (md5('cts-v0.2.1-item-105')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-18')::uuid, 105, 'خطة التوظيف معتمدة ويظهر تاريخ وجهة الاعتماد.', 'اعتماد خطة التوظيف من الجهة المختصة مع توضيح تاريخ وجهة الاعتماد في الوثيقة لتعزيز موثوقيتها.', 'خطة التوظيف معتمدة رسمياً وتحتوي على تاريخ وجهة الاعتماد مما يعزز من موثوقيتها واعتمادها كمرجع رسمي لتنفيذ التوظيف.', 'لم يتم اعتماد خطة التوظيف أو لا يظهر فيها تاريخ وجهة الاعتماد مما يقلل من مصداقيتها ويحد من استخدامها كوثيقة رسمية.'),
  (md5('cts-v0.2.1-item-106')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-19')::uuid, 106, 'تتأكد الجمعية أن جميع البرامج والخدمات لديها الكادر البشري اللازم لتحقيق الأهداف.', 'إجراء تقييم دوري لتحديد الاحتياجات الفعلية من الكادر البشري لكل برنامج أو خدمة وضمان تغطيتها بشكل كامل.', 'تحرص الجمعية على ضمان توافر الكادر البشري اللازم لجميع البرامج والخدمات لتحقيق الأهداف بكفاءة وفعالية.', 'لا تضمن الجمعية توافر الكادر البشري اللازم لبعض البرامج أو الخدمات مما قد يؤدي إلى تأخير في التنفيذ أو ضعف في جودة الخدمات.'),
  (md5('cts-v0.2.1-item-107')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-19')::uuid, 107, 'الكفاءات المطلوبة للموظفين والمتطوعين تتوافق مع المعايير المُعتمدة في مجال عمل المنظمة.', 'تحديد الكفاءات المطلوبة للموظفين والمتطوعين بناءً على المعايير المعتمدة في المجال مع تضمينها في عمليات التوظيف والتدريب.', 'تتوافق الكفاءات المطلوبة للموظفين والمتطوعين في الجمعية مع المعايير المعتمدة في مجال عملها مما يعزز الاحترافية وجودة الأداء.', 'لا تتوافق الكفاءات المطلوبة للموظفين والمتطوعين مع المعايير المعتمدة مما قد يؤدي إلى ضعف في الأداء وصعوبة تحقيق الأهداف.'),
  (md5('cts-v0.2.1-item-108')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-19')::uuid, 108, 'يوجد سجل يوضح أعداد الموظفين أو المتطوعين لكل برنامج أو خدمة.', 'إعداد سجل محدّث يحتوي على أعداد الموظفين والمتطوعين المخصصين لكل برنامج أو خدمة مع مراجعة دورية للتأكد من دقته.', 'تمتلك الجمعية سجلاً موثقاً يوضح أعداد الموظفين والمتطوعين لكل برنامج أو خدمة مما يسهل تتبع التوزيع والاحتياجات البشرية.', 'لا يوجد سجل يوضح أعداد الموظفين والمتطوعين لكل برنامج أو خدمة مما قد يؤدي إلى صعوبة تقييم كفاية الكوادر البشرية وتوزيعها.'),
  (md5('cts-v0.2.1-item-109')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-19')::uuid, 109, 'يوجد تحليل لمناسبة أعداد الموظفين أو المتطوعين مع متطلبات تنفيذ البرامج وتقديم الخدمات.', 'إجراء تحليل دوري لمناسبة أعداد الموظفين والمتطوعين مع متطلبات البرامج والخدمات مع تعديل التوزيع لتلبية الاحتياجات الفعلية.', 'تجري الجمعية تحليلاً منتظماً لمناسبة أعداد الموظفين والمتطوعين مع متطلبات تنفيذ البرامج وتقديم الخدمات مما يضمن تلبية الاحتياجات بكفاءة.', 'لا يوجد تحليل لمناسبة أعداد الموظفين والمتطوعين مع متطلبات التنفيذ مما قد يؤدي إلى فجوات في التغطية البشرية أو توزيع غير فعال.'),
  (md5('cts-v0.2.1-item-110')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-20')::uuid, 110, 'صممت الجمعية برامج تهيئة شاملة للموظفين والمتطوعين تغطي المهام والمسؤوليات الأساسية.', 'تصميم برامج تهيئة شاملة للموظفين والمتطوعين تتضمن تعريفاً دقيقاً بالمهام والمسؤوليات الأساسية لضمان جاهزيتهم.', 'صممت الجمعية برامج تهيئة شاملة تغطي المهام والمسؤوليات الأساسية مما يضمن جاهزية الموظفين والمتطوعين لأداء أدوارهم بفعالية.', 'لا توجد برامج تهيئة شاملة تغطي المهام والمسؤوليات الأساسية مما قد يؤدي إلى ضعف في فهم الموظفين والمتطوعين لمتطلبات وظائفهم.'),
  (md5('cts-v0.2.1-item-111')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-20')::uuid, 111, 'نفذت الجمعية برامج توعية فعّالة تعرّف الموظفين والمتطوعين بمعايير تقديم الخدمات والتواصل مع المستفيدين.', 'إعداد وتنفيذ برامج توعية مخصصة لتعريف الموظفين والمتطوعين بمعايير تقديم الخدمات والتواصل مع المستفيدين.', 'تنفذ الجمعية برامج توعية فعّالة تعرّف الموظفين والمتطوعين بمعايير تقديم الخدمات وأسس التواصل مع المستفيدين مما يعزز جودة الخدمات المقدمة.', 'لا تنفذ الجمعية برامج توعية كافية لتعريف الموظفين والمتطوعين بمعايير تقديم الخدمات والتواصل مما قد يؤدي إلى ضعف في الأداء وجودة الخدمة.'),
  (md5('cts-v0.2.1-item-112')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-20')::uuid, 112, 'تُدرج متطلبات السلامة وحماية المستفيدين في برامج التهيئة والتوعية.', 'إدراج متطلبات السلامة وحماية المستفيدين كجزء أساسي من محتوى برامج التهيئة والتوعية مع تدريب خاص على تطبيقها.', 'تدمج الجمعية متطلبات السلامة وحماية المستفيدين في برامج التهيئة والتوعية مما يضمن التزام العاملين بأعلى معايير الأمان والرعاية.', 'لا تتضمن برامج التهيئة والتوعية متطلبات السلامة وحماية المستفيدين مما يزيد من مخاطر الإخلال بمعايير الحماية والأمان.'),
  (md5('cts-v0.2.1-item-113')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-20')::uuid, 113, 'تدرب الجمعية الموظفين والمتطوعين على أساليب التواصل الفعّال مع المستفيدين.', 'تصميم وتنفيذ برامج تدريبية تركّز على تطوير مهارات التواصل الفعّال مع المستفيدين للموظفين والمتطوعين.', 'توفر الجمعية تدريباً متخصصاً على أساليب التواصل الفعّال مع المستفيدين مما يسهم في تحسين تجربة المستفيد وجودة التفاعل.', 'لا تقدم الجمعية تدريباً كافياً على أساليب التواصل الفعّال مع المستفيدين مما قد يؤدي إلى ضعف في بناء علاقات إيجابية معهم.'),
  (md5('cts-v0.2.1-item-114')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-20')::uuid, 114, 'يتضمن البرنامج توعية الموظفين والمتطوعين بالأنظمة والمعايير المُعتمدة في مجال العمل.', 'تضمين الأنظمة والمعايير المعتمدة في مجال العمل ضمن برامج التهيئة والتوعية مع توفير مواد مرجعية للموظفين والمتطوعين.', 'يشمل برنامج التهيئة والتوعية تعريف الموظفين والمتطوعين بالأنظمة والمعايير المعتمدة مما يعزز الالتزام بالممارسات المهنية والأخلاقيات.', 'لا يتم تضمين الأنظمة والمعايير المعتمدة في برامج التهيئة والتوعية مما قد يؤدي إلى ضعف في الالتزام بالإجراءات والسياسات.'),
  (md5('cts-v0.2.1-item-115')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-20')::uuid, 115, 'تقيّم الجمعية فهم الموظفين والمتطوعين بعد إتمام برامج التهيئة والتوعية لضمان استيعابهم.', 'إعداد أدوات تقييم بعد كل برنامج تهيئة وتوعية لقياس مدى فهم الموظفين والمتطوعين مع تحسين البرامج بناءً على النتائج.', 'تجري الجمعية تقييمات شاملة بعد برامج التهيئة والتوعية لضمان استيعاب الموظفين والمتطوعين للمهام والمعايير المطلوبة.', 'لا تقوم الجمعية بتقييم فهم الموظفين والمتطوعين بعد إتمام برامج التهيئة مما يصعب تحديد مدى استيعابهم وفاعلية البرامج.'),
  (md5('cts-v0.2.1-item-116')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-20')::uuid, 116, 'تُراجع برامج التهيئة والتوعية بانتظام لضمان مواكبتها للتغيرات والاحتياجات الجديدة.', 'وضع جدول زمني لمراجعة دورية لبرامج التهيئة والتوعية مع تحديث المحتوى بما يتناسب مع المستجدات والاحتياجات.', 'تحرص الجمعية على مراجعة برامج التهيئة والتوعية بانتظام لتتوافق مع التغيرات والاحتياجات الجديدة مما يضمن فعاليتها واستمراريتها.', 'لا تتم مراجعة برامج التهيئة والتوعية بانتظام مما قد يؤدي إلى عدم مواكبتها للتغيرات والاحتياجات الجديدة.'),
  (md5('cts-v0.2.1-item-117')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-20')::uuid, 117, 'توثق الجمعية برامج التهيئة والتوعية ومحتوياتها لضمان الاتساق في التنفيذ.', 'إعداد وتوثيق شامل لجميع برامج التهيئة والتوعية ومحتوياتها مع توفير نسخة محدثة يسهل الوصول إليها.', 'توثق الجمعية برامج التهيئة والتوعية ومحتوياتها بشكل دقيق مما يضمن الاتساق في التنفيذ وسهولة الرجوع إليها عند الحاجة.', 'لا توجد توثيقات كافية لبرامج التهيئة والتوعية مما قد يؤدي إلى تفاوت في تنفيذها وصعوبة في مراجعتها أو تطويرها.'),
  (md5('cts-v0.2.1-item-118')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-21')::uuid, 118, 'تنفذ الجمعية تحليلاً دورياً لاحتياجات التعلّم والتطوير للموظفين والمتطوعين.', 'وضع جدول زمني دوري لإجراء تحليل احتياجات التعلم والتطوير مع إشراك الموظفين والمتطوعين لضمان دقة النتائج.', 'تحرص الجمعية على إجراء تحليل دوري لاحتياجات التعلّم والتطوير للموظفين والمتطوعين مما يساعد في تصميم برامج موجهة تلبي الاحتياجات الفعلية.', 'لا تنفذ الجمعية تحليلاً دورياً لاحتياجات التعلّم والتطوير مما قد يؤدي إلى نقص في البرامج الملائمة لتحسين أداء الموظفين والمتطوعين.'),
  (md5('cts-v0.2.1-item-119')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-21')::uuid, 119, 'تصمم الجمعية برامج تعلم وتطوير بناءً على نتائج التحليل لتلبية الاحتياجات المحددة.', 'تصميم برامج تعلم وتطوير تستند إلى نتائج تحليل الاحتياجات مع مراجعة مستمرة لضمان توافقها مع أولويات العمل.', 'تصمم الجمعية برامج تعلم وتطوير بناءً على نتائج التحليل مما يضمن استهداف الاحتياجات الحقيقية وتعزيز كفاءة الموظفين والمتطوعين.', 'لا تصمم الجمعية برامج تعلم وتطوير تستند إلى نتائج تحليل الاحتياجات مما قد يؤدي إلى تقديم برامج غير متوائمة مع الاحتياجات الفعلية.'),
  (md5('cts-v0.2.1-item-120')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-21')::uuid, 120, 'يوجد خطة موثقة لبرامج التعلّم والتطوير للموظفين والمتطوعين.', 'إعداد خطة موثقة وشاملة لبرامج التعلّم والتطوير مع تضمين الأهداف وآليات التنفيذ لضمان التنظيم الفعّال.', 'تمتلك الجمعية خطة موثقة لبرامج التعلّم والتطوير للموظفين والمتطوعين مما يضمن وضوح الأهداف والأنشطة التدريبية المطلوبة.', 'لا توجد خطة موثقة لبرامج التعلّم والتطوير مما قد يؤدي إلى غياب التنظيم وعدم وضوح الأهداف التدريبية.'),
  (md5('cts-v0.2.1-item-121')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-21')::uuid, 121, 'تحدد الخطة البرامج التدريبية وبرامج التعلّم لجميع الموظفين والمتطوعين.', 'تحديث الخطة لتتضمن برامج تدريبية واضحة لجميع الموظفين والمتطوعين مع تخصيص فرص تدريبية تناسب كل فئة.', 'تتضمن الخطة تحديداً واضحاً للبرامج التدريبية وبرامج التعلّم لجميع الموظفين والمتطوعين مما يسهم في تخصيص الفرص التدريبية بناءً على الاحتياجات.', 'لا تحدد الخطة البرامج التدريبية بشكل شامل مما قد يؤدي إلى نقص في توزيع الفرص التدريبية بشكل عادل ومنظم.'),
  (md5('cts-v0.2.1-item-122')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-21')::uuid, 122, 'تتضمن الخطة تحديداً للموارد المطلوبة والتكاليف.', 'إضافة تفاصيل حول الموارد المطلوبة والتكاليف في خطة التعلم والتطوير مع مراجعتها لضمان دقة التقديرات المالية.', 'تتضمن خطة التعلم والتطوير تحديداً دقيقاً للموارد المطلوبة والتكاليف مما يضمن التخطيط المالي الفعّال وتنفيذ البرامج بكفاءة.', 'لا تحتوي الخطة على تحديد واضح للموارد المطلوبة والتكاليف مما قد يؤدي إلى عشوائية في التخطيط وصعوبة في تنفيذ البرامج.'),
  (md5('cts-v0.2.1-item-123')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-21')::uuid, 123, 'الخطة محدثة ومعتمدة ويظهر تاريخ وجهة الاعتماد.', 'مراجعة وتحديث الخطة بانتظام مع توضيح تاريخ الاعتماد وجهته لتعزيز مصداقيتها وتنظيمها.', 'الخطة محدثة ومعتمدة رسمياً ويظهر فيها تاريخ الاعتماد وجهته مما يعزز مصداقيتها كوثيقة مرجعية معتمدة.', 'الخطة غير محدثة أو لا تحتوي على تاريخ وجهة الاعتماد مما يقلل من موثوقيتها واستخدامها كمرجع رسمي.'),
  (md5('cts-v0.2.1-item-124')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-21')::uuid, 124, 'لدى الموظفين وعي ببرامج التعلم والتطوير الخاصة بهم والمحددة في الخطة.', 'تنظيم جلسات تعريفية للموظفين والمتطوعين حول برامج التعلم والتطوير الخاصة بهم مع توفير المواد اللازمة لتعزيز الوعي.', 'تحرص الجمعية على توعية الموظفين ببرامج التعلم والتطوير المخصصة لهم والمحددة في الخطة مما يعزز مشاركتهم واستفادتهم منها.', 'لا يوجد لدى الموظفين وعي كافٍ ببرامج التعلم والتطوير المخصصة لهم مما قد يؤدي إلى انخفاض الاستفادة من الفرص التدريبية.'),
  (md5('cts-v0.2.1-item-125')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-22')::uuid, 125, 'تنفذ الجمعية برامج التعلّم والتطوير وفقًا للخطة المعتمدة لضمان تحقيق الأهداف.', 'التأكد من تنفيذ برامج التعلم والتطوير بما يتماشى مع الخطة المعتمدة مع وضع آليات متابعة لضمان الالتزام وتنفيذ البرامج بكفاءة.', 'تلتزم الجمعية بتنفيذ برامج التعلم والتطوير بدقة وفقًا للخطة المعتمدة مما يضمن تحقيق الأهداف المحددة بكفاءة وفعالية.', 'لا يتم تنفيذ برامج التعلم والتطوير وفقًا للخطة المعتمدة مما قد يؤدي إلى صعوبة تحقيق الأهداف المرسومة وضعف نتائج التعلم.'),
  (md5('cts-v0.2.1-item-126')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-22')::uuid, 126, 'تُتاح فرص التعلم والتطوير لجميع الموظفين والمتطوعين دون تمييز.', 'وضع سياسة تضمن إتاحة فرص التعلم والتطوير لجميع الموظفين والمتطوعين على قدم المساواة مع مراقبة تنفيذها بشكل دوري.', 'تضمن الجمعية إتاحة فرص التعلم والتطوير لجميع الموظفين والمتطوعين دون تمييز مما يعزز العدالة والشفافية في تقديم البرامج.', 'لا يتم إتاحة فرص التعلم والتطوير لجميع الموظفين والمتطوعين بالتساوي مما قد يؤدي إلى شعور بعدم العدالة وضعف التزام البعض بالبرامج.'),
  (md5('cts-v0.2.1-item-127')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-22')::uuid, 127, 'تُوفر الجمعية الموارد الكافية مثل المدربين ومواد تدريبية ووقت لتنفيذ البرامج بشكل فعال.', 'تقييم الموارد اللازمة لكل برنامج تدريب وتوفيرها مسبقًا مع تخصيص ميزانية مناسبة وضمان استدامة الموارد المطلوبة.', 'تحرص الجمعية على توفير جميع الموارد اللازمة مثل المدربين والمواد التدريبية والوقت الكافي لضمان تنفيذ برامج التعلم والتطوير بجودة عالية.', 'لا تُوفر الجمعية الموارد الكافية لتنفيذ برامج التعلم والتطوير مما قد يؤدي إلى انخفاض جودة البرامج وصعوبة تحقيق الأهداف.'),
  (md5('cts-v0.2.1-item-128')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-22')::uuid, 128, 'توثق الجمعية تفاصيل برامج التعلم والتطوير بما في ذلك الأهداف والمشاركين والمخرجات.', 'إنشاء نظام توثيق موحد لجميع برامج التعلم والتطوير يشمل الأهداف والمشاركين والمخرجات مع تحديث السجلات بعد كل برنامج.', 'توثق الجمعية جميع تفاصيل برامج التعلم والتطوير بما يشمل الأهداف المشاركين والمخرجات مما يسهل مراجعة الأداء وتحسينه مستقبلاً.', 'لا تقوم الجمعية بتوثيق تفاصيل برامج التعلم والتطوير بشكل كافٍ مما قد يؤدي إلى فقدان البيانات وصعوبة تقييم فاعلية البرامج.'),
  (md5('cts-v0.2.1-item-129')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-22')::uuid, 129, 'تحتفظ الجمعية بسجلات محدثة لكل موظف ومتطوع تشمل البرامج التي شارك فيها ونواتج التعلم.', 'إعداد  سجل محدث لكل موظف ومتطوع يشمل تفاصيل البرامج التي شارك فيها ونواتج التعلم مع مراجعة دورية لضمان دقته.', 'تحتفظ الجمعية بسجلات محدثة لكل موظف ومتطوع توضح البرامج التي شاركوا فيها ونواتج التعلم مما يسهل متابعة تطورهم المهني.', 'لا تحتفظ الجمعية بسجلات محدثة لكل موظف ومتطوع مما قد يؤدي إلى صعوبة تتبع المشاركات التدريبية وتقييم التحسينات المهنية.'),
  (md5('cts-v0.2.1-item-130')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-23')::uuid, 130, 'تعتمد الجمعية سياسات مكتوبة وشاملة لضمان سلامة الموظفين والمتطوعين أثناء تنفيذ البرامج وتقديم الخدمات.', 'صياغة واعتماد سياسات مكتوبة وشاملة لضمان سلامة الموظفين والمتطوعين مع توضيح الإجراءات الوقائية وآليات التنفيذ.', 'تتبنى الجمعية سياسات مكتوبة وشاملة لضمان سلامة الموظفين والمتطوعين أثناء تنفيذ البرامج مما يعزز بيئة عمل آمنة وفعّالة.', 'لا تعتمد الجمعية سياسات مكتوبة وشاملة لضمان سلامة الموظفين والمتطوعين مما قد يؤدي إلى زيادة المخاطر أثناء تنفيذ البرامج.'),
  (md5('cts-v0.2.1-item-131')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-23')::uuid, 131, 'تُوفر الجمعية تدريباً منتظماً للموظفين والمتطوعين حول التعامل مع المخاطر والإجراءات الوقائية.', 'تنظيم برامج تدريب منتظمة حول التعامل مع المخاطر والإجراءات الوقائية مع ضمان مشاركة جميع الموظفين والمتطوعين.', 'تلتزم الجمعية بتوفير تدريبات منتظمة للموظفين والمتطوعين حول التعامل مع المخاطر والإجراءات الوقائية مما يعزز من وعيهم واستعدادهم لمواجهة التحديات.', 'لا تقدم الجمعية تدريبات كافية للموظفين والمتطوعين حول التعامل مع المخاطر مما يضعف قدرتهم على التصرف في الحالات الطارئة.'),
  (md5('cts-v0.2.1-item-132')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-23')::uuid, 132, 'تُجري الجمعية تقييمًا دوريًا للمخاطر المحتملة أثناء تنفيذ البرامج وتقديم الخدمات.', 'إعداد جدول زمني لإجراء تقييم دوري للمخاطر المحتملة أثناء تنفيذ البرامج مع توثيق النتائج واتخاذ الإجراءات المناسبة.', 'تُجري الجمعية تقييمات دورية للمخاطر المحتملة مما يمكنها من اتخاذ التدابير الوقائية اللازمة وضمان سلامة الجميع.', 'لا تجري الجمعية تقييمًا دوريًا للمخاطر المحتملة مما يزيد من احتمالية تعرض الموظفين والمتطوعين للمخاطر أثناء تنفيذ البرامج.'),
  (md5('cts-v0.2.1-item-133')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-23')::uuid, 133, 'توفر الجمعية المعدات والأدوات الوقائية اللازمة لضمان سلامة العاملين والمتطوعين.', 'تحديد احتياجات المعدات الوقائية لكل برنامج وضمان توفيرها للعاملين والمتطوعين قبل البدء في التنفيذ.', 'تُوفر الجمعية المعدات والأدوات الوقائية اللازمة مما يضمن سلامة العاملين والمتطوعين أثناء تنفيذ البرامج.', 'لا تُوفر الجمعية الأدوات الوقائية الكافية لضمان سلامة العاملين والمتطوعين مما يعرضهم لمخاطر أثناء تقديم الخدمات.'),
  (md5('cts-v0.2.1-item-134')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-23')::uuid, 134, 'تعتمد الجمعية آليات واضحة للإبلاغ عن الحوادث والتعامل معها بشكل فوري وفعّال.', 'تصميم واعتماد آليات واضحة للإبلاغ عن الحوادث مع تدريب العاملين والمتطوعين على استخدامها لضمان سرعة الاستجابة.', 'تُعتمد الجمعية آليات واضحة ومفعّلة للإبلاغ عن الحوادث والتعامل معها بشكل فوري مما يقلل من تأثير الحوادث ويضمن الاستجابة السريعة.', 'لا توجد آليات واضحة أو فعّالة للإبلاغ عن الحوادث والتعامل معها مما قد يؤدي إلى تأخر الاستجابة وزيادة المخاطر.'),
  (md5('cts-v0.2.1-item-135')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-23')::uuid, 135, 'تراجع الجمعية سياسات وإجراءات السلامة بشكل منتظم لضمان فعاليتها وملاءمتها للتغيرات.', 'وضع جدول زمني لمراجعة دورية لسياسات وإجراءات السلامة مع تحديثها بناءً على الدروس المستفادة والتغيرات.', 'تحرص الجمعية على مراجعة سياسات وإجراءات السلامة بانتظام لضمان فعاليتها ومواكبتها للتغيرات مما يعزز من بيئة العمل الآمنة.', 'لا تقوم الجمعية بمراجعة سياسات وإجراءات السلامة بانتظام مما قد يؤدي إلى عدم توافقها مع الاحتياجات والمتغيرات الحالية.'),
  (md5('cts-v0.2.1-item-136')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-23')::uuid, 136, 'تحتفظ الجمعية بسجلات محدثة حول التدريبات والحوادث والإجراءات المُتبعة لضمان الشفافية والتحسين المستمر.', 'إنشاء نظام موثق لحفظ سجلات محدثة تشمل التدريبات الحوادث والإجراءات المتخذة مع مراجعتها دورياً لضمان دقتها وشمولها.', 'تحتفظ الجمعية بسجلات محدثة حول التدريبات الحوادث والإجراءات المُتبعة مما يدعم الشفافية ويسهل عمليات المراجعة والتحسين.', 'لا تحتفظ الجمعية بسجلات محدثة مما يعيق عمليات التقييم والتحسين المستمر لإجراءات السلامة.'),
  (md5('cts-v0.2.1-item-137')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-24')::uuid, 137, 'تحدد الجمعية بوضوح المهام والمسؤوليات المطلوبة لكل موظف ومتطوع.', 'إعداد توصيفات وظيفية دقيقة وشاملة لكل موظف ومتطوع تتضمن تحديداً واضحاً للمهام والمسؤوليات المطلوبة مع تحديثها دورياً وفقاً للاحتياجات.', 'تُحدد الجمعية بوضوح المهام والمسؤوليات المطلوبة لكل موظف ومتطوع مما يضمن توزيعاً دقيقاً للواجبات وتعزيز الكفاءة التشغيلية.', 'لا تُحدد الجمعية بشكل كافٍ المهام والمسؤوليات المطلوبة لكل موظف ومتطوع مما قد يؤدي إلى غموض في الأدوار وصعوبة في تنفيذ المهام.'),
  (md5('cts-v0.2.1-item-138')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-24')::uuid, 138, 'تحدد الجمعية مستويات الأداء المتوقعة لكل وظيفة أو دور.', 'وضع معايير محددة لمستويات الأداء المتوقعة لكل وظيفة أو دور مع مشاركتها مع الموظفين والمتطوعين لضمان الالتزام بها.', 'تُحدد الجمعية بوضوح مستويات الأداء المتوقعة لكل وظيفة أو دور مما يضمن وضوح الأهداف وتعزيز كفاءة الأداء.', 'لا تحدد الجمعية مستويات أداء واضحة لكل وظيفة أو دور مما قد يؤدي إلى غموض في التوقعات وصعوبة في تقييم الأداء.'),
  (md5('cts-v0.2.1-item-139')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-24')::uuid, 139, 'توثق الجمعية المهام والمستويات المطلوبة في توصيف وظيفي أو سجل واضح لكل موظف ومتطوع.', 'إعداد سجلات أو توصيفات وظيفية توضح المهام والمستويات المطلوبة لكل موظف ومتطوع مع تحديثها بانتظام لتلبية المتطلبات الحالية.', 'تحرص الجمعية على توثيق المهام والمستويات المطلوبة لكل موظف ومتطوع في توصيف وظيفي أو سجل واضح مما يعزز وضوح المسؤوليات والأداء.', 'لا تقوم الجمعية بتوثيق المهام والمستويات المطلوبة لكل موظف ومتطوع مما قد يؤدي إلى ضعف في توجيه الأفراد وصعوبة في متابعة الأداء.'),
  (md5('cts-v0.2.1-item-140')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-24')::uuid, 140, 'توفر الجمعية تدريباً أو جلسات توجيهية لضمان فهم الجميع لمهامهم ومستويات الأداء المطلوبة.', 'تنظيم جلسات تدريبية وتوجيهية منتظمة للموظفين والمتطوعين مع التركيز على توضيح المهام ومستويات الأداء المطلوبة لكل دور.', 'تقدم الجمعية برامج تدريبية وجلسات توجيهية لضمان فهم الموظفين والمتطوعين لمهامهم ومستويات الأداء المطلوبة مما يعزز الالتزام وتحقيق الكفاءة.', 'لا توفر الجمعية تدريباً أو جلسات توجيهية كافية مما قد يؤدي إلى سوء فهم للمهام والمسؤوليات وضعف في تحقيق مستويات الأداء المطلوبة.'),
  (md5('cts-v0.2.1-item-141')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-24')::uuid, 141, 'تحتفظ الجمعية بسجلات تثبت اطلاع الموظفين والمتطوعين على المهام والمسؤوليات الموكلة إليهم.', 'إنشاء نظام موثق لحفظ السجلات التي تثبت اطلاع الموظفين والمتطوعين على مهامهم ومسؤولياتهم مع مراجعتها بانتظام لضمان دقتها.', 'تحتفظ الجمعية بسجلات محدثة تثبت اطلاع الموظفين والمتطوعين على المهام والمسؤوليات الموكلة إليهم مما يضمن الشفافية والمساءلة.', 'لا تحتفظ الجمعية بسجلات تثبت اطلاع الموظفين والمتطوعين على المهام والمسؤوليات مما قد يؤدي إلى صعوبة في متابعة التزام الأفراد بأدوارهم.'),
  (md5('cts-v0.2.1-item-142')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-25')::uuid, 142, 'تُعتمد منهجية محددة وملائمة لتقييم أداء الموظفين والمتطوعين.', 'تصميم واعتماد منهجية محددة وملائمة لتقييم أداء الموظفين والمتطوعين مع توثيقها ومشاركتها لضمان الالتزام بها.', 'تعتمد الجمعية منهجية واضحة وملائمة لتقييم أداء الموظفين والمتطوعين مما يضمن العدالة والدقة في قياس الأداء.', 'لا تعتمد الجمعية منهجية محددة لتقييم الأداء مما قد يؤدي إلى تباين في التقييمات وصعوبة قياس التطور الوظيفي.'),
  (md5('cts-v0.2.1-item-143')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-25')::uuid, 143, 'تنفذ الجمعية تقييمات أداء منتظمة وفق جدول زمني واضح.', 'وضع جدول زمني واضح لتقييمات الأداء الدورية مع الالتزام بتنفيذه لضمان التقييم المستمر للموظفين والمتطوعين.', 'تنفذ الجمعية تقييمات أداء منتظمة بناءً على جدول زمني محدد مما يعزز استمرارية تحسين الأداء وتقييم الكفاءات.', 'لا تنفذ الجمعية تقييمات أداء بانتظام أو وفق جدول زمني واضح مما قد يؤدي إلى غياب المتابعة الدورية وتحديد نقاط التحسين.'),
  (md5('cts-v0.2.1-item-144')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-25')::uuid, 144, 'تقارن الجمعية نتائج أداء الموظفين والمتطوعين بمعايير ومؤشرات محددة مسبقًا.', 'تحديد معايير ومؤشرات أداء واضحة وقابلة للقياس مع تضمينها في منهجية التقييم واستخدامها بشكل منتظم.', 'تعتمد الجمعية معايير ومؤشرات أداء محددة مسبقاً لمقارنة النتائج مما يضمن شفافية التقييم وموضوعيته.', 'لا تعتمد الجمعية معايير واضحة لتقييم الأداء مما قد يؤدي إلى غموض في النتائج وصعوبة في تحديد مستوى الأداء.'),
  (md5('cts-v0.2.1-item-145')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-25')::uuid, 145, 'تُناقش نتائج التقييم بشكل مباشر مع الموظفين والمتطوعين لتعزيز الفهم المتبادل.', 'تنظيم جلسات فردية لمناقشة نتائج التقييم مع الموظفين والمتطوعين مع توثيق النقاشات لضمان تحقيق الأهداف.', 'تخصص الجمعية جلسات لمناقشة نتائج التقييم مع الموظفين والمتطوعين مما يعزز التواصل والفهم المتبادل لتحسين الأداء.', 'لا تُناقش الجمعية نتائج التقييم مع الموظفين والمتطوعين مما قد يؤدي إلى ضعف الفهم وعدم تحقيق الاستفادة المثلى من التقييم.'),
  (md5('cts-v0.2.1-item-146')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-25')::uuid, 146, 'تُقدم للموظفين والمتطوعين ملاحظات بناءة تستهدف تحسين الأداء وتعزيز الكفاءات.', 'إعداد نظام لتقديم ملاحظات بناءة وشخصية بعد كل تقييم أداء مع توجيه الموظفين والمتطوعين لتحسين كفاءاتهم.', 'تحرص الجمعية على تقديم ملاحظات بناءة بعد التقييم مما يساعد الموظفين والمتطوعين على تحسين أدائهم وتطوير كفاءاتهم.', 'لا تقدم الجمعية ملاحظات بناءة بعد التقييم مما قد يؤدي إلى صعوبة تحسين الأداء وضعف استجابة الأفراد للتطوير.'),
  (md5('cts-v0.2.1-item-147')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-25')::uuid, 147, 'تحتفظ الجمعية بسجلات تقييم الأداء لكل موظف ومتطوع بشكل منتظم.', 'إنشاء نظام لحفظ سجلات تقييم الأداء بشكل منتظم مع مراجعتها دورياً لضمان دقتها واكتمالها.', 'تحتفظ الجمعية بسجلات محدثة لتقييم أداء كل موظف ومتطوع مما يضمن وجود مرجع واضح لمتابعة تطور الأداء.', 'لا تحتفظ الجمعية بسجلات تقييم الأداء بشكل منتظم مما قد يؤدي إلى صعوبة متابعة التحسينات والتطوير المهني.'),
  (md5('cts-v0.2.1-item-148')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-25')::uuid, 148, 'تحتفظ الجمعية بسجلات مناقشة نتائج التقييم مع كل موظف ومتطوع.', 'إنشاء آلية لتوثيق مناقشات نتائج التقييم مع كل موظف ومتطوع مع حفظها في السجلات لاستخدامها في المتابعة المستقبلية.', 'توثق الجمعية مناقشات نتائج التقييم مع الموظفين والمتطوعين مما يضمن المتابعة الدقيقة وتحقيق الشفافية.', 'لا تُوثق الجمعية مناقشات نتائج التقييم مما قد يؤدي إلى ضعف في متابعة الأهداف المتفق عليها خلال المناقشات.'),
  (md5('cts-v0.2.1-item-149')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-25')::uuid, 149, 'تراجع الجمعية منهجية التقييم بانتظام لضمان ملاءمتها وتطويرها بما يتماشى مع احتياجات العمل.', 'إجراء مراجعات دورية لمنهجية تقييم الأداء مع تحديثها بناءً على الملاحظات والدروس المستفادة لضمان فعاليتها.', 'تُراجع الجمعية منهجية تقييم الأداء بشكل دوري مما يضمن تطويرها وملاءمتها لاحتياجات العمل الحالية والمستقبلية.', 'لا تُراجع الجمعية منهجية التقييم بانتظام مما قد يؤدي إلى اعتماد ممارسات قديمة أو غير ملائمة لبيئة العمل المتغيرة.'),
  (md5('cts-v0.2.1-item-150')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-26')::uuid, 150, 'تُحلل الجمعية نتائج تقييم الأداء لتحديد مجالات القوة والتطوير لكل موظف ومتطوع.', 'إنشاء آلية منتظمة لتحليل نتائج تقييم الأداء مع إعداد تقارير تحدد نقاط القوة وجوانب التطوير لكل موظف ومتطوع.', 'تقوم الجمعية بتحليل نتائج تقييم الأداء بانتظام لتحديد مجالات القوة والتطوير لكل موظف ومتطوع مما يعزز تحسين الأداء الفردي والجماعي.', 'لا تُحلل الجمعية نتائج تقييم الأداء بشكل كافٍ مما قد يؤدي إلى عدم تحديد نقاط القوة أو جوانب التطوير لكل موظف أو متطوع.'),
  (md5('cts-v0.2.1-item-151')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-26')::uuid, 151, 'تُوفر الجمعية توجيهًا شخصيًا بناءً على احتياجات كل موظف أو متطوع لتحسين أدائهم.', 'إعداد خطط توجيه شخصية لكل موظف ومتطوع بناءً على نتائج تقييم الأداء مع متابعة تنفيذ هذه الخطط بشكل منتظم.', 'تلتزم الجمعية بتوفير توجيه شخصي ومخصص لكل موظف أو متطوع بناءً على احتياجاتهم مما يساعدهم على تحسين أدائهم وتحقيق تطور مهني.', 'لا توفر الجمعية توجيهًا شخصيًا للموظفين أو المتطوعين مما قد يؤدي إلى عدم تلبية احتياجاتهم الفردية وضعف في تحسين الأداء.'),
  (md5('cts-v0.2.1-item-152')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-26')::uuid, 152, 'تعد الجمعية خطط دعم واضحة تشمل التدريب والتوجيه أو الإرشاد لتحسين الأداء.', 'إعداد خطط دعم متكاملة تشمل التدريب والتوجيه والإرشاد مع تحديد أهداف واضحة وآليات تنفيذ فعّالة.', 'تصمم الجمعية خطط دعم واضحة تشمل التدريب والتوجيه لتحسين أداء الموظفين والمتطوعين مما يضمن تطوراً مستمراً.', 'لا توجد خطط دعم واضحة لتحسين أداء الموظفين أو المتطوعين مما قد يؤدي إلى صعوبة تطوير الأداء بشكل منهجي.'),
  (md5('cts-v0.2.1-item-153')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-26')::uuid, 153, 'تُوفر الجمعية الأدوات والموارد والتقنيات التي تساعد الموظفين والمتطوعين على إنجاز مهامهم بكفاءة.', 'تحديد احتياجات الموظفين والمتطوعين من الأدوات والتقنيات وضمان توفيرها بشكل منتظم لدعم الكفاءة والإنتاجية.', 'تُوفر الجمعية الأدوات والتقنيات اللازمة لدعم الموظفين والمتطوعين في أداء مهامهم بكفاءة مما يساهم في تحسين الإنتاجية.', 'لا تُوفر الجمعية الأدوات أو الموارد الكافية مما قد يؤدي إلى صعوبة في إنجاز المهام بكفاءة وانخفاض مستوى الأداء.'),
  (md5('cts-v0.2.1-item-154')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-26')::uuid, 154, 'تُتابع الجمعية تنفيذ التوجيه والدعم لضمان تأثيرها الإيجابي على الأداء.', 'إعداد آلية متابعة منتظمة لخطط التوجيه والدعم مع قياس أثرها على الأداء وتقديم تقارير دورية بالنتائج.', 'تُتابع الجمعية تنفيذ خطط التوجيه والدعم بشكل منتظم مما يضمن تأثيرها الإيجابي على تحسين أداء الموظفين والمتطوعين.', 'لا تُتابع الجمعية تنفيذ التوجيه والدعم المقدم مما قد يؤدي إلى ضعف في قياس تأثير هذه الجهود على الأداء.'),
  (md5('cts-v0.2.1-item-155')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-26')::uuid, 155, 'تُوثق الجمعية أنشطة الدعم والتوجيه لضمان الاستمرارية وتطوير الإجراءات بناءً على الاحتياجات المستقبلية.', 'إنشاء نظام توثيق شامل لأنشطة الدعم والتوجيه مع مراجعة دورية لهذه السجلات لتطوير الإجراءات وفقاً للاحتياجات المستقبلية.', 'توثق الجمعية جميع أنشطة الدعم والتوجيه لضمان استمرارية الجهود وتحسينها بناءً على الاحتياجات المستقبلية.', 'لا تُوثق الجمعية أنشطة الدعم والتوجيه بشكل كافٍ مما قد يؤدي إلى ضعف في استمرارية الجهود وصعوبة تطوير الإجراءات.'),
  (md5('cts-v0.2.1-item-156')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-27')::uuid, 156, 'تُعد الجمعية تقارير تحليلية شاملة عن أداء الموظفين والمتطوعين بناءً على تقييماتهم.', 'إعداد تقارير تحليلية شاملة ومنتظمة تستند إلى تقييمات أداء الموظفين والمتطوعين مع تضمين توصيات لتحسين الأداء وتطوير المهارات.', 'تُعد الجمعية تقارير تحليلية شاملة تستند إلى تقييمات أداء الموظفين والمتطوعين مما يُساعد في تحديد نقاط القوة وفرص التحسين وتعزيز الكفاءة التشغيلية.', 'لا تُعد الجمعية تقارير تحليلية شاملة عن أداء الموظفين والمتطوعين مما قد يؤثر على  بناء خطط تحسين أدائهم أو معالجة التحديات.'),
  (md5('cts-v0.2.1-item-157')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-27')::uuid, 157, 'تتضمن التقارير تحليلًا لنقاط القوة والضعف في أداء الموظفين والمتطوعين.', 'إضافة قسم مخصص في التقارير لتحليل نقاط القوة والضعف في أداء الموظفين والمتطوعين مع تحديث هذا التحليل بانتظام لضمان دقته وشموله.', 'تحرص الجمعية على تضمين تحليل شامل لنقاط القوة والضعف في أداء الموظفين والمتطوعين ضمن التقارير مما يعزز فهم الأداء ويسهم في تحسينه.', 'لا تتضمن التقارير تحليلًا لنقاط القوة والضعف في أداء الموظفين والمتطوعين مما قد يؤدي إلى صعوبة في تحديد مجالات التطوير والاحتياجات.'),
  (md5('cts-v0.2.1-item-158')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-27')::uuid, 158, 'تُظهر التقارير مدى ارتباط الأداء بتحقيق أهداف المنظمة.', 'إدراج مؤشرات أداء رئيسية في التقارير تربط بين أداء الموظفين والمتطوعين وتحقيق أهداف الجمعية.', 'تعكس التقارير بوضوح مدى ارتباط أداء الموظفين والمتطوعين بتحقيق أهداف الجمعية مما يدعم قياس فعالية الجهود التنظيمية.', 'لا توضح التقارير مدى ارتباط الأداء بأهداف الجمعية مما قد يؤدي إلى صعوبة تقييم تأثير الأداء على تحقيق الأهداف.'),
  (md5('cts-v0.2.1-item-159')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-27')::uuid, 159, 'تُشارك المنظمة التقارير مع أصحاب المصلحة الرئيسيين لضمان الشفافية وتعزيز الثقة.', 'تطوير آلية فعّالة لمشاركة التقارير المتعلقة بأداء الموظفين والمتطوعين مع أصحاب المصلحة الرئيسيين بانتظام.', 'تُشارك الجمعية التقارير المتعلقة بأداء الموظفين والمتطوعين مع أصحاب المصلحة الرئيسيين مما يعزز الشفافية ويزيد الثقة في العمليات.', 'لا تُشارك الجمعية التقارير مع أصحاب المصلحة الرئيسيين مما قد يؤدي إلى ضعف الشفافية والثقة بين الأطراف ذات العلاقة.'),
  (md5('cts-v0.2.1-item-160')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-27')::uuid, 160, 'تحدد الجمعية الدروس المستفادة من أداء الموظفين والمتطوعين لتحسين العمليات والإجراءات.', 'إنشاء عملية منهجية لتحديد الدروس المستفادة من أداء الموظفين والمتطوعين وتوثيقها لتطوير العمليات والإجراءات.', 'تحرص الجمعية على تحديد الدروس المستفادة من أداء الموظفين والمتطوعين مما يدعم تحسين العمليات والإجراءات بشكل مستمر.', 'لا تُحدد الجمعية الدروس المستفادة من أداء الموظفين والمتطوعين مما قد يؤدي إلى تكرار الأخطاء وفقدان فرص التحسين.'),
  (md5('cts-v0.2.1-item-161')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-27')::uuid, 161, 'تُستخدم نتائج التحليل والدروس المستفادة لتطوير خطط لتحسين الأداء على المستوى الفردي والتنظيمي.', 'تطبيق نظام يعتمد على نتائج التحليل والدروس المستفادة لتطوير خطط تحسين الأداء الفردي والتنظيمي مع متابعة التنفيذ بانتظام.', 'تُوظف الجمعية نتائج التحليل والدروس المستفادة لتطوير خطط تحسين الأداء على المستويين الفردي والتنظيمي مما يضمن تحقيق التطور المستدام.', 'لا تُستخدم نتائج التحليل والدروس المستفادة لتطوير خطط تحسين الأداء مما قد يؤدي إلى غياب استراتيجيات التطوير الفعّالة.'),
  (md5('cts-v0.2.1-item-162')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-27')::uuid, 162, 'التقارير والدروس المستفادة موثقة بشكل منتظم و لأصحاب المصلحة الوصول إليها بسهوله .', 'تطوير نظام توثيق منتظم للتقارير والدروس المستفادة مع ضمان توفيرها إلكترونياً أو ورقياً لأصحاب المصلحة بسهولة.', 'توثق الجمعية التقارير والدروس المستفادة بشكل منتظم وتتيح الوصول إليها بسهولة لأصحاب المصلحة مما يعزز من الشفافية وسهولة الاستخدام.', 'لا تُوثق الجمعية التقارير والدروس المستفادة بشكل منتظم أو لا تسهّل الوصول إليها مما يعيق الاستفادة منها في تحسين الأداء.'),
  (md5('cts-v0.2.1-item-163')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-28')::uuid, 163, 'حددت الجمعية نوعية الشراكات الفنية اللازمة لتعزيز جودة الخدمات المقدمة.', 'إجراء تحليل شامل لتحديد نوعية الشراكات الفنية اللازمة لدعم وتحسين جودة الخدمات مع تحديث القائمة بانتظام.', 'تُحدد الجمعية نوعية الشراكات الفنية اللازمة لتعزيز جودة الخدمات المقدمة مما يضمن الاستفادة المثلى من الموارد والشراكات الفعّالة.', 'لم تقم الجمعية بتحديد نوعية الشراكات الفنية اللازمة مما قد يؤدي إلى فقدان فرص تحسين جودة الخدمات المقدمة.'),
  (md5('cts-v0.2.1-item-164')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-28')::uuid, 164, 'تحديد نوعية الشراكات الفنية كان استناداً إلى تحليل البرامج والخدمات ومتطلبات تنفيذها.', 'تنفيذ تحليل متكامل للبرامج والخدمات ومتطلباتها قبل تحديد نوعية الشراكات الفنية مع مراجعة النتائج لضمان توافقها مع الأهداف.', 'يتم تحديد نوعية الشراكات الفنية في الجمعية بناءً على تحليل دقيق للبرامج والخدمات ومتطلبات تنفيذها مما يضمن توافق الشراكات مع احتياجات العمل.', 'لا يتم تحديد نوعية الشراكات الفنية بناءً على تحليل البرامج والخدمات مما قد يؤدي إلى تكوين شراكات قد لا تلبي الاحتياجات الفعلية.'),
  (md5('cts-v0.2.1-item-165')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-28')::uuid, 165, 'لدى الجمعية وثيقة أو سجل تتضمن تحديد الشركاء المحتملين وهذا الوثيقة محدثة.', 'إعداد وثيقة أو سجل يتضمن تحديد الشركاء المحتملين مع تحديثه دورياً لتلبية الاحتياجات المتغيرة للجمعية.', 'تحتفظ الجمعية بوثيقة محدثة أو سجل يحدد الشركاء المحتملين مما يسهل إدارة الشراكات واستكشاف فرص التعاون.', 'لا توجد وثيقة محدثة تحدد الشركاء المحتملين مما قد يؤدي إلى صعوبة في بناء شراكات فعّالة وتنسيق الجهود.'),
  (md5('cts-v0.2.1-item-166')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-28')::uuid, 166, 'يظهر في الوثيقة تاريخ آخر تحديث.', 'إضافة تاريخ آخر تحديث إلى وثيقة تحديد الشركاء المحتملين مع تحديثها بانتظام لضمان دقة وموثوقية المعلومات.', 'تتضمن وثيقة تحديد الشركاء المحتملين تاريخ آخر تحديث مما يضمن وضوح المراجعات ودقتها.', 'لا تحتوي وثيقة تحديد الشراكات على تاريخ آخر تحديث مما يجعل من الصعب معرفة مدى حداثة المعلومات وصحتها.'),
  (md5('cts-v0.2.1-item-167')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-29')::uuid, 167, 'لدى الجمعية بيانات تفصيلية عن الشركاء المحتملين بما في ذلك خبراتهم وسجلهم في المجال.', 'إعداد قاعدة بيانات شاملة للشركاء المحتملين تتضمن تفاصيل خبراتهم وسجلهم في المجال مع تحديثها بانتظام.', 'تحتفظ الجمعية ببيانات تفصيلية عن الشركاء المحتملين تشمل خبراتهم وسجلهم في المجال مما يعزز من اتخاذ قرارات مدروسة بشأن الشراكات.', 'لا تمتلك الجمعية بيانات تفصيلية عن الشركاء المحتملين مما قد يؤدي إلى صعوبة تقييم مدى ملاءمتهم لدعم البرامج والخدمات.'),
  (md5('cts-v0.2.1-item-168')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-29')::uuid, 168, 'تُحلل الجمعية رؤية وأهداف الشركاء المحتملين للتأكد من توافقها مع رؤيتها وأهدافها.', 'إجراء تحليل دقيق لرؤية وأهداف الشركاء المحتملين قبل إبرام أي شراكة مع توثيق نتائج التحليل لضمان التوافق.', 'تحلل الجمعية رؤية وأهداف الشركاء المحتملين لضمان توافقها مع رؤيتها وأهدافها مما يعزز فعالية التعاون وتحقيق الأهداف المشتركة.', 'لا تُجري الجمعية تحليلاً لرؤية وأهداف الشركاء المحتملين مما قد يؤدي إلى شراكات غير متوافقة مع توجهات الجمعية.'),
  (md5('cts-v0.2.1-item-169')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-29')::uuid, 169, 'تُقيّم الجمعية الموارد والخبرات التي يمتلكها الشركاء المحتملون لدعم برامجها وخدماتها.', 'تصميم عملية تقييم شاملة للموارد والخبرات التي يمتلكها الشركاء المحتملون مع تضمين النتائج في قرارات الشراكة.', 'تُقيّم الجمعية الموارد والخبرات التي يمتلكها الشركاء المحتملون مما يساعد في اختيار شركاء يمكنهم دعم البرامج والخدمات بفعالية.', 'لا تُقيّم الجمعية الموارد والخبرات التي يمتلكها الشركاء المحتملون مما قد يؤدي إلى اختيار شركاء قد لا يساهمون بشكل فعال في دعم البرامج.'),
  (md5('cts-v0.2.1-item-170')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-29')::uuid, 170, 'تعتمد المنظمة معايير محددة وواضحة لتقييم مدى ملاءمة الشركاء المحتملين.', 'تطوير مجموعة من المعايير الواضحة لتقييم ملاءمة الشركاء المحتملين مع تدريب الفريق على تطبيقها.', 'تُحدد الجمعية معايير واضحة لتقييم ملاءمة الشركاء المحتملين مما يضمن اختيار شركاء ذوي قيمة مضافة للبرامج والخدمات.', 'لا تعتمد الجمعية معايير واضحة لتقييم الشركاء المحتملين مما قد يؤدي إلى اختيار غير مدروس للشراكات.'),
  (md5('cts-v0.2.1-item-171')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-29')::uuid, 171, 'تُوثق الجمعية نتائج تحليل الشركاء المحتملين لضمان الشفافية وسهولة الرجوع إليها.', 'إنشاء نظام توثيق شامل لتحليل الشركاء المحتملين مع ضمان تحديثه بانتظام وإتاحته للأطراف ذات العلاقة.', 'تُوثق الجمعية نتائج تحليل الشركاء المحتملين بشكل دقيق مما يضمن الشفافية وسهولة الرجوع إلى المعلومات لاتخاذ قرارات مستقبلية.', 'لا تُوثق الجمعية نتائج تحليل الشركاء المحتملين مما قد يؤدي إلى ضعف الشفافية وصعوبة تتبع قرارات الشراكة.'),
  (md5('cts-v0.2.1-item-172')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-30')::uuid, 172, 'يوجد خطة مكتوبة ومفصلة للتواصل مع الشركاء المحتملين.', 'إعداد خطة مكتوبة ومفصلة للتواصل مع الشركاء المحتملين تتضمن الأهداف والوسائل وآليات المتابعة.', 'تمتلك الجمعية خطة مكتوبة ومفصلة للتواصل مع الشركاء المحتملين مما يضمن تنظيم الجهود وتحقيق تواصل فعّال يدعم بناء الشراكات.', 'لا توجد خطة مكتوبة أو مفصلة للتواصل مع الشركاء المحتملين مما قد يؤدي إلى ضعف التنظيم وصعوبة تحقيق تواصل فعّال.'),
  (md5('cts-v0.2.1-item-173')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-30')::uuid, 173, 'تُحدد الأهداف المرجوة من بناء الشراكات بوضوح وربطها باحتياجات البرامج والخدمات.', 'تحديد الأهداف المرجوة من الشراكات وربطها بشكل مباشر باحتياجات البرامج والخدمات لضمان توافق الشراكات مع الأولويات.', 'تُحدد الجمعية الأهداف المرجوة من بناء الشراكات بوضوح مع ربطها باحتياجات البرامج والخدمات مما يضمن توافق الشراكات مع أولويات الجمعية.', 'لا تُحدد الجمعية الأهداف المرجوة من الشراكات بشكل واضح أو لا تربطها باحتياجات البرامج مما قد يؤدي إلى بناء شراكات غير فعّالة.'),
  (md5('cts-v0.2.1-item-174')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-30')::uuid, 174, 'تحدد الجمعية الوسائل الأكثر فعالية للتواصل مثل الاجتماعات ورسائل البريد الإلكتروني والاتصال الهاتفي.', 'اختيار الوسائل الأنسب للتواصل مع الشركاء المحتملين بناءً على احتياجات ومتطلبات كل شراكة مع توثيق ذلك في خطة التواصل.', 'تحرص الجمعية على تحديد الوسائل الأكثر فعالية للتواصل مع الشركاء المحتملين مما يضمن سهولة الوصول وتحقيق تواصل مثمر.', 'لا تُحدد الجمعية الوسائل الأكثر فعالية للتواصل مما قد يؤدي إلى ضعف في التواصل وعدم تحقيق نتائج إيجابية.'),
  (md5('cts-v0.2.1-item-175')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-30')::uuid, 175, 'تحدد الجمعية جدولًا زمنيًا لتطبيق خطة التواصل ومتابعة التنفيذ.', 'إعداد جدول زمني محدد لتطبيق خطة التواصل مع تحديد نقاط متابعة دورية لضمان تحقيق الأهداف ضمن الإطار الزمني.', 'تُحدد الجمعية جدولًا زمنيًا واضحًا لتطبيق خطة التواصل ومتابعة التنفيذ مما يضمن الالتزام بالجدول وتحقيق الأهداف في الوقت المناسب.', 'لا تضع الجمعية جدولًا زمنيًا لتطبيق خطة التواصل مما قد يؤدي إلى تأخر في التنفيذ وصعوبة متابعة التقدم.'),
  (md5('cts-v0.2.1-item-176')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-30')::uuid, 176, 'تُقيم الجمعية فعالية وسائل وأهداف التواصل لضمان تحقيق نتائج إيجابية.', 'تنفيذ آلية لتقييم فعالية وسائل وأهداف التواصل بشكل دوري مع تعديل الوسائل عند الحاجة لتحقيق نتائج أفضل.', 'تُجري الجمعية تقييمًا دوريًا لفعالية وسائل وأهداف التواصل مما يساعد في تحسين الأداء وضمان تحقيق نتائج إيجابية.', 'لا تُقيم الجمعية فعالية وسائل وأهداف التواصل مما قد يؤدي إلى استمرار استخدام وسائل غير فعّالة وضعف تحقيق النتائج المرجوة.'),
  (md5('cts-v0.2.1-item-177')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-30')::uuid, 177, 'تُوثق الجمعية جميع خطوات التواصل ونتائجها لضمان الشفافية وتحسين الممارسات المستقبلية.', 'إنشاء نظام توثيق شامل لجميع خطوات التواصل مع الشركاء المحتملين مع حفظ النتائج وتحديثها بانتظام لضمان التحسين المستمر.', 'توثق الجمعية جميع خطوات التواصل ونتائجها مما يضمن الشفافية وسهولة الرجوع إلى البيانات لتحسين الممارسات المستقبلية.', 'لا تُوثق الجمعية خطوات التواصل ونتائجها مما قد يؤدي إلى غياب الشفافية وصعوبة تحسين الممارسات المستقبلية.'),
  (md5('cts-v0.2.1-item-178')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-31')::uuid, 178, 'تعتمد المنظمة إطارًا مكتوبًا وواضحًا يحدد قواعد وآليات الإنهاء منذ بداية الشراكة.', 'إعداد إطار مكتوب وواضح يحدد قواعد وآليات إنهاء الشراكة مع تضمين البنود الأساسية لضمان شفافية العملية.', 'تعتمد الجمعية إطارًا مكتوبًا وواضحًا يحدد قواعد وآليات إنهاء الشراكة منذ بدايتها مما يضمن الشفافية والتنظيم في إدارة الشراكات.', 'لا تعتمد الجمعية إطارًا مكتوبًا وواضحًا يحدد قواعد وآليات إنهاء الشراكة مما قد يؤدي إلى غموض وإشكاليات عند إنهاء الشراكة.'),
  (md5('cts-v0.2.1-item-179')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-31')::uuid, 179, 'تُحدد الجمعية معايير موضوعية لإنهاء الشراكة مثل انتهاء المشروع وعدم توافق الأهداف أو عدم الالتزام بالشروط.', 'تطوير قائمة معايير موضوعية ومحددة لإنهاء الشراكة تشمل حالات مثل انتهاء المشروع عدم توافق الأهداف أو الإخلال بالالتزامات.', 'تُحدد الجمعية معايير موضوعية وواضحة لإنهاء الشراكة مما يضمن اتخاذ قرارات مبنية على أسس عادلة وشفافة.', 'لا تُحدد الجمعية معايير واضحة لإنهاء الشراكة مما قد يؤدي إلى قرارات غير مدروسة وصعوبة في إدارة إنهاء الشراكات.'),
  (md5('cts-v0.2.1-item-180')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-31')::uuid, 180, 'تُوضح الجمعية آليات إنهاء الشراكة مثل الإشعارات المسبقة والاجتماعات الختامية وتسليم الالتزامات.', 'تضمين آليات محددة لإنهاء الشراكة في الإطار المكتوب مثل الإشعارات المسبقة والاجتماعات الختامية مع توضيح مسؤوليات كل طرف.', 'تُوضح الجمعية آليات واضحة لإنهاء الشراكة مثل الإشعارات المسبقة والاجتماعات الختامية مما يضمن تنفيذ العملية بسلاسة ودون خلافات.', 'لا تُحدد الجمعية آليات واضحة لإنهاء الشراكة مما قد يؤدي إلى سوء فهم بين الأطراف وصعوبة في إتمام العملية بشكل منظم.'),
  (md5('cts-v0.2.1-item-181')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-31')::uuid, 181, 'تُراجع الجمعية الإطار بعد كل عملية إنهاء شراكة لاستخلاص الدروس وتحسين الممارسات.', 'إنشاء آلية لمراجعة الإطار بعد كل عملية إنهاء شراكة مع توثيق الدروس المستفادة وتطبيقها لتحسين العمليات المستقبلية.', 'تُراجع الجمعية الإطار بعد كل عملية إنهاء شراكة لاستخلاص الدروس المستفادة وتحسين الممارسات المستقبلية مما يعزز من كفاءة العملية.', 'لا تُراجع الجمعية الإطار بعد إنهاء الشراكات مما قد يؤدي إلى تكرار الأخطاء وعدم الاستفادة من التجارب السابقة.'),
  (md5('cts-v0.2.1-item-182')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-31')::uuid, 182, 'تُتيح الجمعية في إطارها إمكانية إعادة التعاون مع الشركاء في المستقبل بناءً على التقييم المشترك.', 'إدراج بند في الإطار يوضح شروط وإمكانيات إعادة التعاون مع الشركاء مع تحديد آلية للتقييم المشترك قبل استئناف الشراكة.', 'يُتيح إطار الجمعية إمكانية إعادة التعاون مع الشركاء بناءً على التقييم المشترك مما يعزز من بناء علاقات طويلة الأمد وقائمة على الثقة.', 'لا يُتيح إطار الجمعية إمكانية إعادة التعاون مع الشركاء مما قد يؤدي إلى فقدان فرص الشراكات المستقبلية التي قد تكون مفيدة.'),
  (md5('cts-v0.2.1-item-183')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-31')::uuid, 183, 'يظهر في وثيقة الإطار تاريخ وجهة الاعتماد وتاريخ آخر تحديث.', 'إضافة تاريخ وجهة الاعتماد وتاريخ آخر تحديث إلى وثيقة الإطار مع تحديثها بانتظام لضمان دقتها ومرجعيتها.', 'تتضمن وثيقة الإطار تاريخ وجهة الاعتماد وتاريخ آخر تحديث مما يعزز من موثوقية الوثيقة ويضمن استخدامها كمرجع رسمي.', 'لا يظهر في وثيقة الإطار تاريخ الاعتماد أو آخر تحديث مما قد يؤدي إلى ضعف الثقة في الوثيقة وصعوبة تتبع التعديلات.'),
  (md5('cts-v0.2.1-item-184')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-32')::uuid, 184, 'تُراجع الجمعية التزام الشركاء المحتملين بالأنظمة والمعايير.', 'إنشاء آلية منتظمة لمراجعة التزام الشركاء المحتملين بالأنظمة والمعايير مع توثيق نتائج المراجعة لاتخاذ قرارات دقيقة.', 'تلتزم الجمعية بمراجعة مدى التزام الشركاء المحتملين بالأنظمة والمعايير مما يضمن شراكات قانونية ومستدامة.', 'لا تُجري الجمعية مراجعة كافية لالتزام الشركاء المحتملين بالأنظمة والمعايير مما قد يؤدي إلى مخاطر قانونية وإدارية.'),
  (md5('cts-v0.2.1-item-185')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-32')::uuid, 185, 'تُراجع الجمعية بنود الاتفاقية المقترحة لضمان توافقها مع المتطلبات النظامية.', 'إجراء مراجعة دقيقة وشاملة لبنود الاتفاقيات المقترحة للتأكد من توافقها مع المتطلبات النظامية قبل توقيعها.', 'تحرص الجمعية على مراجعة بنود الاتفاقيات المقترحة للتأكد من توافقها مع المتطلبات النظامية مما يعزز الامتثال القانوني للشراكات.', 'لا تُراجع الجمعية بنود الاتفاقيات المقترحة بشكل دقيق لضمان توافقها مع الأنظمة مما قد يؤدي إلى احتمال وقوع مخالفات.'),
  (md5('cts-v0.2.1-item-186')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-32')::uuid, 186, 'تُعرض الاتفاقيات على مستشار قانوني أو مختص للتأكد من توافقها مع الأنظمة ذات الصلة.', 'التأكد من عرض جميع الاتفاقيات على مستشار قانوني أو مختص قبل توقيعها لضمان توافقها مع الأنظمة والقوانين المعمول بها.', 'تعرض الجمعية الاتفاقيات على مستشار قانوني أو مختص لضمان توافقها مع الأنظمة ذات الصلة مما يقلل المخاطر القانونية.', 'لا تُعرض الجمعية الاتفاقيات على مستشار قانوني أو مختص مما يزيد من احتمالية وجود بنود غير متوافقة مع الأنظمة.'),
  (md5('cts-v0.2.1-item-187')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-32')::uuid, 187, 'تُوثق الجمعية جميع الخطوات والإجراءات التي تمت لمراجعة الاتفاقية والتأكد من الالتزام.', 'إنشاء نظام توثيق شامل لجميع خطوات وإجراءات مراجعة الاتفاقيات مع الاحتفاظ بالسجلات لضمان الشفافية وتحسين العمليات المستقبلية.', 'توثق الجمعية جميع الخطوات والإجراءات المتعلقة بمراجعة الاتفاقيات والتأكد من الالتزام مما يضمن الشفافية وسهولة الرجوع إليها عند الحاجة.', 'لا تُوثق الجمعية خطوات مراجعة الاتفاقيات مما قد يؤدي إلى ضعف الشفافية وصعوبة تتبع الإجراءات والمراجعات السابقة.'),
  (md5('cts-v0.2.1-item-188')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-33')::uuid, 188, 'تتأكد الجمعية أن الاتفاقية توضح بشكل مفصل أدوار ومسؤوليات كل طرف.', 'إعداد اتفاقيات شراكة تتضمن تفصيلًا دقيقًا لأدوار ومسؤوليات جميع الأطراف لضمان وضوح المهام والالتزامات.', 'تُوضح الجمعية أدوار ومسؤوليات كل طرف بشكل مفصل في اتفاقيات الشراكة مما يضمن التنظيم والشفافية في تنفيذ الشراكة.', 'لا تحتوي اتفاقيات الشراكة على توضيح مفصل لأدوار ومسؤوليات كل طرف مما قد يؤدي إلى سوء فهم وصعوبات في التنفيذ.'),
  (md5('cts-v0.2.1-item-189')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-33')::uuid, 189, 'تُراجع الأدوار والمسؤوليات مع جميع الأطراف المعنية لضمان التفاهم الكامل.', 'تنظيم جلسات مراجعة مع جميع الأطراف المعنية لمناقشة الأدوار والمسؤوليات وتوثيق أي استفسارات لضمان التفاهم الكامل.', 'تُراجع الجمعية الأدوار والمسؤوليات مع جميع الأطراف المعنية لضمان التفاهم الكامل والالتزام بما تم الاتفاق عليه.', 'لا تُراجع الجمعية الأدوار والمسؤوليات مع الأطراف المعنية مما قد يؤدي إلى احتمال سوء فهم أو عدم التزام ببنود الاتفاقية.'),
  (md5('cts-v0.2.1-item-190')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-33')::uuid, 190, 'تُكتب الأدوار والمسؤوليات بلغة واضحة وغير قابلة للتأويل لتجنب النزاعات.', 'مراجعة الأدوار والمسؤوليات للتأكد من وضوح صياغتها مع الاستعانة بخبراء قانونيين لتحسين اللغة المستخدمة.', 'تستخدم الجمعية لغة واضحة وغير قابلة للتأويل في كتابة الأدوار والمسؤوليات مما يقلل من فرص النزاعات ويعزز الالتزام.', 'تُكتب الأدوار والمسؤوليات بلغة غامضة أو قابلة للتأويل مما يزيد من احتمالية حدوث نزاعات بين الأطراف.'),
  (md5('cts-v0.2.1-item-191')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-33')::uuid, 191, 'تُحدد الاتفاقية آليات متابعة أداء كل طرف في تنفيذ مسؤولياته.', 'إضافة آليات متابعة أداء الأطراف إلى الاتفاقية مثل تقارير دورية واجتماعات مراجعة لضمان الالتزام وتحقيق الشفافية.', 'تتضمن الاتفاقية آليات واضحة لمتابعة أداء الأطراف في تنفيذ مسؤولياتهم مما يضمن مراقبة التنفيذ وتحقيق الأهداف.', 'لا تُحدد الاتفاقية آليات متابعة أداء الأطراف مما قد يؤدي إلى ضعف في الرقابة وصعوبة تقييم الالتزام بالاتفاقية.'),
  (md5('cts-v0.2.1-item-192')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-33')::uuid, 192, 'تُحدد اتفاقيات الشراكة إجراءات واضحة لتعديل الأدوار والمسؤوليات إذا لزم الأمر.', 'إضافة بند في اتفاقية الشراكات يحدد إجراءات تعديل الأدوار والمسؤوليات مع توضيح آلية الموافقة من جميع الأطراف.', 'تُوضح الجمعية إجراءات تعديل الأدوار والمسؤوليات في اتفاقيات الشراكة مما يضمن المرونة في التعامل مع التغيرات.', 'لا تحتوي اتفاقيات الشراكة على إجراءات لتعديل الأدوار والمسؤوليات مما قد يؤدي إلى صعوبات في التعامل مع التغيرات أو الطوارئ.'),
  (md5('cts-v0.2.1-item-193')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-33')::uuid, 193, 'تُوثق الجمعية النسخة الموقعة من اتفاقيات الشراكة لضمان التزام جميع الأطراف.', 'إنشاء نظام توثيق مركزي للنسخ الموقعة من الاتفاقيات مع ضمان سهولة الوصول إليها عند الحاجة.', 'تحتفظ الجمعية بالنسخة الموقعة من الاتفاقيات مما يضمن التزام جميع الأطراف ويُعد مرجعًا رسميًا عند الحاجة.', 'لا تُوثق الجمعية النسخة الموقعة من اتفاقيات الشراكة مما قد يؤدي إلى ضعف الالتزام وصعوبة الرجوع إليها في حال النزاعات.'),
  (md5('cts-v0.2.1-item-194')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-34')::uuid, 194, 'تُعد الجمعية إجراءات مكتوبة وواضحة للتواصل مع الشركاء تحدد القنوات والآليات.', 'إعداد إجراءات مكتوبة ومفصلة توضح قنوات وآليات التواصل مع الشركاء مع مراجعتها وتحديثها دوريًا لضمان فاعليتها.', 'تُعد الجمعية إجراءات مكتوبة وواضحة تحدد قنوات وآليات التواصل مع الشركاء مما يضمن التنظيم والوضوح في التفاعل مع الشركاء.', 'لا توجد إجراءات مكتوبة وواضحة للتواصل مع الشركاء مما قد يؤدي إلى ارتباك في التعامل وصعوبة في تنفيذ الشراكة بفعالية.'),
  (md5('cts-v0.2.1-item-195')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-34')::uuid, 195, 'تُقدم المنظمة شرحًا وافياً لإجراءات التواصل لضمان فهم الشركاء لها.', 'توفير شرح تفصيلي لإجراءات التواصل أثناء توقيع الشراكات مع إتاحة دليل مكتوب للشركاء يشرح الآليات بشكل واضح.', 'تحرص الجمعية على تقديم شرح وافٍ لإجراءات التواصل مما يضمن فهم الشركاء لآليات العمل ويسهم في تعزيز الشفافية.', 'لا تُقدم الجمعية شرحًا كافيًا لإجراءات التواصل مما قد يؤدي إلى سوء فهم من قبل الشركاء وصعوبة في تطبيق الإجراءات.'),
  (md5('cts-v0.2.1-item-196')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-34')::uuid, 196, 'تُنشئ الجمعية آلية لجمع آراء الشركاء حول سير العمل والإجراءات المتبعة.', 'تصميم آلية فعّالة لجمع آراء الشركاء مثل استبيانات أو اجتماعات دورية لضمان الحصول على ملاحظاتهم وتحسين الإجراءات بناءً على ذلك.', 'تُنشئ الجمعية آلية مخصصة لجمع آراء الشركاء حول سير العمل والإجراءات المتبعة مما يعزز التحسين المستمر والشفافية.', 'لا توجد آلية لجمع آراء الشركاء حول سير العمل مما قد يؤدي إلى ضعف في الاستجابة لاحتياجات الشركاء أو تحسين العمليات.'),
  (md5('cts-v0.2.1-item-197')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-34')::uuid, 197, 'تخصص الجمعية آلية واضحة لمعالجة المشاكل التي يثيرها الشركاء.', 'إنشاء آلية موثقة ومحددة لمعالجة مشاكل الشركاء بسرعة وكفاءة مع تعيين مسؤولين واضحين لتلقي المشكلات ومتابعة حلها.', 'تُخصص الجمعية آلية واضحة لمعالجة المشاكل التي يثيرها الشركاء مما يضمن الاستجابة السريعة والحفاظ على الثقة المتبادلة.', 'لا تُوفر الجمعية آلية واضحة لمعالجة مشكلات الشركاء مما قد يؤدي إلى تأخر في الحلول وزيادة التوتر بين الأطراف.'),
  (md5('cts-v0.2.1-item-198')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-34')::uuid, 198, 'تُقيم المنظمة بشكل دوري فعالية إجراءات التواصل ومدى رضا الشركاء عنها.', 'وضع خطة دورية لتقييم إجراءات التواصل ومدى رضا الشركاء مع استخدام نتائج التقييم لتطوير وتحسين العمليات.', 'تُجري الجمعية تقييمًا دوريًا لفعالية إجراءات التواصل ومدى رضا الشركاء مما يساهم في تحسين آليات العمل وبناء شراكات أقوى.', 'لا تُقيم الجمعية فعالية إجراءات التواصل بشكل دوري مما قد يؤدي إلى استمرار استخدام آليات قد تكون غير فعالة أو تسبب عدم رضا الشركاء.'),
  (md5('cts-v0.2.1-item-199')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-34')::uuid, 199, 'تُوثق المنظمة جميع عمليات التواصل وآراء الشركاء لضمان الشفافية والاستفادة المستقبلية.', 'إنشاء نظام موحد لتوثيق جميع عمليات التواصل وآراء الشركاء مع ضمان سهولة الوصول إلى السجلات لاستخدامها في التطوير المستقبلي.', 'توثق الجمعية جميع عمليات التواصل وآراء الشركاء بشكل منتظم مما يعزز الشفافية ويساعد في تحسين الشراكات المستقبلية.', 'لا تُوثق الجمعية عمليات التواصل وآراء الشركاء مما قد يؤدي إلى صعوبة في تتبع المعلومات والاستفادة منها في تحسين العمليات.'),
  (md5('cts-v0.2.1-item-200')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-35')::uuid, 200, 'تُحدد المنظمة الخدمات التي يُقدمها الشركاء وتُصنفها على أنها مكملة لخدماتها.', 'إجراء تحليل شامل للخدمات التي يقدمها الشركاء وتصنيفها على أنها مكملة لخدمات الجمعية مع تحديث التصنيف بشكل دوري.', 'تحرص الجمعية على تحديد وتصنيف الخدمات التي يقدمها الشركاء على أنها مكملة لخدماتها مما يعزز التكامل بين الشراكات لتحقيق أهداف مشتركة.', 'لا تقوم الجمعية بتحديد وتصنيف الخدمات التي يقدمها الشركاء مما قد يؤدي إلى تداخل الأدوار أو عدم توافق الخدمات مع احتياجات المستفيدين.'),
  (md5('cts-v0.2.1-item-201')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-35')::uuid, 201, 'يوجد لدى الجمعية إجراءات مكتوبة تُحدد كيفية إحالة المستفيدين إلى الشركاء.', 'إعداد وثيقة تفصيلية تتضمن إجراءات مكتوبة تُحدد كيفية إحالة المستفيدين إلى الشركاء مع توفير تدريب للموظفين على تنفيذها.', 'تمتلك الجمعية إجراءات مكتوبة وواضحة تُحدد كيفية إحالة المستفيدين إلى الشركاء مما يضمن تنظيم العملية وسهولة التنفيذ.', 'لا توجد إجراءات مكتوبة توضح كيفية إحالة المستفيدين إلى الشركاء مما قد يؤدي إلى عدم اتساق العملية وصعوبة متابعة الإحالات.'),
  (md5('cts-v0.2.1-item-202')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-35')::uuid, 202, 'تُوثق الجمعية كل عملية إحالة بسجلات تحتوي على تفاصيل المستفيد والخدمة المقدمة.', 'إنشاء نظام موحد لتوثيق جميع عمليات الإحالة مع تضمين تفاصيل المستفيد والخدمة المقدمة في السجلات لضمان الشفافية.', 'توثق الجمعية كل عملية إحالة بسجلات دقيقة تحتوي على تفاصيل المستفيد والخدمة المقدمة مما يضمن الشفافية وسهولة الرجوع إلى المعلومات.', 'لا تُوثق الجمعية عمليات الإحالة بشكل منهجي مما قد يؤدي إلى فقدان المعلومات وصعوبة تتبع الخدمات المقدمة للمستفيدين.'),
  (md5('cts-v0.2.1-item-203')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-35')::uuid, 203, 'تُتابع الجمعية نتائج الإحالة مع الشريك لضمان تقديم الخدمة المطلوبة للمستفيد.', 'وضع آلية واضحة لمتابعة نتائج الإحالة مع الشركاء تشمل تقارير متابعة واجتماعات دورية لضمان تقديم الخدمة المطلوبة.', 'تتابع الجمعية نتائج الإحالة مع الشركاء للتأكد من تقديم الخدمة المطلوبة للمستفيدين مما يعزز جودة الخدمة وتحقيق رضا المستفيدين.', 'لا تتابع الجمعية نتائج الإحالة مع الشركاء مما قد يؤدي إلى احتمالية عدم تقديم الخدمة المطلوبة للمستفيدين.'),
  (md5('cts-v0.2.1-item-204')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-35')::uuid, 204, 'تُراجع الجمعية إجراءات الإحالة بشكل دوري للتأكد من كفاءتها وملاءمتها.', 'وضع جدول زمني لمراجعة دورية لإجراءات الإحالة مع إجراء التعديلات اللازمة بناءً على التقييمات والدروس المستفادة.', 'تُراجع الجمعية إجراءات الإحالة بشكل دوري مما يضمن تحسين العملية باستمرار وملاءمتها مع التغيرات والاحتياجات الجديدة.', 'لا تُراجع الجمعية إجراءات الإحالة بشكل منتظم مما قد يؤدي إلى استمرار استخدام إجراءات قد تكون غير فعّالة أو غير ملائمة.'),
  (md5('cts-v0.2.1-item-205')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-36')::uuid, 205, 'لدى الجمعية منهجية واضحة وموثقة لتقييم الشراكات الفنية تشمل الفوائد والمخاطر.', 'إعداد وتوثيق منهجية شاملة لتقييم الشراكات الفنية تشمل الفوائد والمخاطر مع تحديثها دوريًا لضمان مواءمتها للاحتياجات.', 'تمتلك الجمعية منهجية واضحة وموثقة لتقييم الشراكات الفنية مما يتيح تحليل الفوائد والمخاطر بدقة ويسهم في اتخاذ قرارات مدروسة.', 'لا توجد لدى الجمعية منهجية واضحة وموثقة لتقييم الشراكات الفنية مما قد يؤدي إلى قرارات عشوائية وضعف في إدارة الشراكات.'),
  (md5('cts-v0.2.1-item-206')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-36')::uuid, 206, 'تنفذ الجمعية تقييمًا دوريًا لكل شراكة فنية استنادًا إلى الأهداف المحددة مسبقًا.', 'وضع جدول زمني دوري لتقييم الشراكات الفنية بناءً على الأهداف المحددة مسبقًا مع توثيق النتائج واستخدامها في التحسين.', 'تُجري الجمعية تقييمات دورية للشراكات الفنية بناءً على الأهداف المحددة مسبقًا مما يضمن مراقبة مستمرة لتحقيق الأهداف.', 'لا تُنفذ الجمعية تقييمات دورية للشراكات الفنية مما قد يؤدي إلى ضعف في متابعة الأداء وعدم تحقيق الأهداف المرجوة.'),
  (md5('cts-v0.2.1-item-207')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-36')::uuid, 207, 'تحلل الجمعية فوائد الشراكة بما في ذلك تأثيرها على جودة الخدمات وتحقيق الأهداف.', 'إجراء تحليل شامل لفوائد الشراكة  الفنيةبشكل دوري مع التركيز على تحسين جودة الخدمات وتحقيق الأهداف المرسومة.', 'تحلل الجمعية فوائد الشراكات بعناية مع التركيز على تأثيرها على جودة الخدمات وتحقيق الأهداف مما يعزز من قيمة الشراكة.', 'لا تُجري الجمعية تحليلًا كافيًا لفوائد الشراكة مما قد يؤدي إلى استمرارية شراكات غير مجدية أو غير فعّالة.'),
  (md5('cts-v0.2.1-item-208')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-36')::uuid, 208, 'تُحدد الجمعية المخاطر المحتملة المتعلقة باستمرار الشراكة أو تنفيذها.', 'إنشاء عملية تقييم منهجية لتحديد المخاطر المحتملة لكل شراكة فنية مع وضع خطط استباقية لإدارتها وتقليل آثارها.', 'تُحدد الجمعية المخاطر المحتملة لكل شراكة مما يُمكّنها من اتخاذ تدابير وقائية تساهم في استمرارية الشراكة بنجاح.', 'لا تُحدد الجمعية المخاطر المحتملة المرتبطة بالشراكات مما يزيد من احتمالية التعرض لمشكلات قد تؤثر على تنفيذ الشراكة.'),
  (md5('cts-v0.2.1-item-209')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-36')::uuid, 209, 'تُقرر الجمعية استمرار الشراكة أو إيقافها بناءً على نتائج التقييم والتحليل.', 'إنشاء نظام لاتخاذ قرارات مدروسة بشأن استمرار الشراكات الفنية أو إيقافها بناءً على نتائج التقييم والتحليل الدوري.', 'تُتخذ قرارات الجمعية بشأن استمرار الشراكة أو إيقافها بناءً على تقييم وتحليل دقيق مما يعزز من كفاءة إدارة الشراكات.', 'لا تستند قرارات استمرار أو إيقاف الشراكة إلى تحليل منهجي مما قد يؤدي إلى قرارات غير مدروسة قد تؤثر على الجمعية.'),
  (md5('cts-v0.2.1-item-210')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-36')::uuid, 210, 'تُوثق الجمعية نتائج التقييم والتحليل بشكل منظم وسهل الوصول.', 'إنشاء نظام توثيق مركزي لنتائج التقييم والتحليل مع ضمان سهولة الوصول للمعلومات من قبل المعنيين.', 'تُوثق الجمعية نتائج التقييم والتحليل بشكل منظم وسهل الوصول مما يضمن الشفافية وسهولة الرجوع إلى البيانات عند الحاجة.', 'لا تُوثق الجمعية نتائج التقييم والتحليل بشكل كافٍ مما قد يؤدي إلى فقدان البيانات وصعوبة تحسين العمليات.'),
  (md5('cts-v0.2.1-item-211')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-36')::uuid, 211, 'تُبلغ الجمعية الشركاء بقراراتها مع توضيح أسباب استمرار الشراكة أو إيقافها.', 'إنشاء آلية واضحة لإبلاغ الشركاء بقرارات الجمعية بشأن الشراكة مع توضيح الأسباب وتعزيز التواصل المستمر.', 'تُبلغ الجمعية الشركاء بقراراتها مع توضيح أسباب استمرار الشراكة أو إيقافها مما يعزز الشفافية ويقوي العلاقات المهنية.', 'لا تُبلغ الجمعية الشركاء بقراراتها أو لا توضح أسبابها مما قد يؤدي إلى ضعف الثقة وسوء التفاهم بين الأطراف.'),
  (md5('cts-v0.2.1-item-212')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-36')::uuid, 212, 'تُراجع الجمعية منهجية التقييم بشكل دوري بناءً على الدروس المستفادة.', 'تحديد جدول زمني لمراجعة منهجية التقييم بانتظام مع تضمين الدروس المستفادة من الشراكات السابقة في عملية التحسين.', 'تُراجع الجمعية منهجية تقييم الشراكات بشكل دوري مما يساعد في تحسينها وجعلها أكثر توافقًا مع احتياجات العمل والتغيرات.', 'لا تُراجع الجمعية منهجية تقييم الشراكات بانتظام مما قد يؤدي إلى استخدام منهجيات قديمة وغير فعّالة.'),
  (md5('cts-v0.2.1-item-213')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-37')::uuid, 213, 'لدى الجمعية قاعدة بيانات تشمل جميع بيانات الشركاء.', 'إنشاء قاعدة بيانات شاملة تضم جميع بيانات الشركاء مع ضمان تنظيمها وسهولة الوصول إليها من قبل المعنيين.', 'تُدير الجمعية قاعدة بيانات شاملة تضم جميع بيانات الشركاء مما يسهل الوصول إلى المعلومات اللازمة لإدارة الشراكات بفعالية.', 'لا تمتلك الجمعية قاعدة بيانات شاملة لبيانات الشركاء مما قد يؤدي إلى صعوبة تنظيم المعلومات وصعوبة تتبع الشراكات.'),
  (md5('cts-v0.2.1-item-214')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-37')::uuid, 214, 'تُحدث الجمعية بشكل دوري معلومات الاتصال بالشركاء مثل أرقام الهواتف والبريد الإلكتروني والعناوين.', 'وضع آلية دورية لتحديث معلومات الاتصال بالشركاء مع تخصيص مسؤولية محددة لهذه المهمة لضمان دقتها.', 'تحرص الجمعية على تحديث معلومات الاتصال بالشركاء بشكل دوري مما يضمن دقة التواصل وسرعة الوصول إليهم عند الحاجة.', 'لا تُحدّث الجمعية معلومات الاتصال بالشركاء بانتظام مما قد يؤدي إلى ضعف التواصل وصعوبة متابعة الشراكات.'),
  (md5('cts-v0.2.1-item-215')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-37')::uuid, 215, 'تُسجل الجمعية تفاصيل المشاريع المُنفذة بالتعاون مع كل شريك.', 'إنشاء نظام موحد لتسجيل تفاصيل المشاريع المُنفذة مع الشركاء مع تحديث السجلات بانتظام لضمان اكتمالها.', 'تُسجل الجمعية تفاصيل جميع المشاريع المُنفذة بالتعاون مع الشركاء مما يوفر مرجعًا موثقًا يمكن الاعتماد عليه لتحليل الأداء وتحسين التعاون.', 'لا تُسجل الجمعية تفاصيل المشاريع المُنفذة مع الشركاء بشكل منتظم مما قد يؤدي إلى فقدان المعلومات وضعف التوثيق.'),
  (md5('cts-v0.2.1-item-216')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-37')::uuid, 216, 'تحتفظ الجمعية بنتائج تقييم الشراكات في السجلات المخصصة لكل شريك.', 'تصميم نظام لحفظ نتائج تقييم الشراكات في سجلات مخصصة لكل شريك مع ضمان سهولة الوصول إليها عند الحاجة.', 'تحتفظ الجمعية بنتائج تقييم الشراكات في سجلات مخصصة لكل شريك مما يعزز الشفافية ويساعد في تحسين الشراكات المستقبلية.', 'لا تحتفظ الجمعية بنتائج تقييم الشراكات بشكل منظم مما قد يؤدي إلى صعوبة تتبع أداء الشراكات وإجراء التحسينات المطلوبة.'),
  (md5('cts-v0.2.1-item-217')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-37')::uuid, 217, 'تُحدد الجمعية صلاحيات الوصول إلى قاعدة البيانات لضمان أمن المعلومات.', 'تحديد صلاحيات وصول دقيقة لقاعدة بيانات الشركاء مع تطبيق إجراءات أمنية صارمة لضمان حماية المعلومات.', 'تُحدد الجمعية صلاحيات وصول واضحة لقاعدة بيانات الشركاء مما يضمن حماية البيانات ومنع الوصول غير المصرح به.', 'لا تُحدد الجمعية صلاحيات واضحة للوصول إلى قاعدة البيانات مما يعرضها لمخاطر أمنية وإمكانية الوصول غير المصرح به.'),
  (md5('cts-v0.2.1-item-218')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-37')::uuid, 218, 'تُراجع الجمعية السجلات بشكل دوري للتأكد من دقتها وتحديثها.', 'إعداد جدول زمني لمراجعة دورية لسجلات الشركاء مع تخصيص فريق مسؤول لضمان دقة المعلومات وتحديثها.', 'تُراجع الجمعية السجلات المتعلقة بالشركاء بشكل دوري مما يضمن دقتها وحداثتها ويساعد في تحسين إدارة الشراكات.', 'لا تُراجع الجمعية السجلات بانتظام مما قد يؤدي إلى وجود بيانات غير دقيقة أو قديمة قد تؤثر على كفاءة الشراكات.'),
  (md5('cts-v0.2.1-item-219')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-38')::uuid, 219, 'يوجد لدى الجمعية سياسات مكتوبة تُحدد مبادئ وقواعد تقديم الخدمات للمستفيدين.', 'إعداد سياسات مكتوبة تُحدد مبادئ وقواعد تقديم الخدمات للمستفيدين مع مراجعتها بشكل دوري لضمان فعاليتها.', 'تمتلك الجمعية سياسات مكتوبة تُحدد مبادئ وقواعد تقديم الخدمات للمستفيدين مما يضمن تنظيم العملية وتوحيد معايير الخدمة.', 'لا توجد سياسات مكتوبة تُحدد مبادئ وقواعد تقديم الخدمات مما قد يؤدي إلى غياب التوجيه الواضح وتفاوت في تقديم الخدمات.'),
  (md5('cts-v0.2.1-item-220')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-38')::uuid, 220, 'تتضمن السياسات مبادئ واضحة توجه تقديم الخدمات للمستفيدين مثل العدالة الشفافية والجودة.', 'إضافة مبادئ واضحة مثل العدالة والشفافية والجودة إلى السياسات المكتوبة مع تدريب العاملين على الالتزام بها.', 'تُعزز الجمعية من العدالة الشفافية والجودة في تقديم الخدمات من خلال تضمين هذه المبادئ بوضوح في السياسات المكتوبة.', 'لا تتضمن السياسات مبادئ واضحة مثل العدالة والشفافية والجودة مما قد يؤدي إلى تقديم خدمات قد لا تتوافق مع أفضل الممارسات.'),
  (md5('cts-v0.2.1-item-221')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-38')::uuid, 221, 'تُحدد السياسات القواعد المتعلقة بالإجراءات والمعايير والشروط لتقديم الخدمات.', 'إعداد سياسات تتضمن القواعد والإجراءات والمعايير المتعلقة بتقديم الخدمات مع توضيحها للعاملين والمستفيدين.', 'تُحدد السياسات القواعد والإجراءات والمعايير بوضوح مما يضمن تقديم الخدمات بكفاءة وبما يتوافق مع احتياجات المستفيدين.', 'لا تُحدد السياسات القواعد والإجراءات اللازمة لتقديم الخدمات مما قد يؤدي إلى غموض وصعوبة في تنظيم العملية.'),
  (md5('cts-v0.2.1-item-222')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-38')::uuid, 222, 'تُراجع السياسات وتُحدث بشكل دوري للتأكد من ملاءمتها للتغيرات والاحتياجات.', 'إعداد جدول زمني لمراجعة السياسات بشكل دوري مع إشراك أصحاب العلاقة لضمان توافقها مع المتطلبات الحالية.', 'تُراجع الجمعية سياساتها بشكل دوري لضمان ملاءمتها للتغيرات والاحتياجات مما يُحسن من جودة الخدمات ويضمن استمراريتها.', 'لا تُراجع السياسات بانتظام مما قد يؤدي إلى استخدامها دون تحديثات تتماشى مع التغيرات والاحتياجات الجديدة.'),
  (md5('cts-v0.2.1-item-223')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-38')::uuid, 223, 'وثيقة السياسات معتمدة ومحدثة ويظهر تاريخ الاعتماد وتاريخ آخر تحديث.', 'إضافة تاريخ الاعتماد وتاريخ آخر تحديث إلى وثيقة السياسات مع ضمان تحديثها عند إجراء أي تعديلات.', 'تتضمن وثيقة السياسات تاريخ الاعتماد وتاريخ آخر تحديث مما يُعزز من موثوقيتها ويضمن استخدامها كمرجع رسمي.', 'لا تتضمن وثيقة السياسات تاريخ الاعتماد أو آخر تحديث مما يضعف مصداقيتها ويُعيق استخدامها كمرجع معتمد.'),
  (md5('cts-v0.2.1-item-224')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-38')::uuid, 224, 'وثيقة السياسة متاحة وسهل الوصول لأصحاب العلاقة.', 'توفير وثيقة السياسات إلكترونيًا وورقيًا لجميع أصحاب العلاقة مع ضمان سهولة الوصول إليها في أي وقت.', 'تُتيح الجمعية وثيقة السياسات لجميع أصحاب العلاقة بسهولة مما يعزز من الشفافية ويساعد في الالتزام بالقواعد.', 'لا تُوفر الجمعية وثيقة السياسات بسهولة لأصحاب العلاقة مما قد يؤدي إلى غياب الشفافية وصعوبة الالتزام بالقواعد.'),
  (md5('cts-v0.2.1-item-225')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-39')::uuid, 225, 'تُحدد الجمعية متطلبات واضحة لتقديم الخدمات للفئات المستهدفة.', 'إعداد قائمة واضحة ومكتوبة تحدد متطلبات تقديم الخدمات للفئات المستهدفة مع تحديثها دوريًا لتلبية الاحتياجات.', 'تُحدد الجمعية متطلبات واضحة لتقديم الخدمات للفئات المستهدفة مما يضمن تنظيم العملية وتوفير الخدمات بشكل فعال يتماشى مع الاحتياجات.', 'لا تُحدد الجمعية متطلبات واضحة لتقديم الخدمات مما قد يؤدي إلى غموض وصعوبة في تحديد أهلية المستفيدين وتقديم الخدمات المناسبة.'),
  (md5('cts-v0.2.1-item-226')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-39')::uuid, 226, 'تُعرّف الجمعية معايير دقيقة تضمن جودة تقديم الخدمات ووصولها بشكل عادل.', 'وضع معايير دقيقة لجودة تقديم الخدمات مع تدريب العاملين على تطبيقها وضمان العدالة في تقديمها.', 'تعتمد الجمعية معايير دقيقة لضمان جودة تقديم الخدمات ووصولها بشكل عادل مما يعزز الثقة بين الجمعية والمستفيدين.', 'لا تُعرّف الجمعية معايير دقيقة لجودة تقديم الخدمات مما قد يؤدي إلى تباين في مستوى الخدمة وعدم تحقيق العدالة بين المستفيدين.'),
  (md5('cts-v0.2.1-item-227')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-39')::uuid, 227, 'تُحدد الجمعية آليات واضحة وإجراءات عادلة لإيقاف تقديم الخدمات عند الحاجة.', 'تطوير آليات واضحة وعادلة لإيقاف تقديم الخدمات مع توثيقها وإبلاغ المستفيدين بها لضمان الشفافية.', 'تُحدد الجمعية آليات واضحة وعادلة لإيقاف تقديم الخدمات عند الحاجة مما يضمن التعامل بشفافية وموضوعية في هذه الحالات.', 'لا تُحدد الجمعية آليات واضحة لإيقاف تقديم الخدمات مما قد يؤدي إلى قرارات عشوائية قد تؤثر سلبًا على علاقة الجمعية بالمستفيدين.'),
  (md5('cts-v0.2.1-item-228')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-39')::uuid, 228, 'تُبلغ الجمعية المستفيدين بمتطلبات ومعايير تقديم وإيقاف الخدمات لضمان الشفافية.', 'إعداد قنوات فعّالة لإبلاغ المستفيدين بمتطلبات ومعايير تقديم وإيقاف الخدمات مثل الأدلة الإرشادية أو الإعلانات الرسمية.', 'تُبلغ الجمعية المستفيدين بوضوح بمتطلبات ومعايير تقديم وإيقاف الخدمات مما يعزز من الشفافية والثقة في العمليات.', 'لا تُبلغ الجمعية المستفيدين بمتطلبات ومعايير تقديم وإيقاف الخدمات مما قد يؤدي إلى ضعف التواصل وصعوبة فهم المستفيدين للإجراءات.'),
  (md5('cts-v0.2.1-item-229')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-39')::uuid, 229, 'تُراجع المنظمة المعايير بشكل دوري لتتوافق مع احتياجات الفئات المستهدفة والتغيرات في البيئة.', 'وضع جدول زمني دوري لمراجعة المعايير  وتنفيذ المراجعة مع إشراك أصحاب العلاقة لضمان توافقها مع الاحتياجات والتغيرات البيئية.', 'تُراجع الجمعية المعايير بشكل دوري لضمان توافقها مع احتياجات الفئات المستهدفة والتغيرات البيئية مما يعزز من فعالية الخدمات.', 'لا تُراجع الجمعية المعايير بشكل دوري مما قد يؤدي إلى تقديم خدمات قديمة أو غير متوافقة مع الاحتياجات الحالية.'),
  (md5('cts-v0.2.1-item-230')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-40')::uuid, 230, 'تُعد الجمعية وثائق شاملة تُحدد إجراءات تقديم الخدمات خطوة بخطوة.', 'إعداد وثائق شاملة ومفصلة تُوضح إجراءات تقديم الخدمات خطوة بخطوة مع مراجعتها وتحديثها عند الحاجة.', 'تُعد الجمعية وثائق شاملة تُوضح إجراءات تقديم الخدمات خطوة بخطوة مما يضمن وضوح العمليات وتحقيق تنظيم عالٍ في تقديم الخدمات.', 'لا توجد وثائق شاملة تُحدد إجراءات تقديم الخدمات مما قد يؤدي إلى غموض في العمليات وصعوبة تحقيق الكفاءة في تقديم الخدمات.'),
  (md5('cts-v0.2.1-item-231')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-40')::uuid, 231, 'تُطور الجمعية أدلة مفصلة توضح مراحل تقديم الخدمة والخطوات المطلوبة في كل مرحلة.', 'تصميم أدلة مفصلة تُوضح مراحل تقديم الخدمة والخطوات اللازمة لكل مرحلة مع توفير تدريب للعاملين على استخدامها.', 'تُوفر الجمعية أدلة تفصيلية تُحدد بوضوح مراحل تقديم الخدمة والخطوات المطلوبة في كل مرحلة مما يسهم في تحسين جودة التنفيذ.', 'لا تُوفر الجمعية أدلة مفصلة توضح مراحل تقديم الخدمة مما قد يؤدي إلى تباين في تنفيذ العمليات وصعوبة تحقيق الاتساق.'),
  (md5('cts-v0.2.1-item-232')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-40')::uuid, 232, 'تُحدد الأدلة المسؤوليات والصلاحيات لكل مرحلة ولكل موظف أو فريق.', 'تحديد  المسؤوليات والصلاحيات في الأدلة الإرشادية لكل مرحلة ولكل موظف أو فريق مع مراجعتها دوريًا لضمان التزام الجميع.', 'تُحدد الجمعية المسؤوليات والصلاحيات لكل مرحلة ولكل موظف أو فريق ضمن الأدلة مما يضمن وضوح الأدوار وتحقيق التنسيق الفعّال.', 'لا تُحدد الأدلة المسؤوليات والصلاحيات بشكل واضح مما قد يؤدي إلى تداخل الأدوار وصعوبة متابعة تنفيذ الخدمات.'),
  (md5('cts-v0.2.1-item-233')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-40')::uuid, 233, 'تُوثق الجمعية تجربة المستفيد وتدمجها في الأدلة لضمان تحسين الخدمات باستمرار.', 'تصميم آلية لتوثيق تجربة المستفيد ودمج نتائج التوثيق في الأدلة مع استخدام ذلك كمرجع لتحسين الإجراءات والخدمات.', 'توثق الجمعية تجربة المستفيد وتدمج نتائج التوثيق في الأدلة مما يعزز من تحسين الخدمات بشكل مستمر بناءً على احتياجات المستفيدين.', 'لا تُوثق الجمعية تجربة المستفيد أو لا تدمجها في الأدلة مما قد يؤدي إلى عدم الاستفادة من ملاحظات المستفيدين لتحسين الخدمات.'),
  (md5('cts-v0.2.1-item-234')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-40')::uuid, 234, 'تُراجع المنظمة الأدلة والإجراءات بانتظام لتتوافق مع احتياجات المستفيدين والتغيرات.', 'إعداد جدول زمني دوري لمراجعة الأدلة والإجراءات  وتنفيذ المراجعة مع إشراك المستفيدين وأصحاب العلاقة في عملية المراجعة.', 'تُراجع الجمعية الأدلة والإجراءات بشكل منتظم لضمان توافقها مع احتياجات المستفيدين والتغيرات في البيئة المحيطة.', 'لا تُراجع الجمعية الأدلة والإجراءات بشكل دوري مما قد يؤدي إلى عدم ملاءمتها للاحتياجات الحالية والتغيرات المستجدة.'),
  (md5('cts-v0.2.1-item-235')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-40')::uuid, 235, 'الإجراءات والأدلة الإرشادية معتمدة ويظهر فيها تاريخ الاعتماد وتاريخ آخر تحديث.', 'إضافة تاريخ الاعتماد وآخر تحديث إلى الأدلة الإرشادية مع إنشاء آلية لتحديثها بانتظام وتوثيق ذلك لضمان الموثوقية.', 'تتضمن الأدلة الإرشادية تاريخ الاعتماد وآخر تحديث مما يعزز من موثوقيتها واستخدامها كمرجع رسمي.', 'لا تحتوي الأدلة الإرشادية على تاريخ الاعتماد أو آخر تحديث مما قد يؤدي إلى ضعف الموثوقية وصعوبة معرفة مدى حداثة الوثائق.'),
  (md5('cts-v0.2.1-item-236')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-41')::uuid, 236, 'تُعد الجمعية خطط عمل واضحة ومفصلة لكل البرامج والخدمات.', 'إعداد خطط عمل شاملة ومفصلة لكل برنامج أو خدمة تتضمن الأهداف والخطوات اللازمة للتنفيذ مع مراجعتها بشكل دوري.', 'تضع الجمعية خطط عمل واضحة ومفصلة لكل البرامج والخدمات مما يضمن تنظيم الجهود وتحقيق الأهداف بكفاءة.', 'لا تُعد الجمعية خطط عمل واضحة ومفصلة مما قد يؤدي إلى غياب التنظيم وصعوبة تحقيق الأهداف المحددة.'),
  (md5('cts-v0.2.1-item-237')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-41')::uuid, 237, 'تُحدد الجمعية المهام المطلوبة لكل برنامج أو خدمة والمسؤوليات الموكلة لكل فريق أو فرد.', 'وضع قائمة مفصلة بالمهام المطلوبة لكل برنامج أو خدمة مع تحديد المسؤوليات بوضوح لكل فريق أو فرد.', 'تُحدد الجمعية المهام المطلوبة لكل برنامج أو خدمة بوضوح مع تحديد المسؤوليات الموكلة لكل فريق أو فرد مما يضمن توزيع الأدوار بكفاءة.', 'لا تُحدد الجمعية المهام والمسؤوليات بشكل واضح مما قد يؤدي إلى تداخل الأدوار وضعف التنسيق بين الفرق.'),
  (md5('cts-v0.2.1-item-238')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-41')::uuid, 238, 'تُحدد الجمعية مواعيد بدء وانتهاء كل مهمة وجداول زمنية واضحة لكل مرحلة.', 'إعداد جداول زمنية دقيقة لكل مرحلة من مراحل تنفيذ البرامج وتقديم الخدمات مع تضمين مواعيد واضحة لبدء وانتهاء كل مهمة.', 'تضع الجمعية جداول زمنية واضحة لكل مرحلة من مراحل التنفيذ مع تحديد مواعيد بدء وانتهاء كل مهمة مما يساعد في الالتزام بالجدول الزمني.', 'لا تُحدد الجمعية مواعيد دقيقة أو جداول زمنية واضحة مما قد يؤدي إلى تأخير في تنفيذ المهام وصعوبة متابعة التقدم.'),
  (md5('cts-v0.2.1-item-239')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-41')::uuid, 239, 'تُوضح الجمعية الموارد البشرية والمالية والمادية اللازمة لتنفيذ الخطط.', 'إعداد قائمة مفصلة بالموارد المطلوبة لكل برنامج أو خدمة مع التأكد من توافر هذه الموارد قبل بدء التنفيذ.', 'تُحدد الجمعية الموارد البشرية والمالية والمادية اللازمة لتنفيذ الخطط بدقة مما يساعد في تخصيص الموارد بشكل فعّال.', 'لا تُوضح الجمعية الموارد اللازمة لتنفيذ الخطط مما قد يؤدي إلى نقص في الإمكانيات وصعوبة في تنفيذ البرامج والخدمات.'),
  (md5('cts-v0.2.1-item-240')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-41')::uuid, 240, 'تُراجع الجمعية الخطط للتحقق من واقعيتها وجدواها قبل التنفيذ.', 'إجراء مراجعة شاملة للخطط قبل التنفيذ مع إشراك أصحاب العلاقة للتأكد من واقعيتها وجدواها.', 'تُراجع الجمعية الخطط بشكل دوري للتحقق من واقعيتها وجدواها قبل التنفيذ مما يقلل من المخاطر ويضمن تحقيق الأهداف.', 'لا تُراجع الجمعية الخطط قبل التنفيذ مما قد يؤدي إلى احتمالية عدم جدواها أو صعوبات في تطبيقها.'),
  (md5('cts-v0.2.1-item-241')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-41')::uuid, 241, 'تُعدل الجمعية الخطط بناءً على التغيرات أو التحديات التي تظهر أثناء التنفيذ.', 'إنشاء آلية لتعديل الخطط أثناء التنفيذ بناءً على التغيرات أو التحديات مع توثيق هذه التعديلات لضمان استمرارية العمل.', 'تُظهر الجمعية مرونة في تعديل الخطط بناءً على التغيرات أو التحديات مما يضمن استمرارية التنفيذ وتحقيق الأهداف.', 'لا تُعدل الجمعية الخطط لمواكبة التغيرات أو التحديات مما قد يؤدي إلى تعثر التنفيذ أو تحقيق نتائج أقل من المتوقع.'),
  (md5('cts-v0.2.1-item-242')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-42')::uuid, 242, 'تُطور الجمعية خطط متابعة موثقة تحدد جميع الجوانب المرتبطة بمتابعة البرامج والخدمات.', 'إعداد خطط متابعة موثقة تشمل جميع الجوانب المرتبطة بمتابعة البرامج والخدمات مع توضيح الخطوات والإجراءات اللازمة.', 'تضع الجمعية خطط متابعة موثقة ومتكاملة تحدد جميع الجوانب المرتبطة بمتابعة البرامج والخدمات مما يعزز من كفاءة التنفيذ وضمان تحقيق الأهداف.', 'لا توجد خطط متابعة موثقة لدى الجمعية مما قد يؤدي إلى ضعف في متابعة تنفيذ البرامج وصعوبة في تقييم النتائج.'),
  (md5('cts-v0.2.1-item-243')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-42')::uuid, 243, 'تُحدد الجمعية مواعيد منتظمة لإعداد التقارير الدورية والمتخصصة.', 'وضع جدول زمني منتظم لإعداد التقارير الدورية والمتخصصة مع الالتزام بالمواعيد المحددة لضمان التحديث المستمر للمعلومات.', 'تُحدد الجمعية مواعيد منتظمة لإعداد التقارير الدورية والمتخصصة مما يضمن توافر معلومات حديثة ودقيقة حول تقدم البرامج والخدمات.', 'لا تُحدد الجمعية مواعيد منتظمة لإعداد التقارير مما قد يؤدي إلى غياب البيانات المحدثة وصعوبة تقييم الأداء.'),
  (md5('cts-v0.2.1-item-244')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-42')::uuid, 244, 'تُوضح الجمعية نوعية البيانات اللازمة للمتابعة مثل  البيانات الكمية والنوعية.', 'إعداد قائمة مفصلة بالبيانات اللازمة للمتابعة تشمل البيانات الكمية والنوعية المطلوبة مع تدريب الفرق على جمع هذه البيانات.', 'تُحدد الجمعية نوعية البيانات اللازمة للمتابعة بدقة مثل البيانات الكمية والنوعية مما يساعد في قياس التقدم وتحليل الأداء بشكل منهجي.', 'لا تُحدد الجمعية نوعية البيانات المطلوبة للمتابعة مما قد يؤدي إلى ضعف في تحليل الأداء وصعوبة في قياس النتائج.'),
  (md5('cts-v0.2.1-item-245')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-42')::uuid, 245, 'تُعين الجمعية الفرق أو الأفراد المسؤولين عن جمع البيانات وتحليلها.', 'تعيين فرق أو أفراد مختصين بمسؤوليات محددة لجمع البيانات وتحليلها مع توضيح أدوارهم في خطط المتابعة.', 'تُعين الجمعية فرقًا أو أفرادًا مسؤولين بوضوح عن جمع البيانات وتحليلها مما يضمن تنظيم العملية وتحقيق دقة في النتائج.', 'لا تُحدد الجمعية المسؤولين عن جمع البيانات وتحليلها مما قد يؤدي إلى ارتباك وصعوبة في إدارة عملية المتابعة.'),
  (md5('cts-v0.2.1-item-246')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-42')::uuid, 246, 'تُحدد الجمعية الجهات أو الأطراف التي ستُشارك التقارير معها.', 'إعداد قائمة بالجهات والأطراف المستهدفة بمشاركة التقارير مع تحديد نوعية المعلومات التي ستُشارك معهم.', 'تُحدد الجمعية الجهات أو الأطراف التي ستُشارك التقارير معها مما يضمن تعزيز الشفافية وإشراك الأطراف ذات العلاقة في متابعة البرامج.', 'لا تُحدد الجمعية الجهات أو الأطراف المستهدفة بمشاركة التقارير مما قد يؤدي إلى ضعف في التواصل وتضاؤل فرصة التحسين المستمر.'),
  (md5('cts-v0.2.1-item-247')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-42')::uuid, 247, 'تُراجع الجمعية خطط المتابعة بشكل دوري لتتوافق مع التغيرات والاحتياجات الجديدة.', 'وضع جدول زمني دوري لمراجعة خطط المتابعة مع إجراء التعديلات اللازمة لتلبية الاحتياجات المتغيرة وضمان فاعلية المتابعة.', 'تُراجع الجمعية خطط المتابعة بانتظام لتتوافق مع التغيرات والاحتياجات الجديدة مما يضمن تحسين العملية باستمرار.', 'لا تُراجع الجمعية خطط المتابعة بشكل دوري مما قد يؤدي إلى استمرار استخدام إجراءات قديمة وغير ملائمة.'),
  (md5('cts-v0.2.1-item-248')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-43')::uuid, 248, 'تُحدد الجمعية المرافق والأجهزة والمعدات الضرورية لتنفيذ البرامج والخدمات.', 'إعداد قائمة تفصيلية تشمل جميع المرافق والأجهزة والمعدات اللازمة لكل برنامج أو خدمة مع تحديثها دوريًا.', 'تُحدد الجمعية بدقة المرافق والأجهزة والمعدات الضرورية لتنفيذ البرامج والخدمات مما يضمن تحقيق الأهداف بكفاءة وفعالية.', 'لا تُحدد الجمعية المرافق والأجهزة والمعدات الضرورية لتنفيذ البرامج مما قد يؤدي إلى نقص في الموارد وصعوبة في تحقيق الأهداف.'),
  (md5('cts-v0.2.1-item-249')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-43')::uuid, 249, 'تُؤمن الجمعية المرافق المناسبة من حيث الموقع والتجهيزات لضمان تنفيذ الأنشطة.', 'تقييم احتياجات الأنشطة وتوفير مرافق مناسبة تلبي هذه الاحتياجات من حيث الموقع والتجهيزات.', 'تُؤمن الجمعية مرافق مناسبة من حيث الموقع والتجهيزات مما يضمن تنفيذ الأنشطة بسهولة وراحة للمستفيدين.', 'لا تُؤمن الجمعية مرافق مناسبة مما قد يؤدي إلى صعوبة في تنفيذ الأنشطة وتأثير سلبي على جودة الخدمات المقدمة.'),
  (md5('cts-v0.2.1-item-250')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-43')::uuid, 250, 'تُوفر المنظمة الأجهزة والمعدات الضرورية بجودة وكفاءة تلبي احتياجات البرامج والخدمات.', 'اختيار أجهزة ومعدات ذات جودة عالية تلبي احتياجات البرامج مع مراجعة مواصفاتها قبل الشراء لضمان الكفاءة.', 'تُوفر الجمعية الأجهزة والمعدات الضرورية بجودة وكفاءة عالية مما يعزز من جودة الخدمات المقدمة ورضا المستفيدين.', 'لا تُوفر الجمعية أجهزة ومعدات ذات جودة وكفاءة مناسبة مما قد يؤدي إلى تأثير سلبي على تنفيذ البرامج والخدمات.'),
  (md5('cts-v0.2.1-item-251')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-43')::uuid, 251, 'تنفذ الجمعية صيانة منتظمة للمرافق والمعدات لضمان استدامتها.', 'إعداد خطة صيانة دورية للمرافق والمعدات مع تخصيص موارد لضمان تنفيذها بانتظام.', 'تُنفذ الجمعية صيانة دورية للمرافق والمعدات مما يضمن استدامتها ويقلل من الأعطال أو التكاليف غير المتوقعة.', 'لا تُنفذ الجمعية صيانة منتظمة مما قد يؤدي إلى تدهور المرافق والمعدات وتوقف الأنشطة أو انخفاض جودتها.'),
  (md5('cts-v0.2.1-item-252')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-43')::uuid, 252, 'تُراجع الجمعية توافر الموارد بشكل مستمر خلال تنفيذ البرامج والخدمات.', 'تطبيق آلية لمراجعة دورية لتوافر الموارد أثناء تنفيذ البرامج مع تحديد خطط بديلة لتغطية أي نقص محتمل.', 'تُراجع الجمعية بشكل مستمر توافر الموارد اللازمة أثناء تنفيذ البرامج مما يضمن استمرارية الأنشطة دون انقطاع.', 'لا تُراجع الجمعية توافر الموارد بشكل مستمر مما قد يؤدي إلى نقص مفاجئ في الموارد وتأخير تنفيذ الأنشطة.'),
  (md5('cts-v0.2.1-item-253')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-43')::uuid, 253, 'تُوثق الجمعية كل عمليات توفير الموارد وتخصيصها لضمان الشفافية والمساءلة.', 'إنشاء نظام توثيق شامل لكل عمليات توفير وتخصيص الموارد مع مراجعة السجلات بانتظام لضمان الدقة والمساءلة.', 'تُوثق الجمعية جميع عمليات توفير الموارد وتخصيصها مما يعزز من الشفافية والمساءلة في إدارة الموارد.', 'لا تُوثق الجمعية عمليات توفير الموارد وتخصيصها مما قد يؤدي إلى ضعف في الشفافية وصعوبة تتبع استخدام الموارد.'),
  (md5('cts-v0.2.1-item-254')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-44')::uuid, 254, 'تُجري الجمعية تقييمًا دوريًا لمواقع تقديم البرامج والخدمات لضمان سهولة الوصول إليها.', 'إعداد جدول زمني لإجراء تقييم دوري لمواقع تقديم البرامج والخدمات مع تضمين معايير واضحة لتقييم سهولة الوصول.', 'تُجري الجمعية تقييمات دورية لمواقع تقديم البرامج والخدمات مما يضمن سهولة وصول المستفيدين وفعالية تقديم الخدمات.', 'لا تُجري الجمعية تقييمًا دوريًا لمواقع تقديم البرامج والخدمات مما قد يؤدي إلى صعوبة وصول المستفيدين وتأثير سلبي على تقديم الخدمات.'),
  (md5('cts-v0.2.1-item-255')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-44')::uuid, 255, 'تُحدد الجمعية مواقع مناسبة من حيث القرب المرافق ووسائل النقل المتاحة.', 'تطوير آلية اختيار مواقع مناسبة للخدمات مع تقييم الموقع بناءً على معايير القرب والمرافق ووسائل النقل.', 'تختار الجمعية مواقع مناسبة من حيث القرب وتوفر المرافق ووسائل النقل مما يُسهل على المستفيدين الوصول إلى الخدمات.', 'لا تُحدد الجمعية مواقع مناسبة بناءً على قربها وتوفر المرافق ووسائل النقل مما يُصعب الوصول ويقلل من فعالية البرامج.'),
  (md5('cts-v0.2.1-item-256')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-44')::uuid, 256, 'تُوفر الجمعية مداخل ومرافق ميسرة للأشخاص ذوي الاحتياجات الخاصة.', 'إجراء تعديلات على المرافق والمداخل لتكون ميسرة للأشخاص ذوي الإعاقة مع الالتزام بالمعايير المعتمدة لتسهيل الوصول.', 'تُراعي الجمعية احتياجات الأشخاص ذوي الإعاقة من خلال توفير مداخل ومرافق ميسرة مما يعزز من شمولية الخدمات.', 'لا تُوفر الجمعية مداخل ومرافق ميسرة للأشخاص ذوي الإعاقة مما قد يؤدي إلى عوائق تمنع شريحة كبيرة من الاستفادة من الخدمات.'),
  (md5('cts-v0.2.1-item-257')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-44')::uuid, 257, 'تُطور الجمعية إرشادات واضحة ومحددة للحركة داخل المواقع.', 'تصميم إرشادات واضحة للحركة داخل المواقع تشمل لوحات توجيهية ومخططات مرئية مع تحديثها عند الحاجة.', 'تُوفر الجمعية إرشادات واضحة للحركة داخل المواقع مما يُسهل التنقل ويُحسن من تجربة المستفيدين.', 'لا تُطور الجمعية إرشادات واضحة للحركة داخل المواقع مما قد يؤدي إلى ارتباك المستفيدين وصعوبة التنقل.'),
  (md5('cts-v0.2.1-item-258')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-44')::uuid, 258, 'تُوفر الجمعية معلومات محدثة حول مواقع تقديم الخدمات وطرق الوصول إليها.', 'إعداد نظام لتحديث ونشر معلومات حول مواقع تقديم الخدمات يشمل خرائط ووسائل الاتصال والإرشادات المحدثة.', 'تُوفر الجمعية معلومات محدثة حول مواقع تقديم الخدمات وطرق الوصول إليها مما يعزز من شفافية الخدمة وسهولة التخطيط للوصول.', 'لا تُوفر الجمعية معلومات كافية أو محدثة حول مواقع تقديم الخدمات مما قد يؤدي إلى صعوبة وصول المستفيدين.'),
  (md5('cts-v0.2.1-item-259')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-44')::uuid, 259, 'تُجمع آراء المستفيدين حول سهولة الوصول والتحرك داخل المواقع لتحسين الخدمات.', 'تصميم استبيانات أو جلسات استماع مخصصة لجمع آراء المستفيدين حول سهولة الوصول مع استخدام النتائج لتحسين المرافق.', 'تُجمع الجمعية آراء المستفيدين حول سهولة الوصول مما يتيح لها فرصة تحسين الخدمات وتلبية احتياجاتهم بشكل أفضل.', 'لا تُجمع الجمعية آراء المستفيدين حول سهولة الوصول مما يحرمها من فرصة التعرف على المشكلات والعمل على تحسينها.'),
  (md5('cts-v0.2.1-item-260')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-44')::uuid, 260, 'تُوثق الجمعية جميع التعديلات والتحسينات التي أُجريت على المرافق لتسهيل الوصول.', 'إنشاء نظام توثيق شامل لكل التعديلات والتحسينات التي أُجريت على المرافق مع حفظ السجلات بشكل منتظم لمراجعتها عند الحاجة.', 'تُوثق الجمعية جميع التعديلات والتحسينات التي أُجريت على المرافق مما يضمن الشفافية ويُسهل تتبع الجهود المبذولة لتحسين الوصول.', 'لا تُوثق الجمعية التعديلات والتحسينات على المرافق مما قد يؤدي إلى فقدان البيانات وصعوبة قياس التطورات المحققة.'),
  (md5('cts-v0.2.1-item-261')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-45')::uuid, 261, 'تُعد الجمعية قائمة شاملة بالخدمات التي تقدمها مع تفاصيل واضحة لكل خدمة.', 'إعداد قائمة شاملة ومفصلة تتضمن جميع الخدمات المقدمة مع توضيح التفاصيل لكل خدمة لضمان وضوحها وسهولة الوصول إليها.', 'تُعد الجمعية قائمة شاملة ومفصلة بالخدمات التي تقدمها مما يُسهل على المستفيدين التعرف على الخدمات المتاحة وكيفية الاستفادة منها.', 'لا تُعد الجمعية قائمة شاملة بالخدمات أو لا تتضمن التفاصيل اللازمة مما قد يؤدي إلى صعوبة فهم المستفيدين لطبيعة الخدمات.'),
  (md5('cts-v0.2.1-item-262')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-45')::uuid, 262, 'تُعد الجمعية مواد توعوية تحتوي على معلومات عن كيفية الوصول إلى الخدمات والاستفادة منها.', 'تصميم مواد توعوية تفصيلية تشرح كيفية الوصول إلى الخدمات والاستفادة منها مع توجيهها إلى الفئات المستهدفة.', 'تُعد الجمعية مواد توعوية شاملة تحتوي على معلومات واضحة حول كيفية الوصول إلى الخدمات والاستفادة منها مما يعزز من وعي المستفيدين.', 'لا تُعد الجمعية مواد توعوية كافية حول الخدمات مما قد يؤدي إلى ضعف معرفة المستفيدين بكيفية الوصول والاستفادة من الخدمات.'),
  (md5('cts-v0.2.1-item-263')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-45')::uuid, 263, 'تستخدم الجمعية وسائل تواصل متنوعة مثل المواقع الإلكترونية ووسائل التواصل الاجتماعي والنشرات الورقية لتوصيل المعلومات.', 'توسيع نطاق وسائل التواصل لتشمل المواقع الإلكترونية ووسائل التواصل الاجتماعي والنشرات الورقية مع تحسين جودة المحتوى المقدم.', 'تستخدم الجمعية وسائل تواصل متنوعة لضمان وصول المعلومات لجميع الفئات المستهدفة بطرق تناسب احتياجاتهم.', 'لا تُنوع الجمعية وسائل التواصل لتوصيل المعلومات مما قد يؤدي إلى عدم وصولها لفئات معينة من المستفيدين.'),
  (md5('cts-v0.2.1-item-264')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-45')::uuid, 264, 'تُصمم المعلومات والمواد بما يناسب احتياجات المستفيدين بما في ذلك الأشخاص ذوي الإعاقة.', 'إعادة تصميم المواد والمعلومات لتكون متاحة ومناسبة لجميع الفئات مع تضمين أدوات دعم مثل النصوص الكبيرة أو الوصف الصوتي.', 'تُراعي الجمعية احتياجات المستفيدين المختلفة بما في ذلك الأشخاص ذوي الإعاقة عند تصميم المواد والمعلومات مما يضمن شمولية الخدمات.', 'لا تُراعي الجمعية احتياجات جميع الفئات بما في ذلك الأشخاص ذوي الإعاقة مما قد يؤدي إلى صعوبة استفادة بعض المستفيدين من المعلومات.'),
  (md5('cts-v0.2.1-item-265')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-45')::uuid, 265, 'تُوضح الجمعية للمستفيدين خطوات وإجراءات الاستفادة من الخدمات.', 'إعداد دليل شامل يوضح خطوات وإجراءات الاستفادة من الخدمات مع تقديمه للمستفيدين عبر القنوات المناسبة.', 'تُقدم الجمعية شرحًا واضحًا للمستفيدين حول خطوات وإجراءات الاستفادة من الخدمات مما يُسهل عليهم الحصول على الدعم المطلوب.', 'لا تُوضح الجمعية خطوات وإجراءات الاستفادة من الخدمات بشكل كافٍ مما قد يؤدي إلى ارتباك المستفيدين وصعوبة الحصول على الخدمات.'),
  (md5('cts-v0.2.1-item-266')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-45')::uuid, 266, 'تُجمع آراء المستفيدين حول وضوح المعلومات ومدى استفادتهم منها.', 'تصميم استبيانات أو أدوات تفاعلية لجمع آراء المستفيدين حول وضوح المعلومات ومدى فائدتها مع استخدام النتائج لتحسين المحتوى.', 'تُجمع الجمعية آراء المستفيدين حول وضوح المعلومات ومدى استفادتهم منها مما يساعد في تحسين جودة المعلومات والخدمات.', 'لا تُجمع الجمعية آراء المستفيدين حول المعلومات المقدمة مما قد يؤدي إلى غياب بيانات تحسين واضحة.'),
  (md5('cts-v0.2.1-item-267')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-45')::uuid, 267, 'تُحدث الجمعية المواد والمعلومات بشكل منتظم لضمان دقتها ومواكبتها للتغيرات.', 'إعداد جدول زمني دوري لتحديث المواد والمعلومات مع تخصيص فريق مسؤول عن مراجعتها وضمان دقتها.', 'تُحدث الجمعية موادها ومعلوماتها بشكل منتظم مما يضمن دقة المحتوى ومواكبته للتغيرات والاحتياجات المستجدة.', 'لا تُحدث الجمعية المواد والمعلومات بانتظام مما قد يؤدي إلى تقديم معلومات قديمة أو غير دقيقة للمستفيدين.'),
  (md5('cts-v0.2.1-item-268')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-46')::uuid, 268, 'تُعد الجمعية أدلة مكتوبة توضح مبادئ وإجراءات إدارة العلاقة مع المستفيدين أثناء وبعد تقديم الخدمات.', 'إعداد أدلة مكتوبة تُوضح مبادئ وإجراءات إدارة العلاقة مع المستفيدين أثناء وبعد تقديم الخدمات مع تحديثها بانتظام.', 'تضع الجمعية أدلة مكتوبة تحتوي على مبادئ وإجراءات واضحة لإدارة العلاقة مع المستفيدين مما يعزز من تنظيم العلاقة وبناء الثقة.', 'لا تُعد الجمعية أدلة مكتوبة لإدارة العلاقة مع المستفيدين مما قد يؤدي إلى غموض في التعامل وصعوبة الحفاظ على علاقة فعّالة.'),
  (md5('cts-v0.2.1-item-269')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-46')::uuid, 269, 'تتضمن الأدلة قواعد واضحة للتواصل والتعامل مع المستفيدين بما يعزز الثقة والاحترام المتبادل.', 'تطوير أدلة تُحدد قواعد واضحة للتواصل والتعامل مع المستفيدين مع توفير التدريب اللازم للموظفين على الالتزام بها.', 'تتضمن أدلة الجمعية قواعد واضحة للتواصل مع المستفيدين مما يُعزز الثقة والاحترام المتبادل ويضمن تقديم خدمات بجودة عالية.', 'لا تحتوي الأدلة على قواعد واضحة للتواصل والتعامل مع المستفيدين مما قد يؤدي إلى ضعف في بناء علاقة إيجابية ومستدامة.'),
  (md5('cts-v0.2.1-item-270')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-46')::uuid, 270, 'تُحدد الجمعية الإجراءات الواجب اتباعها لضمان استمرارية العلاقة الإيجابية مع المستفيدين بعد تقديم الخدمة.', 'وضع إجراءات واضحة تضمن استمرارية العلاقة الإيجابية مع المستفيدين مع توثيق ومتابعة هذه الإجراءات لضمان فاعليتها.', 'تُحدد الجمعية إجراءات تضمن استمرارية العلاقة الإيجابية مع المستفيدين بعد تقديم الخدمة مما يدعم رضاهم ويُعزز العلاقة طويلة الأمد.', 'لا تُحدد الجمعية إجراءات لاستمرار العلاقة الإيجابية مع المستفيدين بعد تقديم الخدمة مما قد يؤدي إلى ضعف في متابعة احتياجاتهم المستقبلية.'),
  (md5('cts-v0.2.1-item-271')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-46')::uuid, 271, 'تُحدد الجمعية آليات للإفصاح عن أي تضارب محتمل في المصالح أثناء تقديم الخدمات أو بعدها.', 'تصميم آليات واضحة للإفصاح عن أي تضارب محتمل في المصالح أثناء تقديم الخدمات أو بعدها مع تدريب الموظفين على الالتزام بها.', 'تُحدد الجمعية آليات للإفصاح عن أي تضارب محتمل في المصالح مما يعزز الشفافية ويحمي العلاقة مع المستفيدين من أي تأثير سلبي.', 'لا تُحدد الجمعية آليات للإفصاح عن تضارب المصالح مما قد يؤدي إلى تأثيرات سلبية على ثقة المستفيدين في الخدمات المقدمة.'),
  (md5('cts-v0.2.1-item-272')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-46')::uuid, 272, 'تُوفر الجمعية تدريباً منتظماً للموظفين على استخدام الأدلة الإرشادية والالتزام بها.', 'إعداد برامج تدريبية منتظمة للموظفين على استخدام الأدلة الإرشادية مع تقييم مستمر لمستوى التزامهم بالإجراءات.', 'تُوفر الجمعية تدريباً دورياً للموظفين حول استخدام الأدلة الإرشادية والالتزام بها مما يعزز من كفاءة تقديم الخدمات وجودتها.', 'لا تُوفر الجمعية تدريباً كافياً للموظفين على استخدام الأدلة الإرشادية مما قد يؤدي إلى ضعف في الالتزام بالإجراءات وتأثير سلبي على العلاقة مع المستفيدين.'),
  (md5('cts-v0.2.1-item-273')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-46')::uuid, 273, 'تُراجع الأدلة الإرشادية بشكل دوري لضمان ملاءمتها وتحسينها بناءً على التغيرات أو الملاحظات.', 'إعداد جدول زمني دوري لمراجعة الأدلة الإرشادية وتحسينها بناءً على التغيرات أو الملاحظات لضمان جودتها.', 'تُراجع الجمعية أدلتها الإرشادية بشكل دوري مما يضمن تحسينها وتوافقها مع التغيرات والاحتياجات الجديدة للمستفيدين.', 'لا تُراجع الجمعية الأدلة الإرشادية بانتظام مما قد يؤدي إلى استخدامها دون مراعاة التغيرات أو الملاحظات الواردة من المستفيدين.'),
  (md5('cts-v0.2.1-item-274')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-46')::uuid, 274, 'تُوثق الجمعية جميع التفاعلات مع المستفيدين والإجراءات المتخذة لإدارة العلاقة بفعالية.', 'إنشاء نظام توثيق شامل لجميع التفاعلات والإجراءات المتخذة مع المستفيدين مع مراجعة دورية للسجلات لضمان شفافيتها وفاعليتها.', 'تُوثق الجمعية جميع التفاعلات مع المستفيدين مما يضمن متابعة فعّالة للعلاقة معهم وتحسين جودة الخدمة المقدمة.', 'لا تُوثق الجمعية التفاعلات مع المستفيدين والإجراءات المتخذة مما قد يؤدي إلى فقدان المعلومات وصعوبة تحسين العلاقة.'),
  (md5('cts-v0.2.1-item-275')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-47')::uuid, 275, 'تُعد الجمعية إجراءات ومعايير مكتوبة لضمان سلامة المستفيدين أثناء تقديم الخدمات.', 'إعداد إجراءات ومعايير مكتوبة لضمان سلامة المستفيدين أثناء تقديم الخدمات مع مراجعتها وتحديثها بانتظام.', 'تُعد الجمعية إجراءات ومعايير مكتوبة لضمان سلامة المستفيدين مما يُعزز من الثقة ويُؤمن بيئة آمنة أثناء تقديم الخدمات.', 'لا تُعد الجمعية إجراءات ومعايير مكتوبة لضمان سلامة المستفيدين مما قد يؤدي إلى غياب التنظيم وصعوبة التعامل مع المخاطر.'),
  (md5('cts-v0.2.1-item-276')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-47')::uuid, 276, 'تُوفر الجمعية تدريبًا منتظمًا للعاملين حول إجراءات وتعليمات السلامة.', 'تصميم برنامج تدريبي منتظم للعاملين يغطي تعليمات وإجراءات السلامة مع تقييم مستمر لمستوى التزامهم.', 'تُوفر الجمعية تدريبًا منتظمًا للعاملين على إجراءات وتعليمات السلامة مما يُعزز من جاهزية الفريق لحماية المستفيدين.', 'لا تُوفر الجمعية تدريبًا كافيًا للعاملين حول إجراءات وتعليمات السلامة مما قد يؤدي إلى ضعف الجاهزية وزيادة المخاطر.'),
  (md5('cts-v0.2.1-item-277')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-47')::uuid, 277, 'تُبلغ الجمعية المستفيدين بإجراءات السلامة والتعليمات الواجب اتباعها أثناء تلقي الخدمات.', 'إنشاء آلية واضحة لإبلاغ المستفيدين بإجراءات وتعليمات السلامة مثل الملصقات الإرشادية أو الجلسات التوعوية.', 'تُبلغ الجمعية المستفيدين بإجراءات وتعليمات السلامة مما يُساهم في تعزيز وعيهم وتقليل احتمالية الحوادث.', 'لا تُبلغ الجمعية المستفيدين بإجراءات وتعليمات السلامة مما قد يؤدي إلى سوء فهم وارتفاع احتمالية وقوع الحوادث.'),
  (md5('cts-v0.2.1-item-278')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-47')::uuid, 278, 'تُؤمن الجمعية الأدوات والمعدات الضرورية لضمان بيئة آمنة أثناء تقديم الخدمات.', 'تحديد الأدوات والمعدات الضرورية لتأمين بيئة آمنة أثناء تقديم الخدمات مع تخصيص ميزانية لصيانتها وتحديثها.', 'تُؤمن الجمعية الأدوات والمعدات الضرورية لضمان بيئة آمنة أثناء تقديم الخدمات مما يُعزز من سلامة المستفيدين والعاملين.', 'لا تُوفر الجمعية الأدوات والمعدات الضرورية لضمان بيئة آمنة مما يُعرض المستفيدين والعاملين لمخاطر محتملة.'),
  (md5('cts-v0.2.1-item-279')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-47')::uuid, 279, 'تُجري الجمعية تقييمًا منتظمًا للمخاطر المحتملة المتعلقة بسلامة المستفيدين.', 'إعداد جدول زمني دوري لتقييم المخاطر المحتملة المتعلقة بسلامة المستفيدين مع تنفيذ التوصيات الناتجة عن التقييم.', 'تُجري الجمعية تقييمات منتظمة للمخاطر المحتملة مما يُمكّنها من اتخاذ التدابير الوقائية المناسبة لضمان سلامة المستفيدين.', 'لا تُجري الجمعية تقييمًا منتظمًا للمخاطر المتعلقة بسلامة المستفيدين مما قد يؤدي إلى ضعف الاستعداد لمواجهة الطوارئ.'),
  (md5('cts-v0.2.1-item-280')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-47')::uuid, 280, 'تُعد الجمعية خطة طوارئ تتضمن آليات التعامل مع الحوادث والمواقف الطارئة.', 'إعداد خطة طوارئ شاملة تتضمن إجراءات التعامل مع الحوادث والطوارئ مع تدريب العاملين على تنفيذها بفعالية.', 'تضع الجمعية خطة طوارئ شاملة تتضمن آليات التعامل مع الحوادث مما يُعزز من جاهزية الفريق للتعامل مع المواقف الطارئة بكفاءة.', 'لا تُعد الجمعية خطة طوارئ مما يُعرض المستفيدين والعاملين لخطر عدم القدرة على التعامل مع الحوادث أو الطوارئ.'),
  (md5('cts-v0.2.1-item-281')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-47')::uuid, 281, 'تُوثق الجمعية جميع الحوادث والإجراءات المتخذة لضمان تحسين معايير السلامة بشكل مستمر.', 'إنشاء نظام توثيق شامل لجميع الحوادث والإجراءات المتخذة مع استخدام البيانات لتحسين معايير السلامة بشكل مستمر.', 'تُوثق الجمعية جميع الحوادث والإجراءات المتخذة مما يُتيح لها تحليل البيانات واستخدامها لتحسين معايير السلامة باستمرار.', 'لا تُوثق الجمعية الحوادث والإجراءات المتخذة مما قد يؤدي إلى فقدان الفرصة لتحليل أسباب الحوادث وتحسين الإجراءات.'),
  (md5('cts-v0.2.1-item-282')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-48')::uuid, 282, 'تُنشئ الجمعية نظامًا مخصصًا لتسجيل وحفظ بيانات المستفيدين والخدمات المقدمة لهم.', 'تطوير نظام إلكتروني أو يدوي مخصص لتسجيل وحفظ بيانات المستفيدين والخدمات مع توفير تدريب للعاملين على استخدامه.', 'تُدير الجمعية نظامًا مخصصًا لتسجيل وحفظ بيانات المستفيدين والخدمات المقدمة مما يضمن تنظيم المعلومات وسهولة تتبعها.', 'لم تُنشئ الجمعية نظامًا مخصصًا لتسجيل وحفظ بيانات المستفيدين مما قد يؤدي إلى فقدان البيانات أو صعوبة إدارتها.'),
  (md5('cts-v0.2.1-item-283')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-48')::uuid, 283, 'تُحدث الجمعية سجلات المستفيدين والخدمات بشكل دوري لضمان دقتها.', 'إعداد جدول زمني لتحديث دوري لسجلات المستفيدين والخدمات مع تخصيص مسؤولية واضحة للفرق المعنية.', 'تُحدث الجمعية سجلات المستفيدين والخدمات بشكل دوري مما يضمن دقة البيانات وصحتها للاستخدام في التخطيط والتقييم.', 'لا تُحدث الجمعية السجلات بشكل منتظم مما قد يؤدي إلى وجود بيانات قديمة أو غير دقيقة.'),
  (md5('cts-v0.2.1-item-284')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-48')::uuid, 284, 'تعتمد الجمعية سياسات مكتوبة تضمن سرية وخصوصية بيانات المستفيدين.', 'تطوير واعتماد سياسات مكتوبة لحماية سرية وخصوصية بيانات المستفيدين مع توعية العاملين بها.', 'تُعتمد الجمعية سياسات مكتوبة لحماية سرية وخصوصية بيانات المستفيدين مما يعزز الثقة ويضمن الامتثال للقوانين.', 'لا تعتمد الجمعية سياسات مكتوبة تضمن سرية بيانات المستفيدين مما قد يؤدي إلى مخاطر محتملة لانتهاك الخصوصية.'),
  (md5('cts-v0.2.1-item-285')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-48')::uuid, 285, 'تُحدد الجمعية صلاحيات الوصول إلى بيانات المستفيدين لضمان استخدامها فقط من الأطراف المخولة.', 'إنشاء نظام إدارة صلاحيات يحدد من يمكنه الوصول إلى بيانات المستفيدين بناءً على المسؤوليات الوظيفية.', 'تُحدد الجمعية صلاحيات واضحة للوصول إلى بيانات المستفيدين مما يحمي البيانات من الاستخدام غير المصرح به.', 'لا تُحدد الجمعية صلاحيات الوصول مما يزيد من خطر الوصول غير المصرح به إلى البيانات.'),
  (md5('cts-v0.2.1-item-286')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-48')::uuid, 286, 'تُطبق الجمعية تقنيات وإجراءات لحماية السجلات من الوصول غير المصرح به أو التلاعب.', 'تطبيق تقنيات حماية مثل التشفير والجدران النارية مع تنفيذ بروتوكولات أمنية لمنع الوصول غير المصرح به.', 'تستخدم الجمعية تقنيات وإجراءات متقدمة لحماية السجلات من الوصول غير المصرح به أو التلاعب مما يضمن أمان البيانات.', 'لا تُطبق الجمعية إجراءات كافية لحماية السجلات مما يجعلها عرضة للانتهاك أو التلاعب.'),
  (md5('cts-v0.2.1-item-287')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-48')::uuid, 287, 'تُصمم الجمعية نظامًا يتيح الوصول السريع إلى بيانات المستفيدين عند الحاجة وبما لا يخل بالخصوصية.', 'تطوير نظام يتيح الوصول السريع إلى بيانات المستفيدين بشكل آمن مع توفير واجهات سهلة الاستخدام للعاملين.', 'صممت الجمعية نظامًا يتيح الوصول السريع إلى بيانات المستفيدين عند الحاجة مع الحفاظ على خصوصيتهم.', 'لا يتوفر نظام يتيح الوصول السريع إلى البيانات مما قد يؤدي إلى تأخير في الاستجابة لاحتياجات المستفيدين.'),
  (md5('cts-v0.2.1-item-288')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-48')::uuid, 288, 'تُراجع الجمعية نظام إدارة بيانات المستفيدين وسياساته لضمان استمرارية التوافق مع أفضل الممارسات.', 'إعداد جدول زمني دوري لمراجعة نظام إدارة بيانات المستفيدين مع تحسين السياسات بناءً على أحدث الممارسات والقوانين.', 'تُراجع الجمعية نظام إدارة بيانات المستفيدين بشكل دوري لضمان توافقه مع أفضل الممارسات واللوائح.', 'لا تُراجع الجمعية نظام إدارة البيانات بانتظام مما قد يؤدي إلى استخدام سياسات قديمة وغير ملائمة.'),
  (md5('cts-v0.2.1-item-289')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-49')::uuid, 289, 'تُحدد الجمعية آليات واضحة ومكتوبة لمعالجة استفسارات واقتراحات وشكاوى المستفيدين.', 'إعداد آليات مكتوبة وواضحة لمعالجة استفسارات واقتراحات وشكاوى المستفيدين مع توثيقها ومراجعتها بشكل دوري.', 'تُحدد الجمعية آليات واضحة ومكتوبة لمعالجة استفسارات واقتراحات وشكاوى المستفيدين مما يضمن الشفافية وسهولة متابعة الإجراءات.', 'لا تُحدد الجمعية آليات مكتوبة لمعالجة استفسارات واقتراحات وشكاوى المستفيدين مما قد يؤدي إلى غياب التنظيم وصعوبة في متابعة الشكاوى.'),
  (md5('cts-v0.2.1-item-290')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-49')::uuid, 290, 'تُوفر الجمعية قنوات تواصل متعددة تناسب جميع المستفيدين مثل الهاتف والبريد الإلكتروني ومنصات إلكترونية.', 'توسيع قنوات التواصل لتشمل الهاتف والبريد الإلكتروني والمنصات الإلكترونية لضمان وصول الخدمات إلى جميع الفئات.', 'تُوفر الجمعية قنوات تواصل متعددة تناسب احتياجات المستفيدين مما يضمن سهولة الوصول والتواصل مع الجميع.', 'لا تُوفر الجمعية قنوات تواصل متنوعة مما يحد من قدرة بعض المستفيدين على تقديم استفساراتهم أو شكاواهم.'),
  (md5('cts-v0.2.1-item-291')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-49')::uuid, 291, 'تُحدد الجمعية مدة زمنية لمعالجة كل نوع من أنواع التواصل مثل استفسار واقتراح وشكوى.', 'وضع إطار زمني محدد لكل نوع من أنواع التواصل مثل استفسار واقتراح وشكوى مع الالتزام به لضمان الاستجابة في الوقت المناسب.', 'تُحدد الجمعية مدة زمنية واضحة لمعالجة الاستفسارات والاقتراحات والشكاوى مما يضمن الاستجابة السريعة والفعالة.', 'لا تُحدد الجمعية مدة زمنية لمعالجة أنواع التواصل مما قد يؤدي إلى تأخير في الاستجابة وضعف رضا المستفيدين.'),
  (md5('cts-v0.2.1-item-292')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-49')::uuid, 292, 'تُبلغ الجمعية المستفيدين بإجراءات معالجة استفساراتهم وشكاواهم من خلال مواد توعوية واضحة.', 'إعداد مواد توعوية واضحة وسهلة الفهم تشرح إجراءات معالجة الاستفسارات والشكاوى مع توزيعها على جميع المستفيدين.', 'تُبلغ الجمعية المستفيدين بإجراءات معالجة استفساراتهم وشكاواهم من خلال مواد توعوية واضحة مما يعزز الشفافية والفهم.', 'لا تُوفر الجمعية مواد توعوية توضح إجراءات معالجة الاستفسارات والشكاوى مما قد يؤدي إلى غموض لدى المستفيدين حول العملية.'),
  (md5('cts-v0.2.1-item-293')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-49')::uuid, 293, 'تُدرب الجمعية موظفيها على التعامل مع استفسارات وشكاوى المستفيدين بكفاءة ومهنية.', 'تصميم برامج تدريبية دورية للموظفين لتطوير مهاراتهم في التعامل مع استفسارات وشكاوى المستفيدين بكفاءة ومهنية.', 'تُوفر الجمعية تدريبًا منتظمًا لموظفيها على التعامل مع استفسارات وشكاوى المستفيدين بكفاءة مما يضمن جودة الخدمة.', 'لا تُوفر الجمعية تدريبًا كافيًا لموظفيها على التعامل مع استفسارات وشكاوى المستفيدين مما قد يؤدي إلى ضعف جودة الاستجابة.'),
  (md5('cts-v0.2.1-item-294')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-49')::uuid, 294, 'تُسجل الجمعية جميع الاستفسارات والاقتراحات والشكاوى مع تفاصيل المعالجة والإجراءات المتخذة.', 'إنشاء نظام توثيق شامل لتسجيل جميع الاستفسارات والاقتراحات والشكاوى مع تضمين تفاصيل المعالجة والإجراءات المتخذة.', 'تُوثق الجمعية جميع الاستفسارات والاقتراحات والشكاوى مع تسجيل تفاصيل المعالجة والإجراءات المتخذة لضمان الشفافية والمتابعة.', 'لا تُسجل الجمعية جميع الاستفسارات والشكاوى مما قد يؤدي إلى ضعف القدرة على المتابعة وتحليل البيانات لتحسين العمليات.'),
  (md5('cts-v0.2.1-item-295')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-49')::uuid, 295, 'تُراجع الجمعية بيانات الشكاوى والاستفسارات بانتظام لتحليل الأنماط وتحسين العمليات.', 'وضع خطة مراجعة دورية لبيانات الشكاوى والاستفسارات لتحليل الأنماط وتحديد التحسينات اللازمة للخدمات.', 'تُراجع الجمعية بيانات الشكاوى والاستفسارات بانتظام لتحليل الأنماط وتحديد نقاط التحسين مما يساهم في تحسين الخدمات.', 'لا تُراجع الجمعية بيانات الشكاوى والاستفسارات بشكل دوري مما قد يؤدي إلى فقدان فرصة تحليلها لتحسين العمليات.'),
  (md5('cts-v0.2.1-item-296')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-49')::uuid, 296, 'تجمع الجمعية آراء المستفيدين حول فعالية الإجراءات ومدى رضاهم عن الاستجابة.', 'تصميم استبيانات وآليات لجمع آراء المستفيدين حول فعالية الإجراءات ومدى رضاهم مع استخدام النتائج لتحسين العمليات.', 'تُجمع الجمعية آراء المستفيدين حول فعالية الإجراءات ومدى رضاهم عن الاستجابة مما يُعزز من تحسين الخدمات وتلبية الاحتياجات.', 'لا تُجمع الجمعية آراء المستفيدين بشكل كافٍ مما قد يؤدي إلى ضعف في تحسين الخدمات بناءً على تجربتهم.'),
  (md5('cts-v0.2.1-item-297')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-50')::uuid, 297, 'تُطور الجمعية سياسة مكتوبة مخصصة لتحديد وحماية وتأمين وثائق وممتلكات المستفيدين.', 'إعداد سياسة مكتوبة شاملة تحدد آليات حماية وتأمين وثائق وممتلكات المستفيدين مع تحديثها وفقًا لأفضل الممارسات.', 'تُطور الجمعية سياسة مكتوبة مخصصة لتحديد وحماية وثائق وممتلكات المستفيدين مما يعزز الأمان والثقة لدى المستفيدين.', 'لا تُطور الجمعية سياسة مكتوبة لحماية وثائق وممتلكات المستفيدين مما قد يؤدي إلى احتمالية تعرضها للفقدان أو التلف.'),
  (md5('cts-v0.2.1-item-298')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-50')::uuid, 298, 'تُحدد الجمعية إجراءات وقائية لتجنب فقدان أو تلف الوثائق والممتلكات.', 'تصميم إجراءات وقائية واضحة تتضمن بروتوكولات لحماية الوثائق والممتلكات مع تدريب العاملين على تنفيذها.', 'تضع الجمعية إجراءات وقائية شاملة لتجنب فقدان أو تلف الوثائق والممتلكات مما يُقلل من المخاطر ويحمي حقوق المستفيدين.', 'لا تُحدد الجمعية إجراءات وقائية كافية مما قد يؤدي إلى زيادة احتمالية فقدان أو تلف الوثائق والممتلكات.'),
  (md5('cts-v0.2.1-item-299')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-50')::uuid, 299, 'تُوفر الجمعية وسائل مادية وتقنية لحماية ممتلكات المستفيدين مثل الخزائن أو التشفير الإلكتروني.', 'توفير تجهيزات مادية مثل الخزائن وأدوات تقنية مثل التشفير الإلكتروني لضمان حماية الممتلكات مع مراجعة دورية لتطويرها.', 'تُوفر الجمعية وسائل مادية وتقنية متطورة لحماية ممتلكات المستفيدين مما يعزز من أمانها ويقلل من مخاطر التلف أو السرقة.', 'لا تُوفر الجمعية وسائل مادية أو تقنية كافية لحماية ممتلكات المستفيدين مما يعرضها لمخاطر الفقدان أو التلاعب.'),
  (md5('cts-v0.2.1-item-300')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-50')::uuid, 300, 'تُنشئ الجمعية سجلات دقيقة تحتوي على بيانات كاملة عن الوثائق والممتلكات المحفوظة.', 'تصميم نظام سجلات شامل لتوثيق جميع الممتلكات والوثائق المحفوظة مع تحديثه بانتظام لضمان الدقة.', 'تُنشئ الجمعية سجلات دقيقة وشاملة تحتوي على بيانات كاملة عن الوثائق والممتلكات مما يضمن تتبعها بسهولة وشفافية.', 'لا تُنشئ الجمعية سجلات دقيقة أو شاملة مما قد يؤدي إلى صعوبة تتبع الوثائق والممتلكات وزيادة مخاطر فقدانها.'),
  (md5('cts-v0.2.1-item-301')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-50')::uuid, 301, 'تُوثق الجمعية آليات واضحة للتعامل مع حالات فقدان أو تلف الوثائق والممتلكات.', 'إعداد دليل إجراءات واضح يشرح آليات التعامل مع حالات فقدان أو تلف الممتلكات مع تدريب العاملين على استخدامه.', 'تُوفر الجمعية آليات واضحة للتعامل مع حالات فقدان أو تلف الوثائق مما يضمن استجابة فعالة وتقليل الأضرار.', 'لا تُوثق الجمعية آليات واضحة للتعامل مع حالات فقدان أو تلف الممتلكات مما قد يؤدي إلى غموض في الإجراءات وتأخير الاستجابة.'),
  (md5('cts-v0.2.1-item-302')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-50')::uuid, 302, 'تُعلم الجمعية المستفيدين بحقوقهم وإجراءات التعامل مع ممتلكاتهم وتوثيقها.', 'تصميم مواد توعوية تشمل حقوق المستفيدين وإجراءات التعامل مع ممتلكاتهم مع توفيرها بجميع القنوات المتاحة.', 'تُبلغ الجمعية المستفيدين بحقوقهم وبالإجراءات المتعلقة بحماية ممتلكاتهم مما يعزز الشفافية والثقة.', 'لا تُعلم الجمعية المستفيدين بحقوقهم وإجراءات التعامل مع ممتلكاتهم مما قد يؤدي إلى غياب الوعي وصعوبة التعامل عند الحاجة.'),
  (md5('cts-v0.2.1-item-303')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-50')::uuid, 303, 'تُراجع الجمعية نظام الحماية والإجراءات بشكل منتظم للتأكد من فاعليته وتحسينه عند الحاجة.', 'إعداد جدول زمني لمراجعة نظام الحماية والإجراءات بشكل دوري مع تنفيذ التحديثات اللازمة لضمان الفاعلية.', 'تُراجع الجمعية نظام الحماية بشكل منتظم مما يضمن تحسينه باستمرار لمواكبة الاحتياجات والتحديات الجديدة.', 'لا تُراجع الجمعية نظام الحماية والإجراءات بانتظام مما قد يؤدي إلى تراجع كفاءته وزيادة مخاطر الفقدان أو التلف.'),
  (md5('cts-v0.2.1-item-304')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-50')::uuid, 304, 'تُدرب الجمعية العاملين على اتباع النظام والإجراءات المتعلقة بحماية الممتلكات.', 'تنظيم دورات تدريبية منتظمة للعاملين حول نظام حماية الممتلكات مع تقييم مستمر لمستوى التزامهم بالإجراءات.', 'تُوفر الجمعية تدريبًا منتظمًا للعاملين على اتباع النظام والإجراءات مما يعزز من قدرتهم على حماية ممتلكات المستفيدين بكفاءة.', 'لا تُوفر الجمعية تدريبًا كافيًا للعاملين مما قد يؤدي إلى ضعف في الالتزام بالإجراءات وزيادة المخاطر المحتملة.'),
  (md5('cts-v0.2.1-item-305')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-51')::uuid, 305, 'تُطور الجمعية خطة مكتوبة تحدد خطوات واضحة لإدارة حالات عدم المطابقة ومعالجتها.', 'إعداد خطة مكتوبة وشاملة تحدد خطوات واضحة لإدارة ومعالجة حالات عدم المطابقة مع مراجعتها بشكل دوري.', 'تُطور الجمعية خطة مكتوبة تتضمن خطوات واضحة لإدارة ومعالجة حالات عدم المطابقة مما يضمن توجيه الجهود نحو الحلول المناسبة.', 'لا تمتلك الجمعية خطة مكتوبة لإدارة حالات عدم المطابقة مما قد يؤدي إلى غياب التنظيم وصعوبة التعامل مع المشكلات.'),
  (md5('cts-v0.2.1-item-306')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-51')::uuid, 306, 'تُعرف الجمعية بشكل دقيق حالات عدم المطابقة والمعايير التي تُستخدم لتحديدها.', 'تعريف دقيق لحالات عدم المطابقة ووضع معايير واضحة لتحديدها مع تدريب الفرق على كيفية استخدامها.', 'تُحدد الجمعية حالات عدم المطابقة بدقة مستندة إلى معايير واضحة مما يُسهل التعرف على المشكلات ومعالجتها بكفاءة.', 'لا تُعرف الجمعية حالات عدم المطابقة بشكل دقيق أو تفتقر إلى معايير واضحة مما قد يؤدي إلى صعوبة في التحديد والمعالجة.'),
  (md5('cts-v0.2.1-item-307')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-51')::uuid, 307, 'تُجري الجمعية تحليلاً شاملاً لتحديد الأسباب الجذرية لحالات عدم المطابقة باستخدام أدوات تحليلية فعّالة.', 'تطبيق أدوات تحليلية متقدمة مثل تحليل السبب الجذري لتحديد أسباب حالات عدم المطابقة بدقة.', 'تُجري الجمعية تحليلات شاملة باستخدام أدوات فعّالة لتحديد الأسباب الجذرية لحالات عدم المطابقة مما يضمن معالجة دقيقة ومستدامة.', 'لا تُجري الجمعية تحليلاً شاملاً أو تفتقر إلى الأدوات اللازمة لتحديد الأسباب الجذرية مما قد يؤدي إلى حلول غير فعّالة.'),
  (md5('cts-v0.2.1-item-308')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-51')::uuid, 308, 'تُحدد الجمعية الإجراءات اللازمة لتصحيح حالات عدم المطابقة الحالية ومنع تكرارها مستقبلاً.', 'وضع إجراءات تصحيحية ووقائية مفصلة لكل حالة عدم مطابقة مع مراجعتها وتحديثها لضمان فعاليتها.', 'تُحدد الجمعية إجراءات فعّالة لمعالجة حالات عدم المطابقة الحالية ومنع تكرارها مما يضمن استمرارية تحسين العمليات.', 'لا تُحدد الجمعية إجراءات واضحة لتصحيح حالات عدم المطابقة مما يزيد من احتمالية تكرارها.'),
  (md5('cts-v0.2.1-item-309')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-51')::uuid, 309, 'تُوضح الجمعية المسؤوليات والصلاحيات للجهة المسؤولة عن تنفيذ الإجراءات التصحيحية والوقائية.', 'وضع جدول يوضح المسؤوليات والصلاحيات لكل جهة معنية بتنفيذ الإجراءات مع تحديد آليات المتابعة.', 'تُحدد الجمعية المسؤوليات والصلاحيات بوضوح للجهة المسؤولة عن تنفيذ الإجراءات مما يُسهل متابعة التنفيذ وضمان الجودة.', 'لا تُحدد الجمعية المسؤوليات بوضوح مما قد يؤدي إلى تداخل الأدوار وضعف في تنفيذ الإجراءات التصحيحية.'),
  (md5('cts-v0.2.1-item-310')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-51')::uuid, 310, 'تُتابع الجمعية تنفيذ الإجراءات بشكل دوري لضمان تطبيقها بشكل صحيح وفعّال.', 'إنشاء نظام متابعة دوري لضمان تنفيذ الإجراءات التصحيحية بشكل صحيح وفي الوقت المحدد.', 'تُتابع الجمعية تنفيذ الإجراءات التصحيحية بشكل دوري مما يضمن تطبيقها الصحيح وفعالية الحلول المقدمة.', 'لا تُتابع الجمعية تنفيذ الإجراءات بانتظام مما قد يؤدي إلى احتمالية عدم اكتمال التنفيذ أو ضعف في جودته.'),
  (md5('cts-v0.2.1-item-311')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-51')::uuid, 311, 'تُقيم الجمعية مدى فعالية الإجراءات التصحيحية والوقائية في معالجة حالات عدم المطابقة.', 'إعداد آلية لتقييم دوري لفعالية الإجراءات التصحيحية والوقائية مع تقديم تقارير تحليلية لتحسين الأداء.', 'تُجري الجمعية تقييمًا منتظمًا لفعالية الإجراءات التصحيحية مما يضمن تحسين الحلول وتطويرها باستمرار.', 'لا تُقيم الجمعية فعالية الإجراءات التصحيحية مما قد يؤدي إلى استمرارية مشكلات دون حل فعّال.'),
  (md5('cts-v0.2.1-item-312')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-51')::uuid, 312, 'تُوثق الجمعية جميع حالات عدم المطابقة والإجراءات المتخذة لمعالجتها وتُحدث خطتها بناءً على الدروس المستفادة.', 'إنشاء نظام توثيق شامل لجميع حالات عدم المطابقة والإجراءات المتخذة مع تضمين آلية لتحديث الخطة بناءً على الدروس المستفادة.', 'تُوثق الجمعية جميع حالات عدم المطابقة والإجراءات المتخذة مما يُعزز من الشفافية ويوفر بيانات لتحسين المستقبل.', 'لا تُوثق الجمعية جميع حالات عدم المطابقة مما قد يؤدي إلى فقدان المعلومات وعدم الاستفادة من الدروس المستفادة.'),
  (md5('cts-v0.2.1-item-313')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-52')::uuid, 313, 'تُطور الجمعية نظامًا لتسجيل الأخطاء والشكاوى المتعلقة بأداء العاملين والمتطوعين.', 'إنشاء نظام متكامل لتسجيل الأخطاء والشكاوى مع توفير تدريب للعاملين على كيفية استخدامه لضمان الدقة والشمولية.', 'تُطور الجمعية نظامًا مخصصًا لتسجيل الأخطاء والشكاوى مما يضمن تنظيم البيانات وتسهيل تحليلها لتحسين الأداء.', 'لا تُطور الجمعية نظامًا لتسجيل الأخطاء والشكاوى مما قد يؤدي إلى غياب التوثيق وصعوبة تحسين الأداء أو معالجة المشكلات.'),
  (md5('cts-v0.2.1-item-314')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-52')::uuid, 314, 'تُحدد الجمعية معايير واضحة لتصنيف الأخطاء والشكاوى وتوثيقها.', 'تطوير معايير شاملة ومحددة لتصنيف الأخطاء والشكاوى مع تضمينها في دليل إرشادي يوضح طريقة التوثيق.', 'تُحدد الجمعية معايير واضحة لتصنيف الأخطاء والشكاوى وتوثيقها مما يُسهل فهم طبيعة المشكلات وأولويات معالجتها.', 'لا تُحدد الجمعية معايير واضحة لتصنيف الأخطاء والشكاوى مما قد يؤدي إلى غموض في البيانات وصعوبة تحليلها بفعالية.'),
  (md5('cts-v0.2.1-item-315')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-52')::uuid, 315, 'تُجمع الجمعية البيانات المتعلقة بالأخطاء والشكاوى من مصادر متعددة بشكل منتظم.', 'إنشاء جدول زمني منتظم لجمع البيانات المتعلقة بالأخطاء والشكاوى من مختلف المصادر مع توحيد طريقة الإدخال في النظام.', 'تُجمع الجمعية البيانات من مصادر متعددة بشكل منتظم مما يضمن شمولية المعلومات وتحليلها بشكل دقيق.', 'لا تُجمع الجمعية البيانات من مصادر متعددة أو بانتظام مما قد يؤدي إلى نقص في المعلومات الضرورية لتحليل الأخطاء والشكاوى.'),
  (md5('cts-v0.2.1-item-316')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-52')::uuid, 316, 'تُجري الجمعية تحليلًا شاملًا للبيانات لتحديد أنماط الأخطاء ومسببات الشكاوى.', 'استخدام أدوات تحليلية متقدمة لإجراء تحليل شامل للبيانات وتحديد أنماط الأخطاء ومسببات الشكاوى بدقة.', 'تُجري الجمعية تحليلًا شاملًا للبيانات لتحديد الأنماط والمسببات مما يُسهم في وضع حلول جذرية لتحسين الأداء.', 'لا تُجري الجمعية تحليلًا للبيانات بشكل منتظم مما قد يؤدي إلى استمرار الأخطاء وتكرار الشكاوى دون معرفة مسبباتها.'),
  (md5('cts-v0.2.1-item-317')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-52')::uuid, 317, 'تُطور الجمعية خطة لتحسين أداء العاملين والمتطوعين تتضمن إجراءات تصحيحية لمنع التكرار.', 'إعداد خطة تحسين أداء شاملة تشمل الإجراءات التصحيحية والوقائية مع إشراك العاملين والمتطوعين في صياغتها.', 'تُعد الجمعية خطة تحسين شاملة تتضمن إجراءات تصحيحية ووقائية مما يضمن تقليل الأخطاء ومنع تكرارها.', 'لا تُطور الجمعية خطة لتحسين الأداء أو لا تتضمن إجراءات تصحيحية واضحة مما قد يؤدي إلى استمرار الأخطاء.'),
  (md5('cts-v0.2.1-item-318')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-52')::uuid, 318, 'تُتابع الجمعية تنفيذ إجراءات التحسين وتقيم فعاليتها في تقليل الأخطاء والشكاوى.', 'تصميم آلية متابعة دورية لتنفيذ إجراءات التحسين مع تقييم مدى فعاليتها في تقليل الأخطاء والشكاوى.', 'تُتابع الجمعية تنفيذ إجراءات التحسين بانتظام مما يضمن فعالية الحلول وتقليل الأخطاء والشكاوى بشكل ملموس.', 'لا تُتابع الجمعية تنفيذ إجراءات التحسين أو لا تُقيم فعاليتها مما قد يؤدي إلى ضعف تأثير الحلول وعدم تحقيق الأهداف.'),
  (md5('cts-v0.2.1-item-319')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-52')::uuid, 319, 'تُوثق الجمعية جميع البيانات والإجراءات والتحسينات لضمان استدامة الجودة وتحقيق الشفافية.', 'إعداد نظام توثيق شامل لكل البيانات والإجراءات المتعلقة بالأخطاء والتحسينات مع تحديث السجلات بانتظام لضمان دقتها.', 'تُوثق الجمعية جميع البيانات والإجراءات والتحسينات مما يُعزز من الشفافية ويوفر مرجعًا دائمًا لتحسين الجودة.', 'لا تُوثق الجمعية البيانات والإجراءات بشكل كافٍ مما قد يؤدي إلى صعوبة تتبع التحسينات وضعف الشفافية.'),
  (md5('cts-v0.2.1-item-320')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-53')::uuid, 320, 'تُحدد الجمعية معايير واضحة لتقييم كفاءة العاملين والمتطوعين بناءً على دورهم في تقديم الخدمات.', 'إعداد معايير واضحة وشاملة لتقييم كفاءة العاملين والمتطوعين مع تدريب الفرق على تطبيقها لضمان التقييم الموضوعي.', 'تُحدد الجمعية معايير دقيقة وواضحة لتقييم كفاءة العاملين والمتطوعين مما يُسهم في تحسين الأداء وضمان جودة تقديم الخدمات.', 'لا تُحدد الجمعية معايير واضحة لتقييم كفاءة العاملين والمتطوعين مما قد يؤدي إلى غياب منهجية دقيقة لتقييم الأداء وتحسينه.'),
  (md5('cts-v0.2.1-item-321')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-53')::uuid, 321, 'تُعد الجمعية استبيانات أو أدوات مخصصة لقياس رضا المستفيدين عن الأداء.', 'تصميم استبيانات وأدوات مخصصة لقياس رضا المستفيدين عن أداء العاملين مع مراجعتها دورياً لضمان ملاءمتها.', 'تُطور الجمعية استبيانات وأدوات فعّالة لقياس رضا المستفيدين عن الأداء مما يُسهم في تحسين الخدمات بناءً على آراء المستفيدين.', 'لا تُعد الجمعية أدوات لقياس رضا المستفيدين مما قد يؤدي إلى غياب معلومات أساسية حول جودة الأداء ومدى تحقيق التوقعات.'),
  (md5('cts-v0.2.1-item-322')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-53')::uuid, 322, 'تُجمع الجمعية آراء المستفيدين بشكل منتظم عبر استبيانات مقابلات أو جلسات نقاش.', 'وضع خطة زمنية منتظمة لجمع آراء المستفيدين عن أداء العاملين عبر وسائل متنوعة مثل الاستبيانات والمقابلات لضمان شمولية النتائج.', 'تُجمع الجمعية آراء المستفيدين بشكل منتظم باستخدام وسائل متنوعة مما يُسهم في الحصول على ملاحظات دقيقة وشاملة لتحسين الأداء.', 'لا تجمع الجمعية آراء المستفيدين بشكل منتظم مما قد يؤدي إلى ضعف التواصل وفقدان فرص التحسين المستمر.'),
  (md5('cts-v0.2.1-item-323')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-53')::uuid, 323, 'تُقيس الجمعية مستوى ثقة المستفيدين ورضاهم عن أداء العاملين والمتطوعين باستخدام مؤشرات محددة.', 'تطوير مؤشرات واضحة ودقيقة لقياس رضا وثقة المستفيدين مع تدريب الفرق على استخدامها بشكل منتظم.', 'تُقيس الجمعية مستوى رضا وثقة المستفيدين باستخدام مؤشرات محددة مما يُمكّنها من تحسين الأداء بشكل مدروس.', 'لا تُقيس الجمعية رضا وثقة المستفيدين بمؤشرات محددة مما قد يؤدي إلى نقص في تحليل مستوى الأداء وتحديد النقاط التي تحتاج للتحسين.'),
  (md5('cts-v0.2.1-item-324')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-53')::uuid, 324, 'تُحلل الجمعية البيانات المستخلصة من آراء المستفيدين لتحديد نقاط القوة وفرص التحسين في الأداء.', 'تطوير نظام من أجل  التحليل المنتظم للبيانات المستخلصة من آراء المستفيدين مع تخصيص فرق لتحليلها وتقديم تقارير دورية.', 'تُحلل الجمعية البيانات المستخلصة من آراء المستفيدين بدقة مما يُسهم في تحديد نقاط القوة واستغلال فرص التحسين بشكل فعّال.', 'لا تُحلل الجمعية بيانات آراء المستفيدين بشكل منهجي مما قد يؤدي إلى تفويت فرص تحسين الأداء ومعالجة المشكلات.'),
  (md5('cts-v0.2.1-item-325')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-53')::uuid, 325, 'تُشارك الجمعية نتائج التقييم مع العاملين والمتطوعين لتعزيز الشفافية وتحفيز التحسين.', 'تصميم آلية لمشاركة نتائج التقييم مع العاملين والمتطوعين مع تقديم توصيات واضحة لتحسين الأداء.', 'تُشارك الجمعية نتائج التقييم مع العاملين والمتطوعين مما يعزز من الشفافية ويحفز على تحسين الأداء.', 'لا تُشارك الجمعية نتائج التقييم مع العاملين والمتطوعين مما قد يؤدي إلى ضعف في التواصل والتحفيز على تحسين الأداء.'),
  (md5('cts-v0.2.1-item-326')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-53')::uuid, 326, 'تُوثق الجمعية عمليات التقييم ونتائجها لضمان الاستمرارية والتحسين المستمر.', 'إنشاء نظام توثيق شامل لعمليات التقييم ونتائجها مع مراجعة السجلات دورياً لضمان دقتها وتحديثها.', 'تُوثق الجمعية جميع عمليات التقييم ونتائجها مما يضمن استمرارية العمليات ويوفر بيانات مرجعية للتحسين المستمر.', 'لا تُوثق الجمعية عمليات التقييم ونتائجها بشكل كافٍ مما قد يؤدي إلى صعوبة تتبع الأداء وضعف في تحسين العمليات.'),
  (md5('cts-v0.2.1-item-327')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-54')::uuid, 327, 'تُجمع الجمعية بيانات شاملة عن أداء العاملين وكفاءة العمليات وجودة الخدمات من خلال التقييمات الدورية.', 'إنشاء آلية واضحة ومنتظمة لجمع بيانات شاملة عن أداء العاملين وجودة الخدمات من خلال التقييمات الدورية مع تحديد المسؤوليات الزمنية.', 'الجمعية تُجمع بيانات شاملة ومنتظمة عن أداء العاملين وكفاءة العمليات وجودة الخدمات من خلال التقييمات الدورية مما يُسهم في تحسين الأداء العام', 'لا تُجمع الجمعية بيانات شاملة عن أداء العاملين وكفاءة العمليات وجودة الخدمات بشكل منتظم مما قد يؤدي إلى ضعف في تقييم الأداء وصعوبة تحسينه.'),
  (md5('cts-v0.2.1-item-328')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-54')::uuid, 328, 'تُحلل الجمعية البيانات لتحديد الدروس المستفادة من نقاط القوة والضعف في أداء الفريق والعمليات.', 'تطوير نظام تحليل بيانات شامل يُركز على تحديد الدروس المستفادة من نقاط القوة والضعف مع استخدام أدوات تحليل دقيقة وضمان توثيق النتائج.', 'الجمعية تُحلل البيانات بفعالية لتحديد الدروس المستفادة من نقاط القوة والضعف في أداء الفريق والعمليات مما يساعد على تطوير الأداء باستمرار.', 'لا تُحلل الجمعية البيانات بشكل كافٍ لتحديد الدروس المستفادة من نقاط القوة والضعف مما قد يؤدي إلى غياب فرص التحسين وتكرار الأخطاء.'),
  (md5('cts-v0.2.1-item-329')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-54')::uuid, 329, 'تُعد الجمعية سجلات توثيقية تحتوي على الدروس المستفادة بالتفصيل وأسبابها وتأثيرها.', 'إنشاء نظام توثيق شامل للدروس المستفادة يُركز على تحديد الأسباب والتأثيرات مع تحديث هذه السجلات بشكل دوري لضمان استمرارية المعرفة.', 'الجمعية تُعد سجلات توثيقية واضحة تحتوي على الدروس المستفادة بالتفصيل مع تحليل أسبابها وتأثيرها مما يُسهم في تعزيز المعرفة المؤسسية.', 'لا تُعد الجمعية سجلات توثيقية تحتوي على الدروس المستفادة بالتفصيل مما قد يؤدي إلى فقدان المعرفة وصعوبة الاستفادة من التجارب السابقة.'),
  (md5('cts-v0.2.1-item-330')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-54')::uuid, 330, 'تُشارك الجمعية الدروس المستفادة مع العاملين لتحفيز تحسين الأداء وتعزيز الشفافية.', 'وضع آلية فعّالة لمشاركة الدروس المستفادة مع العاملين بشكل دوري من خلال الاجتماعات أو التقارير لتحفيز التحسين وتعزيز الشفافية.', 'الجمعية تُشارك الدروس المستفادة مع العاملين بانتظام مما يُسهم في تحفيز تحسين الأداء وتعزيز روح الشفافية داخل المنظمة.', 'لا تُشارك الجمعية الدروس المستفادة مع العاملين مما قد يؤدي إلى ضعف في تحسين الأداء وغياب الشفافية.'),
  (md5('cts-v0.2.1-item-331')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-54')::uuid, 331, 'تُصمم الجمعية خططًا لتحسين أداء العاملين بناءً على الدروس المستفادة.', 'إعداد خطط تطويرية مُخصصة لتحسين أداء العاملين بناءً على الدروس المستفادة مع وضع أهداف واضحة ومؤشرات لقياس نجاح هذه الخطط.', 'الجمعية تُصمم خططًا فعّالة لتحسين أداء العاملين بناءً على الدروس المستفادة مما يُسهم في رفع كفاءة الموارد البشرية وتحقيق الأهداف.', 'لا تُصمم الجمعية خططًا لتحسين أداء العاملين بناءً على الدروس المستفادة مما قد يؤدي إلى استمرار نقاط الضعف وعدم تحقيق تحسين ملموس.'),
  (md5('cts-v0.2.1-item-332')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-54')::uuid, 332, 'تُتابع الجمعية تطبيق الدروس المستفادة وتقيم أثرها على الأداء العام وجودة العمليات.', 'إنشاء نظام متابعة دوري لتطبيق الدروس المستفادة وتقييم أثرها على الأداء العام وجودة العمليات مع إعداد تقارير دورية لقياس التحسن.', 'الجمعية تُتابع تطبيق الدروس المستفادة بانتظام وتقيم أثرها على الأداء العام وجودة العمليات مما يضمن تحقيق التحسين المستمر.', 'لا تُتابع الجمعية تطبيق الدروس المستفادة أو تقيم أثرها على الأداء مما قد يؤدي إلى عدم تحقيق التطوير المطلوب واستمرار الأثر السلبي.'),
  (md5('cts-v0.2.1-item-333')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-54')::uuid, 333, 'تُوثق الجمعية الدروس الجديدة بشكل مستمر لضمان تحقيق التحسين المستدام.', 'تطوير نظام توثيق مستمر للدروس الجديدة مع توفير آليات للوصول إليها بسهولة وتضمينها في خطط التحسين المستقبلية لضمان الاستدامة.', 'الجمعية تُوثق الدروس الجديدة بشكل مستمر مما يُسهم في تحقيق التحسين المستدام وضمان الاستفادة من التجارب السابقة.', 'لا تُوثق الجمعية الدروس الجديدة بشكل مستمر مما قد يؤدي إلى فقدان المعرفة وصعوبة تحسين العمليات بشكل دائم'),
  (md5('cts-v0.2.1-item-334')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-55')::uuid, 334, 'تُحدد الجمعية مؤشرات أداء واضحة ومرتبطة بأهداف العمليات والخدمات.', 'تطوير قائمة بمؤشرات أداء واضحة وذات صلة بأهداف العمليات والخدمات مع مراجعتها دوريًا لضمان توافقها مع الأهداف الاستراتيجية.', 'الجمعية تُحدد مؤشرات أداء واضحة ومرتبطة بأهداف العمليات والخدمات مما يسهم في قياس الأداء بدقة وتحقيق الأهداف الاستراتيجية.', 'لا تُحدد الجمعية مؤشرات أداء واضحة أو مرتبطة بأهداف العمليات والخدمات مما قد يؤدي إلى صعوبة قياس الأداء ومتابعة تحقيق الأهداف.'),
  (md5('cts-v0.2.1-item-335')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-55')::uuid, 335, 'تُعد الجمعية خططاً مكتوبة تتضمن آليات جمع البيانات وتحليلها لقياس مؤشرات الأداء.', 'إعداد خطط تفصيلية مكتوبة تتضمن إجراءات واضحة لجمع البيانات وتحليلها مع تحديد المسؤوليات والأهداف المرجوة.', 'الجمعية تُعد خططًا مكتوبة تتضمن آليات دقيقة لجمع البيانات وتحليلها مما يضمن قياس مؤشرات الأداء بشكل منهجي وفعّال.', 'لا تُعد الجمعية خططًا مكتوبة تتضمن آليات لجمع البيانات وتحليلها مما قد يؤدي إلى ضعف في منهجية قياس مؤشرات الأداء.'),
  (md5('cts-v0.2.1-item-336')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-55')::uuid, 336, 'تُحدد الجمعية مصادر موثوقة لجمع البيانات المتعلقة بمؤشرات الأداء مثل التقارير أو الاستبيانات.', 'تحديد واعتماد مصادر موثوقة لجمع البيانات المتعلقة بمؤشرات الأداء مع توثيق هذه المصادر لضمان سهولة الوصول إليها واستخدامها.', 'الجمعية تُحدد مصادر موثوقة لجمع البيانات المتعلقة بمؤشرات الأداء مما يضمن توفير بيانات دقيقة وذات جودة عالية لقياس الأداء.', 'لا تُحدد الجمعية مصادر موثوقة لجمع البيانات المتعلقة بمؤشرات الأداء مما قد يؤدي إلى ضعف جودة البيانات وصعوبة الاعتماد عليها.'),
  (md5('cts-v0.2.1-item-337')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-55')::uuid, 337, 'تُحدد الجمعية فترات زمنية منتظمة لقياس المؤشرات وتحليلها مثل شهريًا أو ربع سنويًا.', 'وضع جدول زمني منتظم لقياس مؤشرات الأداء وتحليلها مثل شهريًا أو ربع سنويًا مع متابعة الالتزام به لضمان استمرارية التقييم', 'الجمعية تُحدد فترات زمنية منتظمة لقياس مؤشرات الأداء وتحليلها مما يساعد في متابعة الأداء بشكل دوري واتخاذ قرارات مستنيرة.', 'لا تُحدد الجمعية فترات زمنية منتظمة لقياس المؤشرات وتحليلها مما قد يؤدي إلى عدم انتظام التقييم وصعوبة متابعة الأداء.'),
  (md5('cts-v0.2.1-item-338')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-55')::uuid, 338, 'تُبلغ الجمعية العاملين والمتطوعين بأهداف القياس وأهمية دورهم في جمع البيانات.', 'وضع آلية تواصل فعّالة لتوضيح أهداف القياس ودور العاملين والمتطوعين في جمع البيانات مع تقديم أمثلة عملية على أهمية مساهمتهم.', 'الجمعية تُبلغ العاملين والمتطوعين بأهداف القياس وأهمية دورهم في جمع البيانات مما يُعزز وعيهم والتزامهم بالمساهمة في تحقيق الأهداف.', 'لا تُبلغ الجمعية العاملين والمتطوعين بأهداف القياس أو أهمية دورهم في جمع البيانات مما قد يؤدي إلى ضعف في المشاركة وتأثير سلبي على جودة البيانات.'),
  (md5('cts-v0.2.1-item-339')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-55')::uuid, 339, 'تُوفر الجمعية تدريباً للعاملين والمتطوعين حول آليات جمع البيانات وضمان دقتها.', 'تصميم برامج تدريبية مخصصة للعاملين والمتطوعين حول آليات جمع البيانات وضمان دقتها مع توفير أمثلة عملية ودعم مستمر.', 'الجمعية تُقدم تدريبًا عمليًا للعاملين والمتطوعين حول آليات جمع البيانات وضمان دقتها مما يُسهم في تحسين جودة البيانات المجمعة.', 'لا تُوفر الجمعية تدريبًا كافيًا للعاملين والمتطوعين حول آليات جمع البيانات مما قد يؤدي إلى ضعف في دقة البيانات المجمعة وجودتها.'),
  (md5('cts-v0.2.1-item-340')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-55')::uuid, 340, 'تُراجع الجمعية مؤشرات الأداء وخطط القياس بشكل دوري للتأكد من مواءمتها مع الأهداف الحالية.', 'إعداد جدول زمني دوري لمراجعة مؤشرات الأداء وخطط القياس مع إشراك الفرق المعنية لضمان توافقها مع الأهداف الاستراتيجية الحالية.', 'الجمعية تُراجع مؤشرات الأداء وخطط القياس بشكل دوري لضمان مواءمتها مع الأهداف الحالية مما يُسهم في تحسين الأداء وتحقيق الأهداف.', 'لا تُراجع الجمعية مؤشرات الأداء وخطط القياس بشكل دوري مما قد يؤدي إلى عدم توافقها مع الأهداف الحالية وضعف في تحقيق النتائج المرجوة.'),
  (md5('cts-v0.2.1-item-341')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-56')::uuid, 341, 'تُحلل الجمعية البيانات لتحديد مدى تحقيق الأهداف وكشف أي انحرافات في الأداء.', 'تطوير آلية تحليل بيانات شاملة ومنتظمة لتقييم مدى تحقيق الأهداف وكشف الانحرافات مع تدريب الفرق على كيفية استخدام أدوات التحليل بكفاءة.', 'الجمعية تُظهر التزامًا بتحليل البيانات بشكل منتظم لتحديد مدى تحقيق الأهداف وكشف الانحرافات في الأداء مما يُسهم في تحسين التخطيط واتخاذ القرارات المبنية على الأدلة.', 'لا تقوم الجمعية بتحليل البيانات بشكل منتظم أو دقيق لتحديد مدى تحقيق الأهداف وكشف الانحرافات مما قد يؤدي إلى ضعف في تقييم الأداء وتصحيح المسار.'),
  (md5('cts-v0.2.1-item-342')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-56')::uuid, 342, 'تُعد الجمعية تقارير تحليلية دورية تلخص نتائج تحليل البيانات والانحرافات المكتشفة.', 'إعداد تقارير تحليلية دورية تلخص نتائج تحليل البيانات والانحرافات المكتشفة مع التأكد من تقديمها في الوقت المناسب لجميع الأطراف المعنية.', 'الجمعية تُعد تقارير تحليلية دورية تحتوي على ملخص لنتائج تحليل البيانات والانحرافات مما يُسهم في تحسين الشفافية واتخاذ قرارات مستنيرة.', 'لا تُعد الجمعية تقارير تحليلية دورية تلخص نتائج تحليل البيانات والانحرافات مما قد يؤدي إلى غياب رؤية واضحة عن الأداء.'),
  (md5('cts-v0.2.1-item-343')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-56')::uuid, 343, 'تُحدد الجمعية خططًا وإجراءات لمعالجة الانحرافات المكتشفة وضمان العودة إلى المسار الصحيح.', 'تطوير خطة عمل واضحة لمعالجة الانحرافات المكتشفة أثناء تقييم العمليات مع تحديد الإجراءات اللازمة لضمان العودة إلى المسار الصحيح وتحقيق الأهداف', 'الجمعية تُظهر استجابة فعّالة من خلال تحديد خطط وإجراءات لمعالجة الانحرافات المكتشفة مما يضمن تصحيح المسار وتحقيق الأهداف.', 'لا تُحدد الجمعية خططًا أو إجراءات واضحة لمعالجة الانحرافات المكتشفة مما قد يؤدي إلى استمرار المشكلات وضعف الأداء.'),
  (md5('cts-v0.2.1-item-344')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-56')::uuid, 344, 'تُحدد الجمعية المسؤوليات والجدول الزمني لتنفيذ الإجراءات التصحيحية.', 'إعداد جدول زمني واضح مع تحديد المسؤوليات لكل فريق أو فرد لتنفيذ الإجراءات التصحيحية ومتابعة التقدم لضمان الالتزام بالخطة.', 'الجمعية تُحدد المسؤوليات والجدول الزمني لتنفيذ الإجراءات التصحيحية مما يُسهم في تحسين التنسيق وضمان تنفيذ الإجراءات في الوقت المحدد.', 'لا تُحدد الجمعية المسؤوليات أو الجدول الزمني لتنفيذ الإجراءات التصحيحية مما قد يؤدي إلى تأخير أو عدم كفاءة في تنفيذ التصحيحات.'),
  (md5('cts-v0.2.1-item-345')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-56')::uuid, 345, 'تُتابع الجمعية تطبيق الإجراءات التصحيحية بانتظام لضمان تحقيق النتائج المرجوة.', 'إنشاء نظام متابعة دوري لمراقبة تطبيق الإجراءات التصحيحية مع إعداد تقارير دورية لتقييم التقدم وضمان تحقيق الأهداف.', 'الجمعية تُظهر التزامًا قويًا بمتابعة تطبيق الإجراءات التصحيحية بانتظام مما يضمن تحقيق النتائج المرجوة وتحسين الأداء.', 'لا تُتابع الجمعية تطبيق الإجراءات التصحيحية بانتظام مما قد يؤدي إلى ضعف في تحقيق النتائج المرجوة واستمرار الانحرافات.'),
  (md5('cts-v0.2.1-item-346')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-56')::uuid, 346, 'تُقيم الجمعية أثر الإجراءات التصحيحية على الأداء وتوثق الدروس المستفادة لتحسين العمليات المستقبلية.', 'وضع آلية لتقييم أثر الإجراءات التصحيحية على أداء العمليات مع تخصيص جلسات دورية لتوثيق الدروس المستفادة وتضمينها في خطط العمليات المستقبلية.', 'الجمعية تُقيم أثر الإجراءات التصحيحية على الأداء بشكل منهجي وتوثق الدروس المستفادة لتحسين العمليات المستقبلية مما يعزز التعلم المؤسسي.', 'لا تُقيم الجمعية أثر الإجراءات التصحيحية على الأداء أو تُوثق الدروس المستفادة مما قد يؤدي إلى تكرار الأخطاء وضعف التحسين المستقبلي.'),
  (md5('cts-v0.2.1-item-347')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-56')::uuid, 347, 'تُوثق الجمعية جميع البيانات والتحليلات والإجراءات التصحيحية المتخذة لضمان الشفافية والتحسين المستمر.', 'إنشاء نظام توثيق مركزي لجميع البيانات والتحليلات والإجراءات التصحيحية مع مراجعة دورية للتأكد من دقة المعلومات وكفاءتها في دعم التحسين المستمر.', 'الجمعية تُوثق جميع البيانات والتحليلات والإجراءات التصحيحية بشكل شامل مما يُعزز الشفافية ويُسهم في تحقيق التحسين المستمر.', 'لا تُوثق الجمعية جميع البيانات والتحليلات أو الإجراءات التصحيحية المتخذة مما قد يؤدي إلى ضعف في الشفافية وصعوبة مراجعة الأداء وتحسينه.'),
  (md5('cts-v0.2.1-item-348')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-56')::uuid, 348, 'تُعد الجمعية تقارير دورية مفصلة تلخص أداء العمليات وتوضح الإنجازات والتحديات.', 'إنشاء نظام لإعداد تقارير دورية مفصلة تشمل أداء العمليات والإنجازات والتحديات مع وضع جدول زمني منتظم لإصدار التقارير.', 'الجمعية تُعد تقارير دورية مفصلة تلخص أداء العمليات بوضوح مع تسليط الضوء على الإنجازات والتحديات مما يُسهم في تحسين التخطيط واتخاذ القرارات.', 'لا تُعد الجمعية تقارير دورية مفصلة تلخص أداء العمليات مما قد يؤدي إلى غياب رؤية واضحة عن الإنجازات والتحديات.'),
  (md5('cts-v0.2.1-item-349')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-57')::uuid, 349, 'تُحلل التقارير أداء العمليات وتُقارن النتائج بين الفترات الزمنية المختلفة لتحديد التغيرات والاتجاهات.', 'تطوير آلية تحليل دورية لمقارنة نتائج أداء العمليات بين الفترات الزمنية المختلفة مع استخدام أدوات تحليل فعالة لتحديد التغيرات والاتجاهات.', 'الجمعية تُحلل أداء العمليات بشكل منهجي من خلال مقارنة النتائج بين الفترات الزمنية المختلفة مما يساعد في تحديد التغيرات والاتجاهات لتحسين الأداء.', 'لا تُحلل الجمعية أداء العمليات بشكل شامل ولا تُقارن النتائج بين الفترات الزمنية المختلفة مما قد يؤدي إلى ضعف في تحديد التغيرات والاتجاهات'),
  (md5('cts-v0.2.1-item-350')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-57')::uuid, 350, 'تُحدد المنظمة الاتجاهات الإيجابية أو السلبية في الأداء بناءً على البيانات المُجمعة وتحليلها.', 'إنشاء نظام تحليل بيانات مُحكم يُركز على تحديد الاتجاهات الإيجابية والسلبية في أداء العمليات مع إعداد تقارير واضحة تُبرز النتائج.', 'الجمعية تُظهر قدرة عالية على تحديد الاتجاهات الإيجابية والسلبية في الأداء بناءً على البيانات المُجمعة وتحليلها مما يُسهم في اتخاذ قرارات مبنية على البيانات.', 'لا تُحدد الجمعية الاتجاهات الإيجابية أو السلبية في الأداء بشكل منهجي مما قد يؤدي إلى فقدان فرص التحسين أو تصحيح الأخطاء.'),
  (md5('cts-v0.2.1-item-351')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-57')::uuid, 351, 'تُشارك الجمعية التقارير الدورية مع أصحاب المصلحة الداخليين والخارجيين لتعزيز الشفافية وبناء الثقة.', 'تصميم استراتيجية واضحة لمشاركة التقارير الدورية عن أداء العمليات مع أصحاب المصلحة الداخليين والخارجيين مع تحديد قنوات الاتصال المناسبة', 'الجمعية تُشارك التقارير الدورية مع أصحاب المصلحة الداخليين والخارجيين مما يُعزز الشفافية ويُسهم في بناء الثقة ودعم التعاون.', 'لا تُشارك الجمعية التقارير الدورية مع أصحاب المصلحة الداخليين والخارجيين مما قد يؤدي إلى ضعف في بناء الشفافية والثقة.'),
  (md5('cts-v0.2.1-item-352')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-57')::uuid, 352, 'تُوثق الجمعية جميع التقارير الدورية وتعليقات أصحاب المصلحة لضمان المتابعة وتحسين العمليات.', 'إنشاء نظام أرشفة شامل لتوثيق التقارير الدورية عن أداء العمليات وتعليقات أصحاب المصلحة مع مراجعة هذه الوثائق دوريًا لتحسين العمليات.', 'الجمعية تُوثق جميع التقارير الدورية وتعليقات أصحاب المصلحة مما يُسهم في ضمان المتابعة وتحقيق تحسين مستمر للعمليات.', 'لا تُوثق الجمعية التعليقات أو التقارير الدورية بشكل منهجي مما قد يؤدي إلى ضعف في المتابعة وصعوبة تحسين العمليات.'),
  (md5('cts-v0.2.1-item-353')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-57')::uuid, 353, 'تُراجع الجمعية منهجية إعداد التقارير بشكل دوري لتحسين دقتها وفائدتها.', 'وضع جدول زمني دوري لمراجعة منهجية إعداد التقارير عن أداء العمليات مع إشراك الفرق المعنية وأصحاب المصلحة لتحسين دقة وفائدة التقارير.', 'الجمعية تُراجع منهجية إعداد التقارير بشكل دوري مما يضمن تحسين دقتها وفائدتها بما يتماشى مع احتياجات أصحاب المصلحة.', 'لا تُراجع الجمعية منهجية إعداد التقارير بشكل منتظم مما قد يؤدي إلى تكرار الأخطاء أو قلة فائدة التقارير المقدمة.'),
  (md5('cts-v0.2.1-item-354')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-57')::uuid, 354, 'تُحدد الجمعية مؤشرات واضحة وقابلة للقياس لقياس مخرجات البرامج والخدمات.', 'إعداد قائمة بمؤشرات أداء محددة وواضحة وقابلة للقياس لتقييم مخرجات البرامج والخدمات مع التأكد من توافقها مع الأهداف العامة للجمعية.', 'الجمعية تتميز بتحديد مؤشرات واضحة وقابلة للقياس لقياس مخرجات البرامج والخدمات مما يعزز القدرة على تقييم الأداء وتحقيق الأهداف المحددة.', 'لا تُحدد الجمعية مؤشرات واضحة وقابلة للقياس لقياس مخرجات البرامج والخدمات مما قد يؤدي إلى صعوبة تقييم الأداء بدقة.'),
  (md5('cts-v0.2.1-item-355')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-58')::uuid, 355, 'تُحدد الجمعية مؤشرات نتائج واضحة لقياس تأثير البرامج والخدمات على حياة المستفيدين.', 'تطوير مؤشرات نتائج دقيقة وقابلة للقياس لقياس تأثير البرامج والخدمات على حياة المستفيدين مع إشراك ذوي العلاقة لضمان شمولية المؤشرات.', 'الجمعية تُظهر التزامًا بتحديد مؤشرات نتائج واضحة لقياس تأثير البرامج والخدمات على حياة المستفيدين مما يساعد في قياس الأثر الحقيقي للبرامج.', 'لا تُحدد الجمعية مؤشرات نتائج واضحة لقياس تأثير البرامج والخدمات على حياة المستفيدين مما قد يؤدي إلى ضعف في معرفة الأثر الفعلي للبرامج.'),
  (md5('cts-v0.2.1-item-356')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-58')::uuid, 356, 'تُطور الجمعية خطة تقييم تُحدد فيها آليات قياس المؤشرات والبيانات المطلوبة.', 'إعداد خطة تقييم شاملة تُحدد فيها آليات دقيقة لجمع البيانات وتحليلها بما يتوافق مع المؤشرات المحددة لتقييم النتائج مع مراجعة الخطة بشكل دوري.', 'الجمعية تُظهر احترافية من خلال تطوير خطة تقييم شاملة تُحدد فيها آليات قياس المؤشرات والبيانات المطلوبة مما يُسهل عملية التقييم المستمر.', 'لا تُطور الجمعية خطة تقييم تُحدد فيها آليات قياس المؤشرات والبيانات المطلوبة مما قد يؤدي إلى ضعف في تنظيم عملية التقييم.'),
  (md5('cts-v0.2.1-item-357')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-58')::uuid, 357, 'تُوضح الجمعية في خطة التقييم الأدوار والمسؤوليات لكل فريق أو فرد معني بجمع وتحليل البيانات.', 'إنشاء خطة تقييم تُحدد بوضوح أدوار ومسؤوليات الفرق والأفراد المعنيين بجمع وتحليل البيانات المتعلقة بتحقيق النتائج مع توثيق هذه التوجيهات لضمان الالتزام بها.', 'الجمعية تُوضح بوضوح في خطة التقييم الأدوار والمسؤوليات لكل فريق أو فرد معني بجمع وتحليل البيانات مما يعزز التنسيق والكفاءة.', 'لا تُوضح الجمعية في خطة التقييم الأدوار والمسؤوليات لكل فريق أو فرد مما قد يؤدي إلى تداخل المهام أو نقص في تنفيذها.'),
  (md5('cts-v0.2.1-item-358')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-58')::uuid, 358, 'تُحدد الجمعية دورية منتظمة لجمع البيانات وتحليلها مثل أسبوعياً وشهريًا وربعياً.', 'وضع جدول زمني دوري لجمع البيانات المتعلقة بتحقيق النتائج وتحليلها مثل أسبوعيًا أو شهريًا أو ربعياً مع التأكيد على الالتزام بالدورية المحددة.', 'الجمعية تعتمد دورية منتظمة لجمع البيانات وتحليلها مما يضمن استمرارية التقييم وتحقيق تحسين مستمر في الأداء.', 'لا تُحدد الجمعية دورية منتظمة لجمع البيانات وتحليلها مما قد يؤدي إلى عدم انتظام التقييم وصعوبة متابعة الأداء بشكل مستمر.'),
  (md5('cts-v0.2.1-item-359')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-58')::uuid, 359, 'تُختار الجمعية أدوات مناسبة لجمع البيانات مثل استبيانات أو مقابلات أو تقارير.', 'اختيار الأدوات الأنسب لجمع البيانات ذات الصلة بتحقيق النتائج المستهدفة بناءً على طبيعة البرامج والمؤشرات المحددة مع تدريب العاملين على استخدام هذه الأدوات بكفاءة', 'الجمعية تختار أدوات فعالة ومناسبة لجمع البيانات مثل الاستبيانات والمقابلات والتقارير مما يضمن دقة وموثوقية البيانات المجمعة.', 'لا تُحدد الجمعية الأدوات المناسبة لجمع البيانات مما قد يؤدي إلى ضعف في جودة البيانات المجمعة وعدم ملاءمتها للتحليل.'),
  (md5('cts-v0.2.1-item-360')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-58')::uuid, 360, 'تُحدد الجمعية النتائج المرجوة من برامجها وخدماتها وتأثيرها على المستفيدين بوضوح.', 'إنشاء إطار عمل واضح ومحدد لتحديد النتائج المرجوة من البرامج والخدمات مع إشراك جميع الأطراف المعنية لضمان توافق الأهداف مع احتياجات المستفيدين.', 'الجمعية تُظهر التزامًا كبيرًا بتحديد النتائج المرجوة من برامجها وخدماتها وتأثيرها على المستفيدين بوضوح مما يساهم في تحسين التخطيط وتحقيق الأهداف.', 'لا تُحدد الجمعية بوضوح النتائج المرجوة من برامجها وخدماتها وتأثيرها على المستفيدين مما قد يؤدي إلى غموض الرؤية وصعوبة قياس النجاح.'),
  (md5('cts-v0.2.1-item-361')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-59')::uuid, 361, 'تُعد الجمعية مواد توعوية تتضمن شرحًا لأهداف البرامج ونتائجها المرجوة على المستفيدين.', 'تصميم مواد توعوية متكاملة وبسيطة تشرح أهداف البرامج ونتائجها المرجوة مع التركيز على استخدام وسائل تواصل متنوعة للوصول إلى جميع المستفيدين.', 'الجمعية تُعد مواد توعوية شاملة تسلط الضوء على أهداف البرامج ونتائجها المرجوة مما يعزز وعي المستفيدين بأهمية البرامج وقيمتها.', 'لا تُعد الجمعية مواد توعوية كافية لشرح أهداف البرامج ونتائجها المرجوة مما قد يؤدي إلى ضعف في توصيل الرسالة للمستفيدين.'),
  (md5('cts-v0.2.1-item-362')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-59')::uuid, 362, 'تُنظم الجمعية جلسات تعريفية للعاملين والمتطوعين لشرح الأهداف والنتائج المتوقعة.', 'وضع جدول زمني منتظم لعقد جلسات تعريفية للعاملين والمتطوعين مع التركيز على شرح الأهداف والنتائج المتوقعة لضمان وضوح الرؤية.', 'الجمعية تُنظم جلسات تعريفية دورية للعاملين والمتطوعين لشرح الأهداف والنتائج المتوقعة مما يساهم في تحقيق فهم مشترك وتعزيز التنسيق.', 'لا تُنظم الجمعية جلسات تعريفية كافية للعاملين والمتطوعين مما قد يؤدي إلى ضعف في فهم الأهداف والنتائج المتوقعة وتأثير ذلك على الأداء.'),
  (md5('cts-v0.2.1-item-363')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-59')::uuid, 363, 'تُوضح الجمعية للعاملين والمتطوعين أهمية جمع البيانات ودورها في قياس النجاح وتحسين الأداء.', 'تنظيم ورش عمل توعوية للعاملين والمتطوعين لشرح أهمية جمع البيانات ودورها في تحسين الأداء وقياس النجاح مع تقديم أمثلة عملية.', 'الجمعية تُظهر اهتمامًا كبيرًا بتوضيح أهمية جمع البيانات للعاملين والمتطوعين مما يعزز وعيهم بدورها في قياس النجاح وتحسين الأداء.', 'لا تُوضح الجمعية بشكل كافٍ للعاملين والمتطوعين أهمية جمع البيانات مما قد يؤدي إلى ضعف في الالتزام بجمع البيانات وتحليلها.'),
  (md5('cts-v0.2.1-item-364')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-59')::uuid, 364, 'تُوفر الجمعية تدريبًا عمليًا على آليات جمع البيانات بما يتوافق مع مؤشرات الأداء المحددة.', 'تصميم برنامج تدريبي عملي لتعليم العاملين والمتطوعين كيفية جمع البيانات بناءً على مؤشرات الأداء لقياس النتائج مع متابعة دورية لتقييم جودة التنفيذ.', 'الجمعية تُقدم تدريبًا عمليًا شاملًا للعاملين والمتطوعين على آليات جمع البيانات بما يتوافق مع مؤشرات الأداء مما يضمن جودة البيانات ودقتها.', 'لا تُوفر الجمعية تدريبًا كافيًا على آليات جمع البيانات بما يتوافق مع مؤشرات الأداء مما قد يؤدي إلى ضعف في جودة البيانات المجمعة.'),
  (md5('cts-v0.2.1-item-365')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-59')::uuid, 365, 'تُقدم الجمعية إرشادات حول كيفية تحليل البيانات لفهم تأثير البرامج على المستفيدين.', 'إعداد دليل إرشادي مفصل لتحليل البيانات لفهم تأثير البرامج على المستفيدين مع تقديم تدريب عملي للعاملين على استخدام هذه الإرشادات.', 'الجمعية تُقدم إرشادات واضحة حول كيفية تحليل البيانات لفهم تأثير البرامج على المستفيدين مما يساهم في تعزيز دقة التقييم واتخاذ القرارات.', 'لا تُقدم الجمعية إرشادات كافية حول كيفية تحليل البيانات مما قد يؤدي إلى ضعف في تقييم تأثير البرامج على المستفيدين.'),
  (md5('cts-v0.2.1-item-366')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-59')::uuid, 366, 'تُوثق الجمعية جميع جلسات التوعية والتدريب والتقارير لضمان استمرارية التحسين.', 'إنشاء نظام توثيق شامل لجميع جلسات التوعية والتدريب والتقارير مع التأكد من تحديث السجلات بشكل دوري وضمان سهولة الوصول إليها.', 'الجمعية تُظهر التزامًا كبيرًا باستمرارية التحسين من خلال توثيق جميع جلسات التوعية والتدريب والتقارير مما يسهل الرجوع إليها في المستقبل.', 'لا تُوثق الجمعية جميع جلسات التوعية والتدريب والتقارير بشكل منتظم مما قد يؤدي إلى فقدان المعلومات المهمة وصعوبة تحسين العمليات.'),
  (md5('cts-v0.2.1-item-367')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-59')::uuid, 367, 'أنشأت الجمعية آلية لتوثيق الإخفاقات التي واجهتها وقصص النجاح التي تحققت أثناء تنفيذ البرامج وتقديم الخدمات.', 'تصميم وتنفيذ آلية شاملة لتوثيق الإخفاقات وقصص النجاح أثناء تنفيذ البرامج والخدمات مع تدريب الفرق على استخدامها بفعالية.', 'الجمعية تمتلك آلية فعّالة لتوثيق الإخفاقات التي واجهتها وقصص النجاح المحققة أثناء تنفيذ البرامج مما يساهم في تعزيز التعلم المؤسسي وتحسين العمليات المستقبلية.', 'لا تمتلك الجمعية آلية واضحة ومحددة لتوثيق الإخفاقات وقصص النجاح مما قد يؤدي إلى فقدان فرص التعلم والاستفادة من التجارب السابقة.'),
  (md5('cts-v0.2.1-item-368')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-60')::uuid, 368, 'تُعد الجمعية تقارير مفصلة تتضمن المخرجات والنتائج إلى جانب الإخفاقات والدروس المستفادة وقصص النجاح.', 'وضع إطار عمل موحد لإعداد تقارير مفصلة تشمل المخرجات والإخفاقات والدروس المستفادة مع التأكد من مراجعتها ومشاركتها بشكل منتظم.', 'الجمعية تُظهر احترافية عالية من خلال إعداد تقارير مفصلة وشاملة تتضمن المخرجات والنتائج مع توثيق الإخفاقات والدروس المستفادة وقصص النجاح.', 'لا تُعد الجمعية تقارير مفصلة تحتوي على المخرجات والنتائج والدروس المستفادة وقصص النجاح مما قد يؤدي إلى ضعف في توثيق الأداء وتحليل العمليات.'),
  (md5('cts-v0.2.1-item-369')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-60')::uuid, 369, 'تُشارك الجمعية تقارير النتائج بشكل دوري مع أصحاب المصلحة لتعزيز الشفافية وبناء الثقة.', 'تطوير جدول زمني دوري لمشاركة تقارير النتائج مع أصحاب المصلحة مع ضمان وضوح التقارير وسهولة فهمها لتعزيز الشفافية.', 'الجمعية تُظهر التزامًا بالشفافية من خلال مشاركة تقارير النتائج بشكل دوري مع أصحاب المصلحة مما يعزز بناء الثقة وتحسين التعاون.', 'لا تُشارك الجمعية تقارير النتائج بشكل دوري مع أصحاب المصلحة مما قد يؤدي إلى ضعف الشفافية وتقليل الثقة بين الأطراف المعنية.'),
  (md5('cts-v0.2.1-item-370')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-60')::uuid, 370, 'لدى الجمعية آلية لجمع ملاحظات أصحاب المصلحة حول التقارير المقدمة لتحسين جودة التقارير والعمليات.', 'إنشاء آلية لجمع ملاحظات أصحاب المصلحة حول تقارير النتائج المقدمة من خلال استبيانات أو اجتماعات دورية لضمان تحسين جودة التقارير والعمليات.', 'الجمعية تمتلك آلية فعّالة لجمع ملاحظات أصحاب المصلحة حول التقارير المقدمة مما يساهم في تحسين جودة التقارير وتطوير العمليات بشكل مستمر.', 'لا توجد لدى الجمعية آلية لجمع ملاحظات أصحاب المصلحة حول التقارير المقدمة مما قد يؤدي إلى ضعف في تحسين جودة التقارير والخدمات.'),
  (md5('cts-v0.2.1-item-371')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-60')::uuid, 371, 'تُوثق الجمعية جميع البيانات المجمعة والتحليلات والتقارير لضمان حفظها واستخدامها في المستقبل.', 'تطوير نظام أرشفة موحد لتوثيق جميع البيانات المجمعة والتحليلات والتقارير مع ضمان تحديثها دوريًا وإتاحتها للفِرق المعنية.', 'الجمعية تُظهر التزامًا قويًا بالاستدامة من خلال توثيق جميع البيانات المجمعة والتحليلات والتقارير مما يضمن سهولة الرجوع إليها واستخدامها في التخطيط المستقبلي.', 'لا تقوم الجمعية بتوثيق البيانات المجمعة والتحليلات والتقارير بشكل كافٍ مما قد يؤدي إلى فقدان المعلومات الحيوية وصعوبة الرجوع إليها لاحقًا.'),
  (md5('cts-v0.2.1-item-372')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-60')::uuid, 372, 'تُستخلص الجمعية الدروس المستفادة من النجاحات والإخفاقات في تنفيذ البرامج والخدمات.', 'وضع آلية فعّالة ومنظمة لاستخلاص الدروس المستفادة من النجاحات والإخفاقات في تنفيذ البرامج والخدمات مع تخصيص فرق عمل مسؤولة عن تحليل الأداء وتوثيق النتائج.', 'الجمعية تُظهر كفاءة عالية في استخلاص الدروس المستفادة من النجاحات والإخفاقات مما يساهم في تعزيز عملية التعلم المؤسسي وتحسين الأداء المستمر.', 'لا تستخلص الجمعية الدروس المستفادة من النجاحات والإخفاقات مما قد يؤدي إلى تكرار الأخطاء والحد من فرص التحسين المستقبلي.'),
  (md5('cts-v0.2.1-item-373')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-61')::uuid, 373, 'تُعد الجمعية سجلات منظمة تحتوي على الدروس المستفادة من تحليل النتائج.', 'إعداد نظام توثيق مُحكم ومنظم لتسجيل الدروس المستفادة من تحليل النتائج مع ضمان سهولة الوصول إليها واستخدامها بشكل مستمر من قبل العاملين لتحسين الأداء.', 'إعداد سجلات منظمة ومفصلة يُسهم في توثيق الدروس المستفادة بشكل منهجي ودقيق.', 'لا تحتفظ الجمعية بسجلات منظمة تحتوي على الدروس المستفادة من تحليل النتائج مما قد يؤدي إلى فقدان البيانات المهمة التي يمكن أن تدعم التحسين المستقبلي.'),
  (md5('cts-v0.2.1-item-374')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-61')::uuid, 374, 'تُشارك الجمعية الدروس المستفادة مع الفرق العاملة لتعزيز الفهم المشترك والتحسين الجماعي.', 'تصميم آلية فعّالة لمشاركة الدروس المستفادة مع الفرق العاملة من خلال الاجتماعات الدورية ورش العمل أو النشرات الداخلية لتعزيز التعاون وتشجيع التحسين الجماعي.', 'الجمعية تُظهر التزامًا قويًا بتعزيز التعاون من خلال مشاركة الدروس المستفادة مع جميع الفرق العاملة مما يعزز الفهم المشترك والتحسين الجماعي.', 'لا تُشارك الجمعية الدروس المستفادة بشكل كافٍ مع الفرق العاملة مما يحد من فرص التحسين الجماعي وتعزيز الفهم المشترك.'),
  (md5('cts-v0.2.1-item-375')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-61')::uuid, 375, 'تُستخدم النتائج المُوثقة من الإخفاقات والنجاحات لتطوير البرامج وتحسين الأداء المستقبلي.', 'إنشاء آلية لتطبيق النتائج المُوثقة من النجاحات والإخفاقات في تطوير البرامج والخدمات مع تحديد مسؤوليات واضحة لفريق العمل لمتابعة التنفيذ والتأكد من تحقيق الأهداف.', 'الجمعية تستفيد من النتائج المُوثقة للإخفاقات والنجاحات كأداة أساسية لتطوير البرامج وتحسين الأداء المستقبلي', 'لا تُستخدم النتائج المُوثقة من الإخفاقات والنجاحات بشكل كافٍ في تطوير البرامج مما قد يؤدي إلى تكرار الأخطاء وضعف التحسين المستقبلي.'),
  (md5('cts-v0.2.1-item-376')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-61')::uuid, 376, 'تُحدث الجمعية الإجراءات التشغيلية بناءً على الدروس المستفادة لضمان تجنب التحديات السابقة.', 'تطبيق نظام دوري لمراجعة الإجراءات التشغيلية وتحديثها بناءً على الدروس المستفادة مع توثيق كافة التحديثات وإبلاغ الفرق المعنية لضمان التنفيذ الفعّال للبرامج والخدمات.', 'الجمعية تقوم بتحديث الإجراءات التشغيلية بناءً على الدروس المستفادة لضمان تجنب تكرار التحديات السابقة وتحقيق تحسين مستمر.', 'لا تُحدث الجمعية الإجراءات التشغيلية بناءً على الدروس المستفادة مما قد يؤدي إلى استمرار التحديات السابقة دون حلول فعّالة.'),
  (md5('cts-v0.2.1-item-377')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-61')::uuid, 377, 'تُتابع الجمعية تنفيذ التحسينات الناتجة عن الدروس المستفادة وتقيم أثرها على جودة البرامج والخدمات.', 'وضع نظام متابعة دقيق لتنفيذ التحسينات الناتجة عن الدروس المستفادة مع تحديد مؤشرات أداء واضحة لقياس الأثر على جودة البرامج والخدمات.', 'الجمعية تُظهر حرصها على متابعة تنفيذ التحسينات الناتجة عن الدروس المستفادة وتقييم أثرها على جودة البرامج والخدمات لتحقيق أهدافها بكفاءة', 'لا تتابع الجمعية تنفيذ التحسينات الناتجة عن الدروس المستفادة بشكل كافٍ مما يقلل من فرص ضمان تحسين جودة البرامج والخدمات.'),
  (md5('cts-v0.2.1-item-378')::uuid, md5('cts-v0.2.1')::uuid, md5('cts-v0.2.1-indicator-61')::uuid, 378, 'تُوثق الجمعية جميع الإجراءات التي تمت بناءً على الدروس المستفادة لضمان استدامة التحسين.', 'تصميم نظام توثيق شامل لجميع الإجراءات التي تمت بناءً على الدروس المستفادة مع توفير تدريب عملي للموظفين لضمان التزامهم بالتوثيق المستمر وتحقيق التحسين المستدام للبرامج والخدمات.', 'الجمعية تُظهر التزامًا بالتحسين المستدام من خلال توثيق جميع الإجراءات التي تمت بناءً على الدروس المستفادة مما يضمن تحسينًا طويل الأمد', 'لا تُوثق الجمعية الإجراءات التي تمت بناءً على الدروس المستفادة مما قد يؤدي إلى ضعف الاستدامة في التحسين وعدم القدرة على البناء على الإنجازات السابقة.')
